window.EXAM_DATA = {"meta":{"title":"00037《美学》历年真题","periods":21,"choice":665,"essay":189,"first":"1604","last":"2604"},"periods":[{"id":"1604","year":2016,"month":4,"label":"2016年4月","choice":[{"no":1,"t":"1883年从西文翻译《维氏美学》的日本学者是","o":["中江肇民","花之安","今道友信","小尾郊一"],"a":[0],"exp":"中江肇民（中江兆民）是日本近代著名的思想家，于1883年根据法国维龙（Véron）的《美学》日译本转译，是最早将西方美学引入东亚的学者之一。花之安是德国传教士，今道友信是日本当代美学家，小尾郊一为中国古典文学研究者，均与本题时间及事件不符。","multi":false},{"no":2,"t":"美学学科属于","o":["自然科学","社会学科","信息学科","人文学科"],"a":[3],"exp":"美学研究人类的审美活动、审美意识和艺术规律，涉及价值、意义、情感等主观精神层面，不以实证或量化为主，故属于人文学科（如哲学、文学、艺术学等），而非自然科学、社会科学或信息学科。","multi":false},{"no":3,"t":"意象的主要类型不包括","o":["兴象","仿象","物象","喻象"],"a":[2],"exp":"在美学中，意象按生成方式可分为兴象（触物起情）、喻象（借喻表意）、仿象（模拟客观）、抽象（抽离具象）等类型。“物象”是客观物体的自然形象，未经主观情感和意识的熔铸，属于意象的原材料而非意象本身，因此不属于主要类型。","multi":false},{"no":4,"t":"提出“艺术是人类情感符号形式”的学者是","o":["柏格森","荣格","克莱夫·贝尔","苏珊·朗格"],"a":[3],"exp":"苏珊·朗格在《情感与形式》中明确提出艺术是“人类情感的符号形式的创造”。柏格森强调直觉，荣格提出集体无意识和原型，克莱夫·贝尔提出“有意味的形式”，均与此命题不同。","multi":false},{"no":5,"t":"关于艺术功能不正确的表述是","o":["艺术的首要功能是审美","艺术具有多元的功能","艺术的多元功能须通过审美功能间接实现","艺术的审美功能让人们透过现象看本质"],"a":[3],"exp":"艺术的首要功能是审美，且具有认知、教育、娱乐等多元功能，这些功能通常以审美为中介间接实现。但“透过现象看本质”主要属于科学或哲学认识功能，并非审美功能的直接目的，审美更侧重于感性体验和情感愉悦，故D表述不正确。","multi":false},{"no":6,"t":"从杜甫《闻官军收河南河北》的诗中：“剑外忽传收蓟北，初闻涕泪满衣裳！却看妻子愁何在，漫卷诗书喜欲狂。白日放歌须纵酒，青春作伴好还乡。即从巴峡穿巫峡，便下襄阳向洛阳。”可以看出，对审美想象起支配作用的因素是","o":["感知","理解","情感","移情"],"a":[2],"exp":"诗中诗人听闻胜利消息后涕泪纵横、欣喜若狂，进而想象归乡路线，整个想象过程被强烈的情感（惊喜）所驱动。情感是审美想象的动力和导向，感知提供材料，理解赋予意义，移情是情感投射，但本题明确体现情感对想象的支配作用。","multi":false},{"no":7,"t":"西方美学史上提出“理智直观”学说的思想家是","o":["谢林","马克思","胡塞尔","德里达"],"a":[0],"exp":"德国古典哲学家谢林在《先验唯心论体系》中提出“理智直观”（或译“智性直观”），认为主体通过直观直接把握绝对同一性。马克思持实践观点，胡塞尔主张现象学直观，德里达解构主义，均不属此。","multi":false},{"no":8,"t":"自调节审美除了要做到有目的和无目的的辩证统一，还要求","o":["鉴赏调节","同化调节","反思调节","反馈调节"],"a":[3],"exp":"自调节审美理论认为审美活动需要目的性与无目的性的统一，同时通过“反馈调节”机制（即审美主体根据审美对象的反馈不断调整自身心理结构）来维持动态平衡。其他选项并非该理论的专用术语。","multi":false},{"no":9,"t":"艺术本体论的核心问题是","o":["艺术的形式构成","艺术的存在方式","艺术的创作方法","艺术的本质特征"],"a":[1],"exp":"艺术本体论探讨艺术作为存在的根本方式，即艺术“如何存在”的问题，涉及艺术品、艺术家、欣赏者等多重关系中的存在形态。形式构成、创作方法、本质特征虽相关，但核心是存在方式。","multi":false},{"no":10,"t":"艺术创造的核心是","o":["形象的创造","主题的表达","意象的生成","情节的构思"],"a":[2],"exp":"艺术创造的本质在于艺术意象的生成，即艺术家将审美感受、情感与理解融合为内在的、非现实的心理意象，这是艺术活动的核心环节。形象、主题、情节均为意象的具体表现或载体。","multi":false},{"no":11,"t":"艺术接受中的意象是","o":["再生成的","直接传递的","作品中固有的","艺术家规定的"],"a":[0],"exp":"艺术接受中，欣赏者并非被动接收作品中的意象，而是依据自身审美经验对作品符号进行解读、补充和再创造，形成新的意象，即“再生成”的过程。意象并非实物直接传递，也非固化于作品或由艺术家单方面规定。","multi":false},{"no":12,"t":"所谓自由人生境界，就是从人生境界中升华出来的","o":["自然境界","功利境界","道德境界","审美境界"],"a":[3],"exp":"根据冯友兰等人的人生境界说，人生境界由低到高依次为自然境界、功利境界、道德境界、天地境界（审美境界）。审美境界超越了功利和道德的自律，达到心灵自由和情感愉悦，故“自由人生境界”即审美境界的升华。","multi":false},{"no":13,"t":"明朗的秋日、淡淡的远山、薄薄的晨雾、轻盈的雪花，从审美形态看都属于","o":["优美","意境","壮美","自然"],"a":[0],"exp":"上述景物给人以柔和、宁静、和谐、愉悦的审美感受，符合“优美”的特征（小巧、光滑、柔和、协调等）。“意境”是主客观交融的深层境界，“壮美”强调巨大力量，自然则过于宽泛。","multi":false},{"no":14,"t":"把生活中的悲剧与审美意义上的悲剧明确区别开来的美学家是","o":["亚里士多德","黑格尔","叔本华","尼采"],"a":[3],"exp":"尼采在《悲剧的诞生》中明确指出，生活中的痛苦和灾难（日常悲剧）与作为艺术形式的悲剧不同，后者是日神精神和酒神精神结合的审美现象，能带来形而上学的慰藉。亚里士多德、黑格尔、叔本华虽论悲剧，但未如此清晰区分日常与审美。","multi":false},{"no":15,"t":"作为审美形态的荒诞，其形成直接源于西方的","o":["荒诞派小说","荒诞派绘画","荒诞派戏剧","荒诞派电影"],"a":[2],"exp":"荒诞作为审美形态，其直接源头是20世纪50年代法国的荒诞派戏剧（如贝克特、尤涅斯库），通过舞台表现世界的非理性和人的异化，从而被纳入美学范畴。小说、绘画、电影虽也有荒诞表现，但戏剧是其最早最集中的艺术载体。","multi":false},{"no":16,"t":"在中国美学史上，美育作为一门独立学科出现于","o":["17世纪","18世纪","19世纪","20世纪"],"a":[3],"exp":"中国现代美育学科是由王国维、蔡元培等人在20世纪初引入和建立的。蔡元培1912年提出“美育代宗教”，并在全国推行，标志着美育在中国成为独立学科。17-19世纪中国虽有美育思想，但未形成独立学科体系。","multi":false},{"no":17,"t":"孔子以山水比德，屈原以芳草自喻，体现了中华审美文化一种特殊的价值观，即","o":["美善相兼","美善相分","以美启真","以美储善"],"a":[0],"exp":"孔子将山水的自然美与人的道德品格（仁、智）相比附，屈原用香草象征自己的高洁品质，都是将审美形象与伦理道德直接融合，体现“美善相兼”的价值观。B主张分离，C强调真，D强调通过美保存善，但本题是二者兼有，故A最贴切。","multi":false},{"no":18,"t":"在中国先秦，提出“化性起伪”、“无伪则性不能自美”这一命题的思想家是","o":["孔子","孟子","荀子","老子"],"a":[2],"exp":"荀子主张“性恶论”，认为人性本恶，需要通过后天的礼义文理（“伪”）来改造（“化性起伪”），并且“无伪则性不能自美”，即不经过人为的修饰和教化，本性无法成就美。孔子重仁，孟子主性善，老子尚自然，均与此论不合。","multi":false},{"no":19,"t":"席勒认为，美育的独特目的是","o":["促进健康","促进认识","促进道德","促进鉴赏力"],"a":[3],"exp":"席勒在《审美教育书简》中提出，美育的独特目的是培养人的“审美鉴赏力”或“审美趣味”，使人从感性冲动和理性冲动的束缚中解放出来，达到自由完整的人性。健康属于体育，认识属于教育，道德属于德育，均非美育独特目的。","multi":false},{"no":20,"t":"提出“有意味的形式”理论的是","o":["克罗齐","克莱夫·贝尔","荣格","席勒"],"a":[1],"exp":"英国美学家克莱夫·贝尔在《艺术》一书中提出“艺术是有意味的形式”，认为形式的“意味”是审美情感的根本来源。克罗齐主张“直觉即表现”，荣格提出原型，席勒强调美育，均不属此。","multi":false},{"no":21,"t":"审美关系是一种","o":["理性认识关系","情感体验关系","感性直观关系","人与世界之间的自由关系","社会功利关系"],"a":[1,2,3],"exp":"审美关系是主体在感性直观中，以情感体验为核心，实现人与世界自由统一的非功利性关系。A理性认识关系属于科学认知，E社会功利关系属于实用领域，均不符合审美的本质特征。","multi":true},{"no":22,"t":"意象和意境的关系主要表现为","o":["意境以意象的存在为前提","两者所达到的层次、深度不同","意象是意境的前提，意境是意象的归宿","意象属艺术范畴，而意境则指的是心灵时空的存在与运动","意境是意象的升华"],"a":[0,1,3,4],"exp":"意象是构成意境的具体个体，意境由多个意象整体升华而来，故A、E正确；意境比意象更具哲理性、深远性，层次更深，B正确；意境不仅是艺术范畴，更涉及心灵时空的延展，D正确。C中“意象是意境的前提，意境是意象的归宿”虽有一定道理，但官方答案未包括，可能因表述过于绝对，且“归宿”提法不准确，故排除。","multi":true},{"no":23,"t":"审美经验的构成要素包括","o":["感知","想象","情感","理解","移情"],"a":[0,1,2,3],"exp":"审美经验的基本构成要素为感知（提供材料）、想象（加工组合）、情感（驱动评价）、理解（赋予意义），四者缺一不可。移情是情感的一种特殊投射方式，属于具体心理机制，不列为基本构成要素。","multi":true},{"no":24,"t":"黑格尔在《美学》中根据内容与形式的关系把艺术分为","o":["象征型","写实型","古典型","浪漫型","理想型"],"a":[0,2,3],"exp":"黑格尔按理念与形式的关系将艺术发展分为三类型：象征型（形式大于内容）、古典型（内容与形式完美统一）、浪漫型（内容大于形式）。写实型和理想型并非黑格尔的划分术语。","multi":true},{"no":25,"t":"从悲剧的性质和效果看，构成悲剧内涵的核心要素有","o":["性格","情节","冲突","抗争","毁灭"],"a":[2,3,4],"exp":"悲剧的核心在于主人公面对不可避免的冲突（社会、命运或内心）时进行不屈的抗争，最终遭遇毁灭，从而引发怜悯与恐惧，达到净化。性格和情节是悲剧的构成成分，但不是核心内涵要素。","multi":true}],"essay":[{"no":26,"t":"审美情趣","ans":"指在审美实践中，不同的审美样态在与主体构成不同的审美关系时，所产生的不同趣味效应，如悲剧令人振奋，优美使人喜爱等。","exp":"审美情趣是主体在审美活动中形成的个性化偏好和情感反应，既受制于审美对象的形态特征，也取决于主体的文化修养、心理结构。它体现了审美主体对特定美感的敏锐性和选择性，是审美判断的感性表现。","type":"名词解释"},{"no":27,"t":"审美理解","ans":"（1）是在把握对象感性形象基础上做出具有普遍性的审美判断和评价。（2）有非概念性和多义性。","exp":"审美理解不同于科学理性认识，它不依赖抽象概念，而是在感性体验中直接领悟对象的美学内涵。其判断往往带有普遍可传达性（如“这件作品是优美的”），但又不唯一固定，允许不同的解读，因此具有多义性。","type":"名词解释"},{"no":28,"t":"生物本能说","ans":"（1）认为美学活动发生于人的某种自然本能的学说。（2）生物本能说若重于生物学意义上的美感能力，代表人物是达尔文。（3）精神分析学的本能说着重于性本能，认为审美是人的性欲升华的一种基本途径，代表人物是弗洛伊德。","exp":"该学说从进化论和生理学角度解释审美起源，认为审美能力是人类或动物先天具备的生物性反应（如对色彩、对称的本能喜好）。但该理论忽视了社会文化因素，因此只能解释部分审美现象，不能全面阐明审美的本质。","type":"名词解释"},{"no":29,"t":"美育的内涵","ans":"（1）以艺术和各种美的形态作为具体的媒介手段。（2）通过审美活动展示审美对象丰富的价值意味，直接作用于受教者的情感世界，从而潜移默化地塑造和优化人的心理结构、铸造完美人性，提升人生境界。（3）是一种有组织、有目的的定向教育方式。","exp":"美育是全面发展教育的重要组成部分，其核心是通过审美体验来培养人的感性素养、创造力与高尚情操。它区别于智育和德育，重在“以情感人”“以美育人”，形式灵活，效果持久，最终目的是实现人的自由而全面的发展。","type":"名词解释"},{"no":30,"t":"简述审美经验的动态过程。","ans":"（1）第一阶段是呈现阶段，指的是主体借助感知对象的感性特征加以把握，从而使对象在主体的意识之中呈现出来。（2）第二阶段是构成阶段，指的是主体在想象等心理要素的作用下，完成审美对象的构成活动。（3）第三阶段是评价阶段，指的是主体对已经构成的审美对象进行感受和评价的过程。","exp":"审美经验是一个由外至内、由浅入深的动态心理流程。呈现阶段是感官对形式美的直接捕捉；构成阶段通过联想、移情等将碎片整合为完整的意象；评价阶段则融合情感与理解，形成审美愉悦或判断。三阶段相互渗透，共同完成审美体验。","type":"简答"},{"no":31,"t":"简述优美和崇高是两种不同的人生境界。","ans":"（1）优美和崇高是两种不同形态的美，是人社会实践中呈现出的两种存在状态。（2）优美主要展示了人的存在中的统一、平衡、和谐的状态，而崇高则主要体现的是人生实践中的冲突和对立状态。（3）优美和崇高是两种互相对立又互相补充的人生境界。","exp":"优美体现主体与客体、感性与理性的和谐统一，给人以宁静、愉悦；崇高则体现为巨大力量对主体的压迫，激发主体的精神提升和超越。二者反映人在实践中面对不同境遇时的情感升华方式，共同构成完整的人生审美维度。","type":"简答"},{"no":32,"t":"简述柏拉图的美育观。","ans":"（1）在西方，柏拉图是最早明确谈到审美教育的哲学家。（2）柏拉图认为必须从幼年起就对人施行严格的教育，而最重要的教育方式就是美育，他认为用故事形成儿童的心灵，比用手形成他们的身体还要费更多的心血，因此，必须用高尚的文艺作品陶冶青少年的心灵。（3）柏拉图非常重视音乐教育，认为音乐教育比其他教育都重要得多。","exp":"柏拉图在《理想国》中强调美育对塑造灵魂的重要性，尤其注重音乐和诗歌的教化作用。他主张通过有选择的内容（排除低级、模仿不良品德的作品）来培养儿童的节制、勇敢等美德，其美育思想服务于政治理想，具有强烈的理性主义倾向。","type":"简答"},{"no":33,"t":"简述审美实践是一种人生实践。","ans":"（1）审美实践是人的生存和发展的需要。审美活动极大地推动着人类社会的发展和文明的进化。（2）审美实践以人生实践为源泉，审美的创造与欣赏都离不开人生实践。","exp":"审美不是脱离现实的精神活动，而是根植于人类生产劳动、社会交往等具体实践活动。它既是人对自由解放的追求，也反作用于实践，提升人的精神境界，促进文化积累。因此，审美实践本质上就是人生实践的有机组成部分。","type":"简答"},{"no":34,"t":"简述艺术品的形式符号层。","ans":"（1）指艺术品中的色彩、线条、形体、音符、旋律、词语等，构成艺术品的第二层次。（2）是艺术品直接性的物质存在。（3）直接指示、负载着艺术的意象世界。","exp":"在艺术品的层次结构中，形式符号层是介于物质媒材层和意象世界层之间的中介。它由材质（如颜料、声波、文字）转化而来，具有可感知的形态，同时又承载着艺术家的情感和观念，引导欣赏者进入意蕴层面。它是艺术语言的具体呈现。","type":"简答"},{"no":35,"t":"结合具体的审美实践，论述审美活动是最具个性化的精神活动。","ans":"（1）审美活动首先是一种精神活动。（2）审美活动在各种精神活动中最具有个性化。（3）审美活动把感性、个别性作为自己最基本的存在方式。","exp":"审美活动是主体面对审美对象时产生的精神感受，区别于物质生产或科学认知。个性化表现在：同一审美对象因欣赏者的人生经历、文化修养、心境情感不同而产生截然不同的体验（如“一千个读者有一千个哈姆雷特”）；审美趣味无争辩，主体拥有充分的选择自由；审美创造更是艺术家独特灵魂的外化。审美活动立足感性具体形象，不诉诸普遍概念，每个意象都是独一无二的。例如，同是观赏黄山云海，诗人、画家、普通游客的感受各异，甚至同一个人不同时刻感受也变化，充分印证其高度个性化特征。","type":"论述"},{"no":36,"t":"举例说明艺术敏感是艺术家生产意象必不可少的重要条件。","ans":"（1）艺术敏感主要是指主体感受生活、欣赏艺术、体验和孕育意象的敏感性和悟性。（2）艺术家对生活的敏感是形成意象雏形的最初动力。（3）艺术敏感为艺术家意象创造准备了丰富的素材。（4）艺术敏感与先在本体的文化心理结构有本质关系，可以赋予意象以艺术意义。","exp":"艺术敏感是艺术家区别于常人的天赋，表现为对日常事物中潜在美感的迅速捕捉（如郑板桥观察竹影而生画意）。敏感激起创作冲动，推动意象从朦胧走向清晰（如白居易闻琵琶曲而引发《琵琶行》的创作冲动）。敏感使得艺术家能从平凡生活中汲取琐碎细节，积累为意象创造的原料（如鲁迅童年记忆中的社戏、百草园）。敏感并非纯粹生理反应，而是建立在艺术家深厚的文化修养和情感倾向之上，从而使生成的意象具有深刻的人文内涵（如杜甫对国破家亡的敏感，赋予“感时花溅泪”以沉痛的艺术意义）。","type":"论述"}]},{"id":"1610","year":2016,"month":10,"label":"2016年10月","choice":[{"no":1,"t":"意境所升华的是","o":["意象","拟象","物境","情境"],"a":[0],"exp":"意境由意象升华而来，是意象整体所呈现出的更深层、更具哲理性和情感性的审美境界。意象是构成意境的具体个体，意境是意象的升华和归宿，故A正确。","multi":false},{"no":2,"t":"“娱乐说”界定艺术的角度是","o":["起源","本质","功能","特质"],"a":[2],"exp":"“娱乐说”强调艺术能给人带来愉悦和消遣，这是从艺术对人产生的作用（功能）角度来界定艺术，而非探讨其起源、本质或特有属性，故C正确。","multi":false},{"no":3,"t":"在形式美的原则中最基本、最普遍的形式规律是","o":["整齐划一","对比调和","均衡对称","多样统一"],"a":[3],"exp":"多样统一是形式美的最高法则，也是最基本、最普遍的形式规律，它体现了变化中的秩序和统一中的丰富。整齐划一、对比调和、均衡对称都是多样统一的具体表现形式。","multi":false},{"no":4,"t":"马克思指出：“作家绝不把自己的作品看作手段，作品就是目的本身”，这说明审美活动具有","o":["他律性","有限无功利性","自律性","最高功利性"],"a":[2],"exp":"马克思这句话强调艺术创作不以作品为工具（手段），而以作品本身为目的，体现了审美活动不依赖外在目的而自我规定的特性，即“自律性”。有限无功利性（B）和最高功利性（D）虽相关，但本题直接指向自律性。","multi":false},{"no":5,"t":"原始人在身体上刻痕、刺纹、穿耳、穿鼻等装饰活动，属于","o":["固定装饰","自我装饰","自我修饰","非固定性装饰"],"a":[0],"exp":"原始人在身体上刺纹、穿耳等永久性或半永久性改变身体形态的装饰，属于“固定装饰”（又称“固定性装饰”）。自我修饰（C）或非固定装饰（D）通常指服饰、配饰等可更换的装饰。","multi":false},{"no":6,"t":"中国古典美学中提到的“言有尽而意无穷”、“象外之象、景外之景”，实质上揭示了审美对象的","o":["实体性","非实体性","开放性","非开放性"],"a":[2],"exp":"这些命题强调审美对象超越了具体语言和形象，指向无限延伸的意蕴空间，说明审美对象不是封闭固定的，而是具有开放性和生成性，故C正确。非实体性（B）更侧重存在方式，而本题强调意蕴的延展。","multi":false},{"no":7,"t":"提出“美就是理念的感性显现”这一命题的美学家是","o":["柏拉图","康德","黑格尔","马克思"],"a":[2],"exp":"黑格尔在《美学》中提出“美是理念的感性显现”，认为美是绝对理念通过感性形式表现出来。柏拉图强调“美本身”是理念，但未用此表述；康德研究审美判断力；马克思继承并改造了黑格尔辩证法。","multi":false},{"no":8,"t":"古希腊的悲剧常被称为","o":["人生悲剧","命运悲剧","性格悲剧","社会悲剧"],"a":[1],"exp":"古希腊悲剧（如索福克勒斯《俄狄浦斯王》）常表现主人公无法逃脱神谕或命运安排的冲突，因此被称为“命运悲剧”。性格悲剧（莎士比亚）、社会悲剧（易卜生）是后世类型。","multi":false},{"no":9,"t":"作为审美形态的荒诞形成于","o":["古代社会","中世纪","近代社会","现代社会"],"a":[3],"exp":"荒诞作为审美形态是20世纪现代主义文艺的产物，与两次世界大战、非理性哲学（如存在主义）密切相关，故形成于现代社会。古代、中世纪、近代均不具备其社会与思想条件。","multi":false},{"no":10,"t":"喜剧有两种基本形式，即","o":["暴露与歌颂","滑稽与嘲笑","讽刺与幽默","揭露与批判"],"a":[2],"exp":"在美学中，喜剧通常分为讽刺和幽默两种基本形式。讽刺以尖锐批判为主，幽默以温和诙谐为主，二者共同构成喜剧的两种主要精神倾向。其他选项为具体手法或效果。","multi":false},{"no":11,"t":"审美理解的特点是","o":["直观性","随意性","非理性","多义性"],"a":[3],"exp":"审美理解是在感性形象基础上进行的非概念性判断，具有多义性（允许多重解读）和非概念性。直观性（A）属于感知特点；它不是随意（B）或非理性（C）的，而是感性与理性交织。","multi":false},{"no":12,"t":"审美经验中最为活跃的因素是（注：原试卷该题题干未显示完整，根据答案推断为“想象”）","o":["想象","感知","情感","理解"],"a":[0],"exp":"在审美经验的构成要素中，想象最为活跃，它能够突破感知的局限，重组记忆表象，创造出新的意象，是审美创造和体验的核心动力。感知提供材料，情感驱动，理解赋予意义。","multi":false},{"no":13,"t":"现代阐释学认为，艺术的本质体现在人类无限延伸的","o":["艺术作品中","审美对象中","社会生活中","审美经验中"],"a":[3],"exp":"现代阐释学（如伽达默尔）强调艺术的意义在历史性的理解和解释中不断生成，艺术的本质不在静态的作品或对象，而在动态的、无限延伸的审美经验过程之中，故D正确。","multi":false},{"no":14,"t":"在生产意象全过程中最重要、最有决定性的因素是","o":["感受力","想象力","观察力","表达力"],"a":[1],"exp":"意象的生成是“意”与“象”的融合，想象力是将情感、意念转化为可感形象的核心能力，它决定了意象的独创性和生动性，因此最具决定性。感受力提供材料，表达力实现外化。","multi":false},{"no":15,"t":"最早从艺术的审美特征出发来划分艺术形态的美学家是","o":["雅克·德里达","苏珊·朗格","阿尔贝·加托","克莱夫·贝尔"],"a":[2],"exp":"法国美学家阿尔贝·加托（Abbé Batteux）在18世纪首次依据艺术的审美特征（如模仿方式）将艺术分为音乐、绘画、雕塑、舞蹈等类别，奠定了现代艺术分类学基础。德里达是解构主义者，朗格和贝尔属20世纪。","multi":false},{"no":16,"t":"“期待视界”对于作品来说是一种","o":["先在结构","心理结构","无意识结构","潜意识结构"],"a":[0],"exp":"“期待视界”（或“期待视野”）由接受美学代表姚斯提出，指读者在阅读前已有的审美经验和知识框架，对作品来说是一种“先在结构”，它决定了读者对作品的接受方式和理解范围。","multi":false},{"no":17,"t":"梁启超认为，美育就是","o":["人格教育","艺术教育","趣味教育","道德教育"],"a":[2],"exp":"梁启超深受康德、席勒影响，提出“美育即趣味教育”，强调通过审美培养人的趣味和情感，提升精神境界。人格教育（蔡元培）、艺术教育（广义美育）、道德教育均非梁启超特有观点。","multi":false},{"no":18,"t":"审美教育的实践基础是","o":["教育活动","道德活动","艺术活动","审美活动"],"a":[3],"exp":"美育以审美活动为直接实践基础，只有在具体的审美体验中才能实现情感陶冶和人格塑造。教育活动、道德活动、艺术活动虽与美育相关，但其基础是审美活动本身。","multi":false},{"no":19,"t":"在儒家的美育观中，实质上更强调","o":["知识教育","艺术教育","道德教化","才艺培养"],"a":[2],"exp":"儒家美育观（如孔子“兴于诗，立于礼，成于乐”）实质上是将艺术和审美作为道德教化的手段，最终目的是培养“仁”德。知识教育、才艺培养是途径，道德教化为根本。","multi":false},{"no":20,"t":"与一般的教育方式相比，美育最显著的特点是","o":["诉诸感性","化性起伪","理性直观","陶养性情"],"a":[0],"exp":"美育区别于德育、智育的根本特点在于“诉诸感性”，即通过具体可感的审美形象直接打动人的情感，而非说理或强制。化性起伪（荀子）是美育功能之一，理性直观（谢林）是哲学概念，陶养性情是效果而非最显著特点。","multi":false},{"no":21,"t":"艺术品的层次结构包括","o":["物质实在层","形式符号层","内在意蕴层","意象世界层","意境超验层"],"a":[0,1,3,4],"exp":"在美学中，艺术品层次结构通常分为物质实在层（材质）、形式符号层（语言）、意象世界层（审美意象）和意境超验层（形而上的意蕴）。内在意蕴层（C）属于意象或意境层的内容，不单独作为基本层次。","multi":true},{"no":22,"t":"从不同角度提出审美活动起源于人的某种本能的学者有","o":["德谟克里特","博克","达尔文","弗洛伊德","柏拉图"],"a":[0,1,2,3],"exp":"德谟克里特（模仿本能）、博克（基本情欲）、达尔文（美感本能）、弗洛伊德（性本能）均从本能角度解释审美起源。柏拉图虽然相关，但其理论更强调“理念回忆”或“迷狂”，不属于生物学本能说，故排除E。","multi":true},{"no":23,"t":"从总体上来看，美学家们划分艺术类型的主要依据是","o":["艺术与现实的关系","艺术与作者的关系","艺术作品与欣赏者的关系","艺术的起源","艺术作品自身的存在方式"],"a":[0,2,4],"exp":"美学家划分艺术类型的主要依据包括：艺术与现实的关系（如模仿论）、艺术作品与欣赏者的关系（如接受美学）、艺术作品自身的存在方式（如时间艺术/空间艺术）。艺术与作者关系（B）和起源（D）不是主要分类依据。","multi":true},{"no":24,"t":"贺拉斯提出著名的“寓教于乐”说，他认为要体现这一原则，文艺就必须具有","o":["真实性","形象性","理解性","想象性","情感性"],"a":[0,1,4],"exp":"贺拉斯在《诗艺》中强调文艺要“寓教于乐”，既要有教育意义，又要有审美愉悦。为此，文艺必须具有真实性（可信）、形象性（可感）和情感性（动人）。理解性（C）和想象性（D）是审美心理要素，并非贺拉斯明确提出的要求。","multi":true},{"no":25,"t":"在中国近代美学史上，对美育作为一门独立学科的形成做出重要贡献的美学家有","o":["蔡元培","王国维","梁启超","宗白华","李泽厚"],"a":[0,1,2],"exp":"蔡元培、王国维、梁启超是中国近代美育学科的主要奠基人。蔡元培首倡“美育代宗教”，王国维引入西方美学并论述美育，梁启超提倡“趣味教育”。宗白华和李泽厚是20世纪中后期美学家，不属于近代美育学科形成期的主要贡献者。","multi":true}],"essay":[{"no":26,"t":"审美体验","ans":"（1）审美主体在审美活动中的一种独特精神状态。（2）主体在具体审美活动中被具有某种独特性质的客体对象所吸引，情不自禁地对之进行领悟、体味、咀嚼，以至于陶醉其中，心灵受到摇荡和震撼。","exp":"审美体验是主体深入审美对象内部，与之交融共鸣的深度心理过程，它不同于日常感知，而是充满情感投入和意义发现，是审美经验的核心环节。","type":"名词解释"},{"no":27,"t":"荒诞","ans":"（1）作为一种审美形态，是西方现代社会与现代文化的产物。（2）荒诞的本义是不合情理与不和谐，它的形式是怪诞、变形，它的内容是荒诞不真。","exp":"荒诞源于现代人对世界非理性、无意义状态的感受，在艺术中表现为夸张、变形、反逻辑的手法，传达出存在的荒诞感和人的异化。","type":"名词解释"},{"no":28,"t":"有意味的形式","ans":"（1）克莱夫·贝尔提出；（2）形式就视觉艺术而言，指线条和色彩以某种特定方式排列而组合起来的纯粹的关系；（3）意味指这种纯形式背后表现或隐藏着的艺术家独特的审美情感；（4）突出了审美本质，但脱离了人类实践和社会历史发展，陷入了形式主义和神秘主义。","exp":"贝尔认为艺术的根本特性是“有意味的形式”，即能引发审美情感的形式组合。该理论强调艺术的自律性，但忽略了艺术与社会、历史的联系，具有局限性。","type":"名词解释"},{"no":29,"t":"虚静","ans":"（1）排除功利杂念，集中精神；（2）超越知性逻辑；（3）进入感性直觉的状态；（4）使日常的“自我”暂时隐退与丧失，却能在审美状态中以虚空的心胸接纳万物，孕育意象。","exp":"虚静是中国古典美学的重要范畴，指审美主体通过清空内心杂念、超越理性思辨，达到物我两忘的直观境界，从而更敏锐地感受和创造美。","type":"名词解释"},{"no":30,"t":"简述意象的结构。","ans":"（1）作为一种心理存在的审美表象系统。（2）“意”指主体在审美中的意向、意图、意志、意念、意欲，表达的思想情感、人生体验、审美理想、艺术追求；“意”借“象”而成形。（3）“象”由想象创造出来，能体现主体之“意”，并能为感官所直接感受、知觉、体验到非现实的表象，“象”以“意”为自己的灵魂。","exp":"意象是“意”与“象”的融合统一。“意”是内在的情感和意念，“象”是外在的可感形象，二者互为表里，共同构成审美意象的基本结构。","type":"简答"},{"no":31,"t":"简述审美趣味的标准。","ans":"（1）必须把审美趣味联系于具体的审美对象，看看依据这种审美趣味所作出的判断是否充分反映了审美对象的客观特点。（2）审美趣味作为主体审美心理结构的组成部分，必然受到主体审美理想的制约，要提高我们的审美趣味，就要提高我们的审美理想。","exp":"审美趣味既有主观性，也有客观标准。标准之一是看它是否符合审美对象的实际特征；标准之二是看它是否受到健康审美理想的引导，后者决定了趣味的品位和格调。","type":"简答"},{"no":32,"t":"简述悲剧的特征。","ans":"（1）悲剧通过对人生存在的否定性体验，展现对人生存在价值的肯定。（2）悲剧的审美冲突体现的是人与自然、社会及自身存在的冲突与超越。","exp":"悲剧不是简单地展示痛苦，而是通过主人公的毁灭性遭遇，激发观众对生命意义和道德价值的深刻思考，在否定中彰显肯定，在毁灭中展现崇高。","type":"简答"},{"no":33,"t":"简述艺术品的鉴赏过程。","ans":"（1）艺术鉴赏的过程分为三个阶段：观、品、悟。观是指接受者透过艺术的形式符号在直观层次上初步感受和重建意象。（2）品是指接受者根据各自的审美文化心理结构和经验，凝神观照，发挥想象力，细致地体味作品，充实、丰富、发展意象，使意象更具接受者的个性。（3）悟是主体对艺术品的意象品鉴渐入佳境后，终于升华为对意境的感悟。","exp":"鉴赏是由浅入深的递进过程。“观”是直觉感知，“品”是深入玩味，“悟”是精神升华，三者共同构成完整的接受体验，体现了审美理解的层次性。","type":"简答"},{"no":34,"t":"简述蔡元培的美育观。","ans":"（1）蔡元培是率先把“美育”一词引入中国的美学家，也是中国近代以倡导美育著称的学者。（2）他认为美育的目的在于陶养感情。陶养的工具为美的对象，陶养的作用叫做美育。（3）他十分推崇美育的价值，提出了“以美育代宗教”的主张，认为美育是自由的，宗教是强制的；美育是进步的，宗教是保守的；美育是普及的，宗教是有界的。他把美育看成是提升人生价值的途径和激发创造力的动力。","exp":"蔡元培是中国现代美育的先驱，他借鉴西方思想，将美育纳入国民教育体系，赋予其提升国民素质、解放个性的使命，其“以美育代宗教”的命题影响深远。","type":"简答"},{"no":35,"t":"结合具体事例，论述审美活动是人的基本存在方式。","ans":"（1）审美活动是人的一种基本的存在方式，也是一种基本的人生实践。（2）在人生实践中，审美活动一旦发生，便必然由一般的人生境界向审美境界发展。（3）只有在审美活动中，主体才成为现实的审美主体，对象才成为现实的审美客体。","exp":"审美活动不是生活的点缀，而是人实现自我、超越有限的重要途径。人在审美中摆脱功利束缚，进入自由的精神状态，如欣赏自然山水或聆听音乐时，人与自然、人与世界达成和谐，这正是人作为“类存在”的本质需求的体现。例如，海德格尔认为“诗意地栖居”是人的本真存在方式；中国古代文人寄情山水、吟咏性情，也表明审美是生存不可分割的部分。","type":"论述"},{"no":36,"t":"马克思说：“忧心忡忡的、贫穷的人对最美丽的景色都没有什么感觉；经营矿物的商人只看到矿物的商业价值，而看不到矿物的美和独特性……”根据这段话，论述审美经验的非功利性。","ans":"（1）从审美对象角度看，审美经验具有直观性的特点，与对象实际存在不发生利害关系。（2）从审美主体角度看，审美经验的基本功能在于让人产生审美愉悦，这就要求人们排除各种功利因素的干扰。（3）审美经验是一种非功利的行为，但并不意味着审美经验不可能产生任何功利性的作用。","exp":"马克思这段话深刻揭示了功利态度对审美感受的遮蔽。贫穷者因生存压力无法感受美景，商人因商业利益看不到矿物之美，说明审美需要主体暂时悬置功利害。只有摆脱实用欲望，才能以“无所为”的心态直观对象的形象和形式，获得纯粹的审美愉悦。同时，审美虽然非功利，但能间接陶冶情操、提升精神境界，具有“无用之用”的深层价值。","type":"论述"}]},{"id":"1704","year":2017,"month":4,"label":"2017年4月","choice":[{"no":1,"t":"“美学的根本问题是研究人对现实的审美关系”这一命题出自蒋孔阳的","o":["《美学新论》","《美的历程》","《美学散步》","《新美学》"],"a":[0],"exp":"蒋孔阳在《美学新论》中明确提出“美学的根本问题是研究人对现实的审美关系”。《美的历程》是李泽厚著，《美学散步》是宗白华著，《新美学》是蔡仪著，均不符合。","multi":false},{"no":2,"t":"“宁可食无肉，不可居无竹”，这说明","o":["肉体享受高于精神享受","精神享受高于肉体享受","精神享受与肉体享受密不可分","肉体享受与精神享受毫不相干"],"a":[1],"exp":"该诗句强调宁可放弃物质满足（食肉），也要追求精神审美（居竹），体现了精神享受高于肉体享受的价值取向，故B正确。C强调二者不可分，D否认关联，均不符合题意。","multi":false},{"no":3,"t":"美学中贯穿始终的理论基石是","o":["审美形态","审美经验","审美关系","审美活动"],"a":[3],"exp":"审美活动是美学的逻辑起点和核心范畴，贯穿美学研究的始终。审美形态、审美经验、审美关系都由审美活动衍生而来，故D为基石。","multi":false},{"no":4,"t":"审美发生的“生物本能说”中影响最大的理论家是","o":["席勒","达尔文","康德","卢卡奇"],"a":[1],"exp":"达尔文从进化论角度提出美感与动物本能相关，是“生物本能说”影响最大的代表。席勒提出“游戏说”，康德研究审美判断，卢卡奇是西方马克思主义美学家，均不属此。","multi":false},{"no":5,"t":"主体在审美活动中的精神存在特征主要体现在","o":["呈现、构成、评价三个阶段","呈现、创造、评论三个阶段","惊异、体验、澄明三个基本环节","惊论、感受、澄明三个基本环节"],"a":[2],"exp":"审美主体在审美活动中的精神存在特征体现为惊异（触发）、体验（深入）、澄明（顿悟）三个基本环节。A为审美经验的动态过程，B和D表述有误。","multi":false},{"no":6,"t":"最具有人的本质性的存在方式是","o":["审美活动","审美经验","审美关系","审美评价"],"a":[0],"exp":"审美活动是人的自由自觉活动的集中体现，最直接地彰显人的本质力量（情感、想象、创造）。审美经验、审美关系、审美评价都是审美活动的具体表现或结果。","multi":false},{"no":7,"t":"提出“劳动先于艺术”的理论家是","o":["格罗塞","泰勒","毕歇尔","普列汉诺夫"],"a":[3],"exp":"普列汉诺夫在《没有地址的信》中系统论证了“劳动先于艺术”，认为艺术起源于生产劳动。格罗塞研究艺术起源但未提出此命题；泰勒是文化人类学家；毕歇尔研究劳动与节奏的关系。","multi":false},{"no":8,"t":"康德认为崇高对象的特征是","o":["无内容","无形式","内容压倒形式","形式压倒内容"],"a":[1],"exp":"康德认为优美是“形式压倒内容”，而崇高对象则是“无形式”或“超越形式”，因其巨大、无限而超出感性形式的把握能力，引发主体的理性超越。","multi":false},{"no":9,"t":"对荒诞审美范畴的形成产生重要影响的哲学派别是","o":["人本主义","存在主义","结构主义","实用主义"],"a":[1],"exp":"存在主义哲学（如萨特、加缪）强调世界的非理性和人的荒诞处境，直接影响了荒诞审美范畴的形成。人本主义、结构主义、实用主义均非其主要思想来源。","multi":false},{"no":10,"t":"美育作为一门独立学科在人类文化史上正式形成于","o":["17世纪","18世纪","19世纪","20世纪"],"a":[1],"exp":"美育作为独立学科正式形成于18世纪，以席勒1795年发表《审美教育书简》为标志。17世纪尚未形成，19世纪和20世纪是美育的发展与完善期。","multi":false},{"no":11,"t":"孔子主张“兴于诗，立于礼，成于乐”，说明他把乐的感化作用看成是育人的","o":["最高境界","现实途径","基本手段","根本目的"],"a":[0],"exp":"孔子认为人格修养始于诗（感发），立于礼（规范），最终“成于乐”，即以乐的感化达成内心的和谐与自由，是育人的最高境界。基本手段和根本目的均不准确。","multi":false},{"no":12,"t":"中国古代诗论中提到的“不着一字，尽得风流”，所涉及的审美理解的特点是","o":["非情感性","非概念性","非直观性","非感知性"],"a":[1],"exp":"“不着一字，尽得风流”强调不依赖概念语言而能传达深长意蕴，体现了审美理解的“非概念性”特征，即不通过抽象概念而直接领悟内涵。A、C、D均不符合。","multi":false},{"no":13,"t":"西方美学史上提出“本质直观”学说的思想家是","o":["谢林","马克思","胡塞尔","德里达"],"a":[2],"exp":"胡塞尔在现象学中提出“本质直观”（或“范畴直观”），认为主体可以通过直接意识把握事物的本质。谢林提出“理智直观”，马克思是实践论，德里达解构主义。","multi":false},{"no":14,"t":"艺术品是","o":["精神产品","自然产品","物质产品","抽象产品"],"a":[0],"exp":"艺术品是艺术家精神劳动创造的成果，主要满足人的审美精神需求，故属于精神产品。它虽依赖物质载体，但本质上是精神性的。","multi":false},{"no":15,"t":"下列不属于意象基本特征的是","o":["情感性","想象性","目的性","虚拟性"],"a":[2],"exp":"意象的基本特征包括情感性（主观情感投射）、想象性（由想象生成）、虚拟性（非现实存在）、感性直观性等。“目的性”不属于意象本质特征，而是意象产生过程中主体的意志因素，但不是意象本身的特性。","multi":false},{"no":16,"t":"宗白华所说“中国文化史上最中心也最具有世界贡献的一方面”是指","o":["意象","形象","意境","情境"],"a":[2],"exp":"宗白华高度评价中国美学的“意境”范畴，认为它是中国文化最核心且对世界有独特贡献的方面。意象、形象、情境均非宗白华此语所指。","multi":false},{"no":17,"t":"艺术的形式符号层直接指示、负载着艺术的","o":["情趣世界","趣味世界","意象世界","意境世界"],"a":[2],"exp":"艺术品的层次结构中，形式符号层（色彩、线条、音符、词语等）直接指示并负载着意象世界，是意象的物质载体。意境世界是意象的升华，情趣/趣味世界是审美效果。","multi":false},{"no":18,"t":"从存在方式说，艺术只能存在于艺术品的","o":["外观形式中","内在结构中","审美构思中","意象世界中"],"a":[3],"exp":"艺术的根本存在方式是意象世界。外观形式是载体，内在结构是组织方式，审美构思是创作阶段，都不等于艺术本身的存在。艺术在欣赏中通过意象世界呈现自身。","multi":false},{"no":19,"t":"意象的产生过程是一种","o":["由此及彼的过程","从无到有的过程","由表及里的过程","从小到大的过程"],"a":[1],"exp":"意象的产生是艺术家将主观情意与客观物象融合，创造出全新的心理形象，是“从无到有”的创造性过程。由此及彼（联想）、由表及里（深入）、从小到大（扩展）均不是对意象产生本质的描述。","multi":false},{"no":20,"t":"艺术技巧的操作在质料上留下的痕迹就是","o":["艺术的形态","艺术的形象","艺术的形式","艺术的形成"],"a":[2],"exp":"艺术技巧在物质材料上留下的可感痕迹即为“艺术的形式”，它是技巧操作的外在呈现。艺术形态、形象、形成均与此定义不符。","multi":false},{"no":21,"t":"关于审美活动作为特殊的价值活动表述正确的有","o":["它追求的是一般的价值","它追求的是一般的精神价值","它追求的是创造一个个性丰满的人的世界","它启迪人领悟人生真谛","它满足人的心灵需要"],"a":[2,3,4],"exp":"审美活动是特殊的价值活动，它追求的不是一般价值（A错）或一般精神价值（B错），而是创造个性丰满的世界、启迪人生真谛、满足心灵需要，故CDE正确。","multi":true},{"no":22,"t":"在西方美学史上，对悲剧理论的发展做出重要贡献的有","o":["亚里士多德","博克","黑格尔","尼采","马克思"],"a":[0,2,3,4],"exp":"亚里士多德（悲剧净化说）、黑格尔（悲剧冲突说）、尼采（日神酒神说）、马克思（悲剧历史观）均对悲剧理论有重要贡献。博克主要研究崇高与优美，与悲剧理论关系不大，故不选。","multi":true},{"no":23,"t":"席勒在《美育书简》中第一次明确提出了“美育”的概念，其贡献主要在于","o":["解释了美育的目的","揭示了美育的价值","提出了美育的任务","说明了美育的复杂性","分析了美育与德育的差异"],"a":[0,1,2],"exp":"席勒在《美育书简》中解释了美育的目的（培养完整人性）、揭示了美育的价值（促进自由）、提出了美育的任务（协调感性与理性）。D（复杂性）和E（与德育差异）并非席勒主要贡献点。","multi":true},{"no":24,"t":"关于审美经验的性质表述正确的有","o":["审美经验是人在与对象的审美关系中，构成并评价审美对象的过程","审美经验构成了人生实践的一种重要形式","审美经验具有浓厚的非理性色彩","审美经验具有浓厚的理性色彩","审美经验是一种低层次的认识活动，带有神秘主义色彩"],"a":[0,1,2],"exp":"审美经验是构成与评价的过程（A），是人生实践的重要形式（B），具有浓厚的非理性色彩（情感、想象等）（C）。D“浓厚理性色彩”与事实不符，E“低层次认识活动”和“神秘主义”均属错误表述。","multi":true},{"no":25,"t":"天才独特的艺术创造力主要表现为","o":["艺术敏感","艺术想象力","艺术技巧","灵感","艺术语言"],"a":[0,1,2,3],"exp":"天才的创造力主要表现为艺术敏感（对生活的敏锐捕捉）、艺术想象力（意象生成的核心）、艺术技巧（物化能力）和灵感（突发性创造力）。艺术语言是技巧的一部分或媒介，不属于独立的创造力表现。","multi":true}],"essay":[{"no":26,"t":"审美趣味","ans":"（1）审美趣味是个人在审美活动和审美评价中所表现出来的主观爱好和倾向。（2）能力或鉴赏力是审美趣味的内在方面，兴趣和品位是审美趣味的外在表现。（3）审美趣味呈现明显个性差异，后天因素或社会条件是影响审美趣味的主要因素。","exp":"审美趣味既包含先天的偏好，也受后天文化修养影响，是审美判断的感性体现。它既有独特性，也有高下之分，可通过教育和实践提升。","type":"名词解释"},{"no":27,"t":"净化说","ans":"（1）是亚里士多德在分析悲剧时提出来的。（2）他认为，悲剧能引起人的怜悯与恐惧之情，并使这种情感得到净化，也就是使情感得到陶冶。","exp":"净化说强调悲剧通过唤起并宣泄强烈情感，使观众心灵得到洗涤和升华，是西方悲剧理论的核心范畴之一。","type":"名词解释"},{"no":28,"t":"意境","ans":"（1）中国古典美学的独特范畴。（2）指运用艺术意象，在主客体交融、物我两忘的基础上，将接受者引向一个超越现实时空，富有形上本体意味的境界中。","exp":"意境是意象的整体升华，它超越具体形象，营造出深远、空灵的精神空间，是中国古典艺术追求的最高审美理想。","type":"名词解释"},{"no":29,"t":"意象的生产","ans":"（1）意象的生产意味着艺术家心中的意象得到物态化和物化的表达。（2）这里的生产既有生命孕育分娩的意思，即事物的从无到有，存在的由隐到显。（3）同时又有工艺制作、生产之涵义。","exp":"意象的生产是将内在心理意象转化为可感艺术形象的过程，既是创造性的孕育，也是技巧性的制作，二者统一于艺术实践中。","type":"名词解释"},{"no":30,"t":"简述自由是美学与实践存在论之间的中介。","ans":"（1）自由是从美学的哲学基础向美学的内在问题过渡的中介概念。（2）自由也是从人的实践—存在向审美现象、审美活动过渡的中介环节。（3）人生在世一旦达到自由状态，审美情境就会应运而生。","exp":"实践存在论是美学的哲学基础，而“自由”是将哲学上的实践转化为美学问题的桥梁。人只有在超越功利和必然性的自由状态中，才能进入审美境界，故自由是二者间的中介。","type":"简答"},{"no":31,"t":"简述巫术活动对审美原始发生的重要意义。","ans":"（1）巫术的神圣性与严肃性，提高了人的意识与意志等主体的精神能力。（2）巫术活动独特的仪式化功能，推动了人的文化心理结构的形成。（3）巫术活动的操演直接孕育着原始艺术的发生。","exp":"巫术是原始社会的重要精神活动，它培养了人的想象力、象征能力，并通过歌舞、绘画等仪式形式，为艺术的产生提供了心理基础和实践形态。","type":"简答"},{"no":32,"t":"简述梁启超的美育观。","ans":"（1）梁启超是中国近代最早倡导美育的先驱之一，他的美育思想因他本人的社会地位和思想影响力而颇受时人重视。（2）他认为，美育是一种“趣味教育”。拿趣味当手段，是教育的一种方法；拿趣味当目的，才是真正的美育。（3）他认为，美育是通过情感去感化别人的。他把小说对人的感化作用概括为熏、浸、刺、提四种力，强调其潜移默化的作用，正是他趣味教育观的补充。","exp":"梁启超强调美育的“趣味”本质和情感感染作用，将美育视为培养健全人格的重要途径，对中国近现代美育实践影响深远。","type":"简答"},{"no":33,"t":"简述艺术品与非艺术品的联系。","ans":"（1）经过审美的加工，非艺术的自然物和人工制品可以转化成艺术品。（2）艺术在发展过程中不断向非艺术品领域渗透，拓宽艺术品的领地，增添艺术的门类和品种，并使人类物质和精神生活富有艺术情趣和审美趣味。","exp":"艺术品与非艺术品的界限不是绝对的。一方面，自然物或日常物品经过审美观照可成为艺术品；另一方面，艺术的审美精神也渗入日常生活，提升了非艺术品的美学品质。","type":"简答"},{"no":34,"t":"简述独特的艺术意象与客观对象的原型的区别。","ans":"（1）客观对象的原型转变为知觉表象。（2）表象上渗透着主体的主观情感因素。（3）表象与表象的关系依主体自身的规律发生转变。（4）表象本身作为主体的心理形式与原型完全不同。","exp":"艺术意象不是对客观原型机械复制的表象，而是经过主体情感、想象加工重塑，超越了原型，具有独创性和精神性，二者本质上不同。","type":"简答"},{"no":35,"t":"鲁迅说：“喜剧是将那人生无价值的东西撕破给人看”。请举例分析喜剧的特点。","ans":"（1）喜剧中包含着深刻的社会现实内容，这种对现实生活内容的反映是以与现实错乱的形式表现出来的。喜剧有两种形式，即讽刺与幽默。（2）喜剧具有不和谐、悖谬的形式特征。（3）喜剧的效果表现为笑。喜剧的笑既是一种讽刺和批判，也是一种快乐和肯定。","exp":"喜剧通过对无价值事物的夸张、颠倒、扭曲，揭示其可笑与荒谬，如莫里哀《伪君子》讽刺宗教伪善，果戈理《钦差大臣》揭露官场腐败。其“撕破”即是对虚假、丑陋的暴露，笑中带有批判性，使人在笑声中警醒。同时，幽默型喜剧则以温和方式给人愉悦，体现肯定性。","type":"论述"},{"no":36,"t":"结合具体作品论述审美经验的超越性。","ans":"审美经验的超越性主要体现在三个方面：（1）从物质世界向精神世界的超越。（2）从现实世界向理想世界的超越。（3）从经验世界向超验世界的超越。","exp":"审美经验超越物质功利，如欣赏贝多芬《第九交响曲》时，听众超越物质环境进入精神共鸣；超越现实限制，如观看《哈姆雷特》时，人进入对存在价值的理想追问；超越日常经验，如读李白“举杯邀明月”，体验到超验的自由境界。审美经验让人在有限中触及无限，在感性中悟达理性，实现精神境界的全面提升。","type":"论述"}]},{"id":"1710","year":2017,"month":10,"label":"2017年10月","choice":[{"no":1,"t":"美学是一门关于审美现象的综合性的","o":["自然科学","人文学科","实证科学","逻辑学科"],"a":[1],"exp":"","multi":false},{"no":2,"t":"杨振宁认为，物理学家用方程式写出了“造物者的不朽诗篇”，这句话谈论的是","o":["艺术美","社会美","自然美","科技美"],"a":[3],"exp":"","multi":false},{"no":3,"t":"朱熹将美育实现目标的过程表述为","o":["乐而不淫","化育万物","化性起伪","消融渣滓"],"a":[3],"exp":"","multi":false},{"no":4,"t":"提出“以美育代宗教”的中国现代学者是","o":["王国维","蔡元培","梁启超","朱光潜"],"a":[1],"exp":"","multi":false},{"no":5,"t":"1795年席勒在《美育书简》里第一次提出了","o":["审美教育","寓教于乐","娱情悦性","趣味教育"],"a":[0],"exp":"","multi":false},{"no":6,"t":"认为悲剧能起到“净化”效果的学者是","o":["柏拉图","亚里士多德","贺拉斯","席勒"],"a":[1],"exp":"","multi":false},{"no":7,"t":"克尔凯戈尔探讨悲剧的哲学基础是","o":["理性主义","经验主义","存在主义","实证主义"],"a":[2],"exp":"","multi":false},{"no":8,"t":"“将那人生无价值的撕破给人看”这句话所指的审美形态是","o":["悲剧","荒诞","丑","喜剧"],"a":[3],"exp":"","multi":false},{"no":9,"t":"康德认为，崇高给人带来的是","o":["积极的快乐","消极的快乐","游戏的快乐","想象的快乐"],"a":[1],"exp":"","multi":false},{"no":10,"t":"下列关于丑的表述不正确的是","o":["丑所引起的情绪感受仍然是一种审美情感","丑在形式上表现为反常、混乱，给人以不和谐感","丑揭示的是一种负面的生存实践","丑是对人生存在的无意义状态的体悟"],"a":[3],"exp":"","multi":false},{"no":11,"t":"中世纪美学在根本上属于","o":["哲学","神学","社会学","心理学"],"a":[1],"exp":"","multi":false},{"no":12,"t":"英伽登所说的艺术作品的“形而上质”体现了审美经验的","o":["超越性","直观性","非理性","非功利性"],"a":[0],"exp":"","multi":false},{"no":13,"t":"审美经验中，心理距离的产生需要借助于","o":["感知","情感","想象","理解"],"a":[2],"exp":"","multi":false},{"no":14,"t":"黑格尔认为美学研究的对象是","o":["美感","文化","艺术","自然"],"a":[2],"exp":"","multi":false},{"no":15,"t":"艺术最核心的功能是","o":["宣传","审美","教育","娱乐"],"a":[1],"exp":"","multi":false},{"no":16,"t":"从艺术意象的角度来说，与中国的“隐秀论”相近的西方理论是","o":["有意味的形式论","集体无意识说","表现论","符号论"],"a":[0],"exp":"","multi":false},{"no":17,"t":"西方18、19世纪的浪漫主义思潮标榜","o":["自我表现","形式创造","符号概括","理念传达"],"a":[0],"exp":"","multi":false},{"no":18,"t":"追溯艺术怎样存在，属于","o":["艺术认识论","艺术价值论","艺术本体论","艺术接受论"],"a":[2],"exp":"","multi":false},{"no":19,"t":"在艺术意象的创造、凝定和重建这一中心线索中，“凝定”涉及的是","o":["艺术创作","艺术品","艺术接受","艺术鉴赏"],"a":[1],"exp":"","multi":false},{"no":20,"t":"艺术创造的核心是","o":["意象的生成","情感的表现","对象的再现","形式的创造"],"a":[0],"exp":"","multi":false},{"no":21,"t":"审美是一种","o":["高级的人生境界","功利的人生境界","道德的人生境界","诗意的人生境界","自然的人生境界"],"a":[0,3],"exp":"","multi":true},{"no":22,"t":"胡吉弩斯认为，文学作品的崇高风格应该具有","o":["庄严伟大的思想","强烈深厚的热情","符合修辞格的藻饰","高尚的措辞","庄严宏伟的结构"],"a":[0,1,2,3,4],"exp":"","multi":true},{"no":23,"t":"下面美学流派中，属于西方现代美学的有","o":["经验主义","理性主义","科学主义","解释学","分析美学"],"a":[2,3,4],"exp":"","multi":true},{"no":24,"t":"给艺术下定义之所以困难的原因有","o":["现象无比丰富","标准和规则多变","价值尺度不确定","功能判断多元","无法定义"],"a":[0,1,2,3],"exp":"","multi":true},{"no":25,"t":"艺术品的基本特征有","o":["他律性","科学性","开放性","形式符号性","意义的确定性"],"a":[0,2,3],"exp":"","multi":true}],"essay":[{"no":26,"t":"审美理想","ans":"（1）是主体心目中关于完善的美的观念。（2）具有一定的形象性特点，始终显现在具体的审美表象中。（3）在主体的审美心理结构中处于最高的位置，一旦形成就具有很高的稳定性。","exp":"审美理想是主体对美的最高追求和标准，它源于审美实践，又反过来指导审美判断和创造，是审美活动的价值导向。","type":"名词解释"},{"no":27,"t":"交感思考","ans":"（1）是审美经验的构成阶段主体与对象之间的精神交流。（2）交感现象之所以发生，是因为审美对象是一种准主体。（3）交感现象的发生使审美理解成为一种双向交流。","exp":"交感思考指审美主体与对象之间进行情感和精神的互动沟通，对象被当作有生命、有情感的准主体，使审美体验具有对话性和参与性。","type":"名词解释"},{"no":28,"t":"悲剧","ans":"（1）悲剧这种审美形态是随着悲剧艺术的发展而产生的。（2）悲剧产生的根源是由人生与现实之间的矛盾所造成的冲突，这种冲突导致了有价值的事物的毁灭。（3）悲剧艺术通过对生活中的悲剧的表现，让人体会到了斗争的勇气和理想追求的力量感，从而引起情感的激荡和振奋。","exp":"悲剧不是单纯展示痛苦，而是通过对有价值事物毁灭的呈现，激发人的崇高感和抗争精神，在否定性体验中肯定人的尊严和价值。","type":"名词解释"},{"no":29,"t":"寓教于乐","ans":"（1）是古罗马贺拉斯在谈到文艺的功能时提出的。（2）美育应该符合文艺的规律，直接给人以感动。（3）文艺的教育功能与娱乐功能应该水乳交融、有机统一。","exp":"贺拉斯认为文艺既要寓教于乐，又要以乐为教，教育目的必须通过审美愉悦自然实现，而非生硬说教。这一原则深刻影响了西方美育传统。","type":"名词解释"},{"no":30,"t":"简析美学研究的核心方法。","ans":"（1）美学研究的核心方法是哲学方法，美学从诞生之日起就从属于哲学。（2）审美活动是人类最高级、最复杂的精神活动，不能仅仅依靠科学和实验方法。（3）美学涉及到人的生存实践等本源问题，只有哲学方法才能掌握。（4）美学作为一门理论学科，必须进行逻辑推演、抽象思辨和理论提升，离不开哲学思考。","exp":"美学始终是哲学的重要分支，其根本方法是哲学思辨。虽然美学也借鉴心理学、社会学等具体方法，但核心方法仍是哲学，因为审美本质、美与真善关系等问题无法通过实证解决。","type":"简答"},{"no":31,"t":"简述崇高的审美特征。","ans":"（1）雄伟壮阔的力量之美；（2）社会价值实现的昂扬之美；（3）刚毅坚强的品格之美；（4）恢弘豪迈的尊严之美。","exp":"崇高是人的精神力量在克服巨大困难或面对无限时所展现的美，具有力量感、昂扬感、刚毅感和尊严感，给人以震撼和升华。","type":"简答"},{"no":32,"t":"简述再造性想象与创造性想象的区别。","ans":"（1）再造性想象是指主体根据自己对事物的感知，在头脑中形成事物的心理表象。（2）创造性想象则不是为了再现事物，而是要通过主体的创造性思维产生新的表象。","exp":"再造性想象是对已有形象的复现，如读小说时在头脑中重构场景；创造性想象是无中生有，将不同素材组合成全新的形象，是艺术创造的核心能力。","type":"简答"},{"no":33,"t":"简述游戏与艺术的区别。","ans":"（1）游戏给予我们的是单纯的虚幻性，艺术提供给我们深刻的真实性。（2）游戏使人们沉浸在单纯的悠闲的快感中，艺术能以其深邃的思想内涵，给我们以审美快乐以外的人生启迪。","exp":"游戏虽具自由性，但缺乏深刻的意蕴和思想深度。艺术在愉悦之外，还承载着对人生、社会、存在的深刻思考，具有更高的精神价值。","type":"简答"},{"no":34,"t":"简述美育的怡情养性功能。","ans":"（1）美育能够对人的精神领域进行调节，从而达到心理的平衡、人格的完善。（2）美育的方式是从内心、从人的情感的角度去打动人的。（3）美育对人的感化能够使人亲和，充满爱心。","exp":"美育通过审美体验陶冶人的情感，净化心灵，调和理性与感性的冲突，使人性趋于和谐完善。它不同于德育的规训，而是以情动人、以美育人。","type":"简答"},{"no":35,"t":"结合具体的审美实践，阐述审美活动是人最具本己性的存在方式。","ans":"（1）人在审美活动中的存在不同于在日常生活中的存在，它是一种超越性的存在方式。（2）人在审美中的存在不同于在异化活动中的存在，它是一种自由的存在方式。（3）人在审美中的存在不同于人的现实存在，它是一种应然的存在方式。","exp":"审美活动是人最本真的存在方式，因为它使人超越功利、摆脱异化、实现自由。例如，当人沉浸于山水画或音乐时，暂时忘却日常烦恼，与作品融为一体，体验到精神解放和生命意义的充盈。这种存在状态最贴近人的本性和理想，故最具“本己性”。","type":"论述"},{"no":36,"t":"以李商隐的诗《锦瑟》为例，分析通过艺术想象创造艺术意象的过程。","ans":"（1）触物而感，“锦瑟无端五十弦”。（2）由这一感受引发体验，“一弦一柱思华年”。（3）再由这些体验引发过去的所见、所闻、所读，在想象中联成一体。“庄生晓梦迷蝴蝶，望帝春心托杜鹃。沧海月明珠有泪，蓝田日暖玉生烟。”（4）引发出强烈的感慨，“此情可待成追忆，只是当时已惘然。”","exp":"李商隐从锦瑟触发对年华的追忆，继而调动庄周梦蝶、望帝托鹃、鲛人泣珠、良玉生烟等历史文化意象，在想象中熔铸成一组迷离怅惘的审美意象群，最终升华为对人生如梦、往事难追的深沉感慨。整首诗充分体现了艺术想象整合感知、记忆、情感，创造全新意象世界的完整过程。","type":"论述"}]},{"id":"1804","year":2018,"month":4,"label":"2018年4月","choice":[{"no":1,"t":"“韵外之致，味外之旨”这句话揭示了审美对象的","o":["确定性","特殊性","实体性","开放性"],"a":[3],"exp":"“韵外之致，味外之旨”（司空图语）强调审美对象超越具体形式之外，具有无限延伸的意蕴空间，体现了审美对象的开放性，即意蕴不断生成、不可穷尽的特性。确定性、特殊性、实体性均不符合。","multi":false},{"no":2,"t":"达尔文认为，雌鸟有能力欣赏雄鸟羽毛的美好，这种观点属于审美发生理论中的","o":["游戏说","劳动说","生物本能说","巫术说"],"a":[2],"exp":"达尔文从进化论角度解释审美能力，认为动物也具有美感本能（如雌鸟对雄鸟羽毛的欣赏），这属于“生物本能说”。游戏说（席勒）、劳动说（普列汉诺夫）、巫术说（弗雷泽）均与达尔文观点不同。","multi":false},{"no":3,"t":"审美活动发生的真正前提是","o":["人开始直立行走","人开始制造和使用工具","人开始使用语言","人开始分工合作"],"a":[1],"exp":"制造和使用工具是人类生产劳动的标志，也是审美活动发生的真正前提。劳动不仅创造了人本身，也培养了人的审美感知能力和形式感。直立行走、使用语言、分工合作都是人类进化的重要环节，但制造工具是审美发生的直接前提。","multi":false},{"no":4,"t":"审美体验的获得需要借助于","o":["情感与想象","知识与信念","判断与推论","概括与反思"],"a":[0],"exp":"审美体验是主体深入对象、与之交融的情感状态，其核心心理机制是情感驱动和想象建构。知识与信念（B）、判断与推论（C）、概括与反思（D）属于理性认知活动，而非审美体验的获得方式。","multi":false},{"no":5,"t":"“夫美也者，上下、内外、大小、远近，皆无害焉。”这句话中的“美”是指","o":["崇高","优美","悲剧","喜剧"],"a":[1],"exp":"这句话出自《国语》，形容美的事物在各方面都和谐适宜、无过无不及，符合“优美”的特征——和谐、均衡、适度。崇高强调巨大与力量，悲剧涉及冲突与毁灭，喜剧涉及可笑与讽刺，均不符合。","multi":false},{"no":6,"t":"康德把崇高分为两种类型，即","o":["数量的崇高与体积的崇高","自然的崇高与人性的崇高","数学的崇高与力学的崇高","静态的崇高与动态的崇高"],"a":[2],"exp":"康德在《判断力批判》中将崇高分为“数学的崇高”（涉及数量的无限大，如星空）和“力学的崇高”（涉及力量的巨大，如暴风雨）。A、B、D均非康德的分类方式。","multi":false},{"no":7,"t":"审美形态的二重性，是指审美形态具有","o":["民族性与世界性","生成性与历史性","稳定性与当代性","连续性与阶段性"],"a":[0],"exp":"审美形态的二重性指其既是民族的（特定文化语境中形成），又是世界的（具有人类普遍性）。其他选项如生成性、历史性、稳定性、当代性等虽涉及审美形态的特征，但非“二重性”的特定内涵。","multi":false},{"no":8,"t":"下列关于荒诞的表述中不正确的是","o":["荒诞是一种现代审美形态","荒诞是人的异化与局限性的表现","荒诞是对人生存在的无意义状态的体悟","从内容看，荒诞更接近于喜"],"a":[3],"exp":"荒诞是一种现代审美形态（A正确），表现人的异化和局限性（B正确），体悟人生存在的无意义状态（C正确）。但从内容看，荒诞更接近于“悲”而非“喜”，它揭示的是非理性和虚无，虽然形式上可能有怪诞和可笑，但本质上是悲剧性的。D不正确。","multi":false},{"no":9,"t":"托马斯·门罗的美学思想属于","o":["理性主义","神秘主义","科学主义","人本主义"],"a":[2],"exp":"托马斯·门罗是科学主义美学的代表，主张用科学实验和实证方法研究审美现象，反对形而上学思辨。理性主义（笛卡尔、康德）、神秘主义（柏拉图某些方面）、人本主义（马克思、萨特）均不属其思想归属。","multi":false},{"no":10,"t":"里普斯说：“审美的欣赏并非对于一个对象的欣赏，而是对于一个自我的欣赏。”这句话所体现的美学观是","o":["内在感官说","移情说","比德说","畅神说"],"a":[1],"exp":"里普斯是“移情说”的代表人物，这句话表明审美欣赏实质上是主体将自我情感投射到对象中，在对象上欣赏自我，正是移情说的核心。内在感官说（夏夫兹博里）、比德说（孔子）、畅神说（中国魏晋美学）均不属此。","multi":false},{"no":11,"t":"荣格关于艺术起源的学说是","o":["模仿说","游戏说","劳动说","集体无意识说"],"a":[3],"exp":"荣格从分析心理学出发，认为艺术起源于人类的“集体无意识”和原型，艺术是原型意象的象征性表达。模仿说（亚里士多德）、游戏说（席勒）、劳动说（普列汉诺夫）均非荣格的观点。","multi":false},{"no":12,"t":"艺术品具有审美特质的根源是","o":["形式","意象","主题","情感"],"a":[1],"exp":"艺术品之所以具有审美特质，其根源在于“意象”——意象是情感与形象的融合，是审美价值的核心载体。形式是意象的外壳，主题和情感是意象的构成要素，但根源是意象本身。","multi":false},{"no":13,"t":"创作主体与接受主体之间的中介与桥梁是","o":["艺术欣赏","艺术品","艺术家","艺术技巧"],"a":[1],"exp":"艺术品是连接创作主体（艺术家）和接受主体（欣赏者）的中介与桥梁。艺术家通过创作产生艺术品，欣赏者通过艺术品理解艺术家的意图和情感，故B正确。艺术欣赏是接受活动，艺术家是创作主体，艺术技巧是手段。","multi":false},{"no":14,"t":"艺术家感受和体验世界、孕育审美意象的基础与起点是","o":["艺术想象","艺术鉴赏","艺术体验","艺术敏感"],"a":[3],"exp":"艺术敏感是艺术家对生活中潜在美感的敏锐捕捉能力，是感受世界、孕育意象的基础与起点。艺术体验（C）是进一步深化，艺术想象（A）是加工过程，艺术鉴赏（B）是接受活动。","multi":false},{"no":15,"t":"和“艺术操作与技巧”相关的是","o":["手中竹","眼中竹","胸中竹","山中竹"],"a":[0],"exp":"郑板桥提出“眼中之竹”（感知）、“胸中之竹”（意象）、“手中之竹”（物化），其中“手中之竹”涉及艺术操作与技巧，即将心中意象转化为物质形式。山中竹为客观原型，眼中竹为感知材料，胸中竹为意象构思。","multi":false},{"no":16,"t":"黑格尔把艺术分为三种类型，分别是象征型、古典型和","o":["抽象型","原始型","写实型","浪漫型"],"a":[3],"exp":"黑格尔按理念与形式的关系将艺术分为象征型（形式大于内容）、古典型（内容与形式统一）、浪漫型（内容大于形式）。抽象型、原始型、写实型均非黑格尔的术语。","multi":false},{"no":17,"t":"提出“哀而不伤，乐而不淫”原则的思想家是","o":["孔子","孟子","荀子","庄子"],"a":[0],"exp":"孔子在《论语·八佾》中评价《关雎》“乐而不淫，哀而不伤”，强调情感表达应适度中和，体现了儒家的中庸思想和美育原则。孟子、荀子、庄子均未提出此论断。","multi":false},{"no":18,"t":"王国维在《论教育之宗旨》一文中","o":["认为美育是一种“人格教育”","认为美育是一种“趣味教育”","将美育与德育、智育、体育并称四育","提出“寓教于乐”"],"a":[2],"exp":"王国维在《论教育之宗旨》中首次将美育与德育、智育、体育并列为教育的四个组成部分。人格教育（蔡元培）、趣味教育（梁启超）、寓教于乐（贺拉斯）均非王国维在该文中的观点。","multi":false},{"no":19,"t":"柏拉图强调“音乐教育比其他教育都重要得多”的理由是","o":["节奏与乐调有最强烈的力量浸入心灵的最深处","音乐是古希腊最流行的艺术形式","只有音乐才能提高人们的审美感受力","音乐比其他艺术更易于普及"],"a":[0],"exp":"柏拉图在《理想国》中认为音乐教育最重要，因为节奏和乐调最能直接深入人的心灵，影响性格和情感。B、C、D均不是柏拉图的核心论证理由。","multi":false},{"no":20,"t":"认为“艺术对象创造出懂得艺术和能够欣赏美的大众”的思想家是","o":["亚里士多德","席勒","马克思","恩格斯"],"a":[2],"exp":"马克思在《〈政治经济学批判〉导言》中提出这一观点，强调艺术不仅是被欣赏的对象，也反过来培养和创造懂得欣赏它的主体。席勒主要论述美育，亚里士多德论悲剧净化，恩格斯相关论述较少，故C正确。","multi":false},{"no":21,"t":"下列关于审美活动的价值内涵的表述正确的有","o":["审美活动能够满足人的心灵需要","审美活动能够帮助人们领悟人生真谛","审美活动包含着对“真”的追求","审美活动包含着对“善”的追求","审美活动是对主体存在的充分肯定"],"a":[0,1,2,3,4],"exp":"审美活动作为特殊的价值活动，满足人的心灵需要（A），启迪人生真谛（B），在审美中追求真（C）与善（D），同时充分肯定主体的存在（E）。五个选项均正确。","multi":true},{"no":22,"t":"模仿说的缺陷在于忽视了","o":["艺术与现实的关系","艺术创造的主体性","艺术创造的表现性","艺术自身的审美特性","艺术创造的再现性"],"a":[1,2,3],"exp":"模仿说强调艺术对现实的再现，其缺陷在于：忽视了艺术创造的主体性（B，艺术家主观能动性）、表现性（C，情感表达）和艺术自身的审美特性（D，形式与美感）。A（艺术与现实的关系）是模仿说所关注的，E（再现性）是模仿说所强调的，均不属缺陷。","multi":true},{"no":23,"t":"以下对“自然天才”的表述正确的有","o":["凭借自然才华","按照规则行事","无需技艺和学识","重视技艺与学识","强调模仿与借鉴"],"a":[0,2],"exp":"“自然天才”概念强调艺术家凭借天赋自然才华进行创作（A），无需依赖技艺和学识（C）。B（按规则行事）、D（重视技艺学识）、E（强调模仿借鉴）均属“人工天才”或有规则指导的创作方式，非“自然天才”的特征。","multi":true},{"no":24,"t":"下列对“以道制欲”原则的表述正确的有","o":["是对人的感性欲望的约束","是理性对感性的节制和净化","张扬人的感性欲望","有助于心灵的和谐健康","体现了美育的情与理的统一"],"a":[0,1,3,4],"exp":"“以道制欲”是以理性原则约束感性欲望（A），体现理性对感性的节制和净化（B），有助于心灵和谐（D），体现了美育中情与理的统一（E）。C（张扬感性欲望）与此原则相悖，故不选。","multi":true},{"no":25,"t":"接受者在美育过程中的能动性主要表现在","o":["通过道德约束自己","无条件的接受","有自觉的追求","体现着一定的创造性","能获得广博的知识"],"a":[2,3],"exp":"接受者在美育过程中不是被动接受，而是具有能动性，表现为有自觉的追求（C）和体现一定的创造性（D，如对作品的再创造）。A（道德约束）与美育的审美特性不符，B（无条件接受）是被动性，E（获得知识）是智育功能而非美育能动性的核心表现。","multi":true}],"essay":[{"no":26,"t":"交感巫术","ans":"（1）弗雷泽在《金枝》中提出的概念。（2）指通过信念来使物体不受时空限制而相互作用。","exp":"交感巫术基于“相似律”和“接触律”，认为事物之间可以通过神秘联系相互影响，如模拟某物可影响其本身。它是原始思维的重要形式，对巫术仪式和原始艺术的产生有推动作用。","type":"名词解释"},{"no":27,"t":"崇高","ans":"（1）是一种基本的审美形态。（2）崇高的对象具有粗犷、博大的形态，劲健的力量，雄伟的气势。（3）能给人以心灵的震撼，能让人产生敬仰和赞叹的情怀，从而提升人的精神境界。","exp":"崇高是主体在面对巨大、强大或无限对象时，经短暂抗拒后产生精神升华的审美体验，它激发人的理性力量和尊严感，是优美之外的另一种重要审美形态。","type":"名词解释"},{"no":28,"t":"超验意境层","ans":"（1）是艺术品的层次结构之一。（2）是意象世界背后所蕴含的形而上的人生哲理。（3）能够把艺术品推向更高层次。","exp":"超验意境层是艺术品最深层的意蕴，超越了具体的意象和情感，指向宇宙、人生、存在等根本性问题，使艺术具有哲学性和永恒性。","type":"名词解释"},{"no":29,"t":"期待视野","ans":"（1）是接受美学提出的一个美学概念。（2）是指接受者的接受眼光和特定审美文化心理结构。（3）是在接受者的生理素质、文化教育、传统积淀以及所处的社会历史环境等基础上形成的。","exp":"期待视野是接受美学（姚斯）的核心概念，指读者在阅读前已有的审美经验和期待指向，它决定了读者对作品的接受态度和理解深度，也影响着作品意义的生成。","type":"名词解释"},{"no":30,"t":"简述普列汉诺夫的“劳动说”。","ans":"（1）劳动先于艺术。（2）人的心理本性中潜在地包含着审美的要求，只有通过劳动才能使之转化为现实。（3）人的审美能力也是在劳动中形成的，并与生产力的发展水平相一致。","exp":"普列汉诺夫在《没有地址的信》中系统论证了艺术起源于劳动。劳动不仅创造了艺术表现的对象和工具，也培养了人的节奏感、形式感等审美能力，审美意识随着生产实践的发展而发展。","type":"简答"},{"no":31,"t":"简述黑格尔的悲剧理论。","ans":"（1）把辩证思维的方法运用到悲剧现象的分析之中，提出了悲剧冲突的概念。（2）悲剧的产生源于理念的分裂，体现为人们的伦理观念和道德理想之间的冲突。（3）悲剧冲突的双方都具有一定的合理性，同时又都具有一定的片面性。","exp":"黑格尔认为悲剧不是善与恶的简单对立，而是两种合理伦理力量的冲突，由于各自片面性导致毁灭，在毁灭中实现“永恒正义”的和解。这一理论深刻揭示了悲剧的辩证本质。","type":"简答"},{"no":32,"t":"简析形式符号层在艺术品层次结构中的作用。","ans":"（1）是艺术品的直接性物质存在。（2）有独立的审美价值。（3）直接指示、负载着艺术的意象世界。","exp":"形式符号层（色彩、线条、音符、词语等）是艺术品最外在的层面，它既是意象的物质载体，又具有自身的形式美（如韵律、对称），是欣赏者首先接触并借以进入意象世界的通道。","type":"简答"},{"no":33,"t":"简述划分艺术类型的三种标准。","ans":"（1）根据艺术与现实之间的关系。（2）根据艺术作品与欣赏者之间的关系。（3）根据艺术作品自身的存在方式。","exp":"艺术分类的三种主要标准：一是按艺术与现实的关系（如模仿、表现），二是按艺术与接受者的关系（如听觉艺术、视觉艺术、综合艺术），三是按作品自身存在方式（时间艺术、空间艺术、时空艺术）。","type":"简答"},{"no":34,"t":"简述美育化性起伪的功能。","ans":"（1）是荀子提出的美育思想。（2）性是人生来就有的自然本质，伪则指在自然本质基础上发展起来的精神形态和能力。（3）“化性起伪”是指通过艺术与环境对人进行塑造，使人的自然本性转化为人性。","exp":"荀子认为人本性有恶的倾向，需要通过礼乐艺术等“伪”（人为教化）来改造和提升，使自然本能升华为符合道德和审美的人性，这正是美育的社会功能所在。","type":"简答"},{"no":35,"t":"为什么说美学应当以实践存在论为哲学基础？","ans":"（1）马克思的存在论是以实践论为根基的，而马克思的实践论则内在地包含着存在论维度，实践论与存在论的结合，构成了美学的哲学基础。（2）人的存在与世界的存在、人的审美感觉与现实的审美对象都是在实践中双向建构、同步发展的。（3）自由是从美学的哲学基础向美学的内在问题过渡的中介概念，也是从人的实践—存在向审美现象、审美活动过渡的中介环节。","exp":"实践存在论克服了传统主客二分的局限，认为审美活动是在实践中人与世界相互生成的过程。审美既不是纯主观感受，也不是纯客观属性，而是在实践中历史地生成的存在方式。自由作为实践的最高境界，正是审美发生的条件，因此美学必须以实践存在论为根基。","type":"论述"},{"no":36,"t":"宋郭若虚《图画见闻志》记载：“唐阎立本至荆州，观张僧繇旧迹，曰：‘定虚得名耳。’明日又往，曰：‘犹是近代佳手？’明日又往，曰：‘名下无虚士。’坐卧观之，留宿其下，十余日不能去。”试以这段话为例，说明审美经验中评价活动的特点。","ans":"（1）审美评价是一种反思判断，需要主体从特殊对象出发寻找到普遍的原则。（2）审美主体在评价活动中所把握到的意义来自于对象的深度，这种深度隐藏在对象的外观背后。（3）对于审美对象的深度体验需要借助于交感思考，这种思考是主体与对象之间的双向交流。","exp":"阎立本三次观看张僧繇画作，评价从否定到肯定，经历了“观—品—悟”的深入过程。这体现了审美评价不是瞬间判断，而是需要反复体验、逐步深入。第一次仅见外观，第三次则领悟了对象深层的美学价值，说明审美评价是反思性的、动态的，要求主体悬置成见、深度参与，最终在主客交感中把握意义的深度。","type":"论述"}]},{"id":"1810","year":2018,"month":10,"label":"2018年10月","choice":[{"no":1,"t":"美学研究的核心方法是","o":["社会学方法","人类学方法","哲学方法","心理学方法"],"a":[2],"exp":"美学从诞生之日起就属于哲学的分支，审美活动的本质、价值、意义等问题需要通过哲学思辨和逻辑推演来把握，故核心方法是哲学方法。社会学、人类学、心理学方法可作为辅助，但非核心。","multi":false},{"no":2,"t":"美学的哲学基础是马克思主义的","o":["实践存在论","实践认识论","科学社会主义","意识形态论"],"a":[0],"exp":"马克思主义美学以实践存在论为哲学基础，强调审美活动是人在实践中与世界双向建构的存在方式。实践认识论（B）侧重认识论维度，科学社会主义（C）是政治理论，意识形态论（D）是上层建筑理论，均不全面。","multi":false},{"no":3,"t":"蒋孔阳主张美学研究的根本问题是","o":["审美经验","艺术","人对现实的审美关系","美和美的规律"],"a":[2],"exp":"蒋孔阳在《美学新论》中明确提出“美学的根本问题是研究人对现实的审美关系”。审美经验（A）、艺术（B）、美和美的规律（D）都是审美关系的具体展开，非根本问题。","multi":false},{"no":4,"t":"人类审美活动发生的最重要标志是","o":["原始巫术活动的出现","原始劳动分工的出现","史前彩陶纹饰的出现","原始审美意识的出现"],"a":[3],"exp":"审美活动发生的根本标志是原始审美意识的出现，即人类开始自觉地从审美角度感受和创造对象。巫术活动、劳动分工、彩陶纹饰都是审美意识产生的前提或表现，而非标志本身。","multi":false},{"no":5,"t":"审美活动的两个基本要素是","o":["审美主体和审美创造","审美客体和审美接受","审美主体和审美接受","审美主体和审美对象"],"a":[3],"exp":"审美活动的基本要素是审美主体（进行审美的人）和审美对象（被审美的事物），二者在审美活动中相互生成。审美创造、审美接受是活动环节，审美客体是对象的不同表述。","multi":false},{"no":6,"t":"席勒认为人摆脱动物状态达到人性的主要标志是","o":["巫术","音乐","游戏","舞蹈"],"a":[2],"exp":"席勒在《审美教育书简》中提出，人只有在“游戏”中才是真正的人，游戏冲动调和感性冲动与理性冲动，是人性实现的标志。巫术、音乐、舞蹈都是具体活动，而非人性标志。","multi":false},{"no":7,"t":"审美活动本身就是一个自身完满的世界，这表明审美活动具有","o":["自律性","因果律","他律性","三一律"],"a":[0],"exp":"审美活动不以外部目的为根据，以自身为目的，这种自我规定性即为“自律性”。因果律是科学规律，他律性相反，三一律是戏剧规范，均不属此。","multi":false},{"no":8,"t":"亚里士多德认为，“美的最高形式是秩序、匀称和确定性”，这里所说的美主要是指","o":["崇高","优美","悲剧","喜剧"],"a":[1],"exp":"亚里士多德这句话描述的是和谐、均衡、有序的美，这正是“优美”的特征。崇高强调巨大与力量，悲剧涉及冲突与毁灭，喜剧涉及可笑与讽刺，均不符合。","multi":false},{"no":9,"t":"首先把辩证思维的方法引进悲剧理论的美学家是","o":["亚里士多德","黑格尔","尼采","马克思"],"a":[1],"exp":"黑格尔首次运用辩证思维分析悲剧，提出悲剧是两种合理伦理力量的冲突与和解。亚里士多德（A）提出净化说但非辩证思维，尼采（C）侧重酒神精神，马克思（D）虽继承辩证法但晚于黑格尔。","multi":false},{"no":10,"t":"审美经验是","o":["纯粹的感性活动","纯粹的理性活动","一种理性直观活动","感性直观和本质直观的统一"],"a":[3],"exp":"审美经验既包含对感性形象的直观（感知），也包含对深层意蕴的把握（本质直观），二者统一于审美体验中。纯粹的感性或理性活动都片面，理性直观（C）不全面。","multi":false},{"no":11,"t":"《荀子·乐论》云：“以道制欲，则乐而不乱。”这句话涉及到审美经验中","o":["情感与想象的关系","情感与理智的关系","想象与感知的关系","想象与理智的关系"],"a":[1],"exp":"“以道制欲”意为用理性原则（道）约束感性欲望（欲），涉及审美经验中情感与理智的关系。A、C、D中的“想象”和“感知”在此句中未涉及。","multi":false},{"no":12,"t":"《礼记·乐记》中的“心生说”，从艺术本质论的角度来说，大致可以划入","o":["符号说","游戏说","模仿说","表现说"],"a":[3],"exp":"“心生说”认为乐舞等艺术形式是内心情感的自然流露和表现，这与“表现说”（艺术是情感的表现）一致。符号说（朗格）、游戏说（席勒）、模仿说（亚里士多德）均不属此。","multi":false},{"no":13,"t":"古希腊语中的“艺术”一词指的是","o":["模仿","技艺","创造","审美"],"a":[1],"exp":"古希腊语“techne”指技艺、技能，包括手工制作和艺术创作，强调规则和技巧。模仿（mimesis）是艺术的功能，创造和审美是后世赋予的内涵。","multi":false},{"no":14,"t":"艺术品结构中最为重要、最为核心的层次是","o":["形式符号层","意境超验层","意象世界层","物质实在层"],"a":[2],"exp":"意象世界层是艺术品结构的核心，它承载着审美价值和情感意蕴。物质实在层（D）是载体，形式符号层（A）是媒介，意境超验层（B）是意象的升华，核心是意象本身。","multi":false},{"no":15,"t":"苏珊·朗格主张艺术作为符号形式应当表现","o":["人类情感","绝对精神","无意识","意识形态"],"a":[0],"exp":"苏珊·朗格在《情感与形式》中提出艺术是“人类情感的符号形式的创造”，艺术表现的是人类普遍的情感形式。绝对精神（黑格尔）、无意识（荣格）、意识形态（马克思主义）均非其核心主张。","multi":false},{"no":16,"t":"宗白华认为，中国美学史上最具有世界贡献的范畴是","o":["境界","意象","神韵","意境"],"a":[3],"exp":"宗白华高度评价中国美学的“意境”范畴，认为它是中国文化最核心且对世界有独特贡献的方面。境界、意象、神韵虽相关，但意境是宗白华特别推崇的。","multi":false},{"no":17,"t":"孕育艺术意象的内在动力是","o":["主体对于客体的认识","主体对于客体的反思","主客体间的感动关系","主客体间的反映关系"],"a":[2],"exp":"意象的孕育源于主客体之间的情感感动关系，即主体被客体激发情感，在情感驱动下形成意象。认识（A）、反思（B）、反映（D）均属认知关系，非审美动力。","multi":false},{"no":18,"t":"在生产意象的过程中最有决定性的艺术创造力是","o":["想象力","艺术敏感","灵感","判断力"],"a":[0],"exp":"想象力是意象生成的核心能力，它整合感知、情感和素材，创造出独特的审美意象，因此最有决定性。艺术敏感（B）是起点，灵感（C）是突发状态，判断力（D）是理性能力。","multi":false},{"no":19,"t":"将小说对人的感化作用看成熏、浸、刺、提四种力的学者是","o":["王国维","蔡元培","梁启超","朱光潜"],"a":[2],"exp":"梁启超在《论小说与群治之关系》中提出小说感化人的四种力：熏（潜移默化）、浸（沉浸感染）、刺（突然刺激）、提（精神提升）。王国维、蔡元培、朱光潜均未提出此概括。","multi":false},{"no":20,"t":"古罗马的贺拉斯对于美育理论的主要贡献在于提出了","o":["“寓教于乐”","“三一律”","“上帝即是美”","“诗应该离开教会”"],"a":[0],"exp":"贺拉斯在《诗艺》中提出“寓教于乐”原则，强调文艺应寓教育于审美愉悦之中。“三一律”（B）是古典主义戏剧规范，“上帝即是美”（C）是中世纪美学观，“诗应该离开教会”（D）是文艺复兴时期的主张。","multi":false},{"no":21,"t":"“生物本能说”的不足之处在于","o":["混淆和抹杀了动物的本能活动与人的有意识的生命活动之间的区别","把动物的快感等同于人的美感","忽视了人的审美活动中所包含的生理性因素","忽视了对人的审美活动赖以发生的社会根源的探讨","忽视了动物的本能活动与审美活动的关联"],"a":[0,1,3],"exp":"“生物本能说”的不足在于：混淆动物本能与人的意识活动（A），将动物快感等同于人的美感（B），忽视审美活动的社会根源（D）。C（忽视生理因素）和E（忽视关联）不是其不足——该学说恰恰过分强调生理因素和关联，故排除。","multi":true},{"no":22,"t":"审美形态的历史性主要表现在","o":["它是特定的历史社会文化发展阶段的产物","它是审美能力中先天就有的","它是审美体验的反思性产物","它的具体内涵是在历史发展中不断演变的","它是民族性与世界性的统一"],"a":[0,3],"exp":"审美形态的历史性表现为：它是特定历史阶段的产物（A），其内涵随历史演变（D）。B（先天就有）是反历史性的，C（反思性产物）侧重生成机制，E（民族性与世界性）是二重性而非历史性。","multi":true},{"no":23,"t":"审美经验中涉及到的想象活动的高级形式包括","o":["接近联想","类似联想","对比联想","再造性想象","创造性想象"],"a":[3,4],"exp":"想象活动的高级形式是再造性想象和创造性想象，前者复现已有形象，后者创造全新形象。A（接近联想）、B（类似联想）、C（对比联想）属于联想，是想象的低级形式。","multi":true},{"no":24,"t":"以下艺术类型中属于空间艺术的有","o":["建筑","雕塑","绘画","书法","音乐"],"a":[0,1,2,3],"exp":"空间艺术是以空间存在方式呈现的艺术，包括建筑、雕塑、绘画、书法等。音乐（E）是时间艺术，非空间艺术，故不选。","multi":true},{"no":25,"t":"下列关于“化性起伪”的表述正确的有","o":["是对美育功能的表述","重视美育对人的后天影响","是对人的先天本性的伪装","对人的先天本性持否定态度","要求美育过程中注意因势利导"],"a":[0,1,4],"exp":"“化性起伪”是荀子对美育功能的表述（A），强调后天教化（B），要求因势利导（E）。C（伪装）是对“伪”的误解——荀子的“伪”指人为教化；D（持否定态度）不准确——荀子虽主性恶，但主张通过教化转化而非彻底否定。","multi":true}],"essay":[{"no":26,"t":"趣味教育","ans":"（1）梁启超提出的美育观，认为美育是一种趣味教育。（2）强调趣味对人的激发和影响。（3）拿趣味当目的。","exp":"梁启超认为美育的本质是“趣味教育”，主张以审美活动激发人的生命情趣，使人达到精神充实和人格完善。他强调“拿趣味当目的”才是真正的美育，区别于以趣味为手段的普通教育。","type":"名词解释"},{"no":27,"t":"抽象","ans":"（1）指创作主体经过加工，舍弃对象的具象性，运用纯粹的形式符号，创造出来的一种审美意象。（2）它不具有再现性、概念性和比喻性。","exp":"抽象作为意象的一种类型，不模仿具体物象，也不通过概念或比喻表达意义，而是通过纯粹的点、线、面、色等形式符号直接呈现审美情感，如抽象绘画。","type":"名词解释"},{"no":28,"t":"灵感","ans":"（1）是在艺术家的生理心理素质、生活体验和学养积累基础上形成的。（2）是艺术家创造力极为旺盛、勃发时一种神思活跃、意象奔涌的心理状态。","exp":"灵感是艺术创造中突然迸发的顿悟状态，表现为思路畅通、意象涌现。它以长期积累为基础，但又超越常规思维，具有突发性、创造性和短暂性。","type":"名词解释"},{"no":29,"t":"审美需要","ans":"（1）是人渴望实现自己、肯定自己，并按照自己的人生理想自由而完整地发展自己的精神要求。（2）是随着人的精神能力的发展而逐步生成的。（3）是人所独有的一种本质力量。","exp":"审美需要是人类超越功利、追求精神自由的内在驱动力，是审美活动发生的主观前提。它既是人的本质力量的体现，也是人在实践中不断生成的精神需求。","type":"名词解释"},{"no":30,"t":"简述审美境界的主要特点。","ans":"（1）是人与世界、情与景、感性与理性的有机统一。（2）能够超越个体眼前的功利性和有限性，达到相对自由的状态。（3）有高低不同的层次。","exp":"审美境界是主体在审美活动中达到的精神状态，它融合主客、情物、感理，超越功利束缚，使人获得精神自由。同时，审美境界有层次之分，从浅层的愉悦到深层的人生感悟，体现境界的高低。","type":"简答"},{"no":31,"t":"简述审美对象形式规律的多样统一性原则。","ans":"（1）是审美对象最基本、最普遍的一种形式规律，是寓多于一，在变化中显统一，在统一中见变化。（2）所谓多样性，是指审美对象所包含的各个物质因素在形式上的区别与差异。（3）所谓统一性，是指审美对象各个部分在整体中彼此关联、呼应的内在关系。","exp":"多样统一是形式美的最高法则，它要求审美对象既要有丰富的差异变化，又要有整体的和谐协调，二者缺一不可，否则会流于杂乱或单调。","type":"简答"},{"no":32,"t":"简述意象与意境的联系。","ans":"意象是构成意境的前提和基础，意境是意象的升华和归宿。意境由多个意象整体融合而成，超越了具体意象的有限性，指向更深远的哲理和情感空间。","exp":"意象是个别的、具体的审美形象，意境是意象群整体营造出的深层境界。有意象未必有意境，有意境必有意象。意境是对意象的超越和升华，更具形而上意味。","type":"简答"},{"no":33,"t":"简述艺术想象力的特点。","ans":"（1）艺术想象力是艺术家在感知基础上，通过记忆、联想、情感等心理机制，创造新形象的能力。（2）它具有创造性，能超越现实局限，生成非现实的审美意象。（3）它受情感驱动，想象的方向和内容与艺术家的情感体验密切相关。","exp":"艺术想象力不同于日常联想，它是艺术创造的灵魂。它不仅再现已有形象，更能创造前所未有、情理交融的意象，情感是想象的动力和导向。","type":"简答"},{"no":34,"t":"简述审美教育的内涵。","ans":"审美教育是以艺术和各种美的形态为媒介，通过审美活动展示审美对象丰富的价值意味，直接作用于受教者的情感世界，从而潜移默化地塑造和优化人的心理结构、铸造完美人性、提升人生境界的有组织、有目的的定向教育方式。","exp":"美育不同于智育和德育，它以情感为中介，以审美体验为途径，旨在培养人的感性素养、审美能力和健全人格。其效果是潜移默化的，而非强制灌输。","type":"简答"},{"no":35,"t":"举例论述悲剧审美形态的特征。","ans":"（1）悲剧通过对人生存在的否定性体验，展现对人生存在价值的肯定。（2）悲剧的审美冲突体现的是人与自然、社会及自身存在的冲突与超越。（3）悲剧使人在毁灭中看到崇高，在痛苦中获得精神升华。","exp":"悲剧不是单纯的苦难展示，而是通过有价值事物的毁灭，激发人对生命意义的追问。例如，索福克勒斯《俄狄浦斯王》中，主人公虽无法逃脱命运，但其抗争体现了人的尊严和勇气；莎士比亚《哈姆雷特》中，主人公在复仇冲突中的犹豫与决断，展现了人性的深度。悲剧让观众在怜悯与恐惧中实现情感净化，进而感受到超越性价值。","type":"论述"},{"no":36,"t":"瑞士美学家布洛曾经说过，当轮船在海上遇到大雾的时候，乘客们会感到十分紧张和焦虑，但如果他们能够与大雾保持一定的心理距离，就能够从中获得审美的愉悦。试以此例说明审美距离在审美经验中的作用。","ans":"（1）审美距离使主体与对象之间摆脱功利关系，进入纯粹的观照状态。（2）心理距离能切断日常实用态度，使对象的形式和意蕴成为注意力的焦点。（3）距离既不能太近（否则被功利束缚），也不能太远（否则失去情感联系），适度距离是审美经验产生的关键。","exp":"布洛的“心理距离说”指出，审美态度的核心在于与对象保持适当的距离。海上大雾本身是危险信号，使人焦虑，但若将注意力从“大雾对航行的危害”转向“大雾的形态、光线、流动感”等形式特征，就进入了审美状态。距离不是物理隔离，而是心理态度的转变——搁置功利需求，专注于对象的外观和意味。这正是审美经验区别于日常经验的根本所在。","type":"论述"}]},{"id":"1904","year":2019,"month":4,"label":"2019年4月","choice":[{"no":1,"t":"在西方现代美学中，实用主义美学的代表是","o":["克罗齐","桑塔亚那","杜威","柏格森"],"a":[2],"exp":"杜威是实用主义美学的主要代表，著有《艺术即经验》。克罗齐是表现主义，桑塔亚那是自然主义美学，柏格森是直觉主义，均非实用主义美学的代表人物。","multi":false},{"no":2,"t":"“爱屋及乌”现象属于","o":["接近联想","类似联想","对比联想","回忆联想"],"a":[0],"exp":"“爱屋及乌”指因喜爱某人而连带喜爱与其相关的事物，属于接近联想（事物在时间或空间上接近而形成联想）。类似联想（B）基于相似性，对比联想（C）基于对立性，回忆联想（D）基于记忆再现。","multi":false},{"no":3,"t":"把审美判断的普遍性归结为“共通感”的美学家是","o":["柏拉图","亚里士多德","康德","黑格尔"],"a":[2],"exp":"康德在《判断力批判》中提出“共通感”（sensus communis），用以解释审美判断为什么具有普遍可传达性。柏拉图、亚里士多德、黑格尔均未使用这一概念来解释审美判断的普遍性。","multi":false},{"no":4,"t":"表现说的主要不足在于","o":["忽视艺术的形式技巧","无视主体的情感","回避艺术与现实的联系","没有突出艺术的政治教化作用"],"a":[2],"exp":"表现说强调艺术是情感的表现，其不足在于过分强调主体情感，而回避了艺术与客观现实的联系。A（忽视形式技巧）和B（无视主体情感）与表现说的实际特征相反，D（政治教化）不是表现说关注的重点。","multi":false},{"no":5,"t":"将艺术品分为符号和意义两个层次的学说是","o":["解构主义美学","形式主义美学","符号学美学","表现主义美学"],"a":[2],"exp":"符号学美学（如苏珊·朗格）将艺术品分为符号形式（载体）和意义（情感意蕴）两个层次。解构主义、形式主义、表现主义均不作此二元划分。","multi":false},{"no":6,"t":"意向与人们内在情感形式相联系便构成了审美心理的","o":["理想状态","基础动力","超验意境","形式符号"],"a":[1],"exp":"审美心理的基础动力是情感，意向（审美主体的指向性）与内在情感形式相结合，构成推动审美活动开展的基础动力。理想状态（A）、超验意境（C）、形式符号（D）均非情感与意向结合的直接产物。","multi":false},{"no":7,"t":"表现说兴起于","o":["18、19世纪西方浪漫主义思潮","16世纪文艺复兴时期","德国狂飙突进运动","1848年欧洲革命时期"],"a":[0],"exp":"表现说作为自觉的艺术理论兴起于18世纪末19世纪初的浪漫主义思潮，强调艺术是艺术家主观情感的表现。文艺复兴（B）以模仿说为主，狂飙突进（C）是德国浪漫主义的前奏但非表现说正式兴起标志，1848年革命（D）与表现说无直接关系。","multi":false},{"no":8,"t":"不属于美育特点的是","o":["诉诸感性","潜移默化","能动性","实用性"],"a":[3],"exp":"美育的特点包括诉诸感性（A）、潜移默化（B）、能动性（C）等。实用性（D）不是美育的特点，美育以精神陶冶为目的，而非实用功利。","multi":false},{"no":9,"t":"“以美启真”指的是","o":["智育对美育起促进作用","美育对智育起促进作用","美育对智育起决定作用","智育对美育起决定作用"],"a":[1],"exp":"“以美启真”是指美育对智育起促进作用，即通过审美教育激发人的好奇心和创造力，推动科学认知的发展。A、D颠倒关系，C夸大美育的作用。","multi":false},{"no":10,"t":"“习与性成”说明美育","o":["要注意因势利导","是修身养性的过程","是潜移默化的过程","是率性而为的行为"],"a":[2],"exp":"“习与性成”意为习惯养成性格，说明美育对人的影响是长期的、渐进的、潜移默化的过程。A（因势利导）是方法，B（修身养性）是目的，D（率性而为）与之相反。","multi":false},{"no":11,"t":"率先把西方美育思想引入中国的是","o":["王国维","严复","蔡元培","陈独秀"],"a":[2,2],"exp":"蔡元培率先将西方美育思想系统引入中国，并在教育实践中推行美育。王国维虽较早介绍西方美学，但系统引入美育思想的是蔡元培。严复主要引入进化论，陈独秀主要引入民主与科学。","multi":true},{"no":12,"t":"艺术接受的核心是","o":["意象的物化与传达","意象的传达与构建","意象的创造与表现","意象的生成与重建"],"a":[3],"exp":"艺术接受的核心是意象的生成（接受者从作品中感受意象）与重建（接受者根据自身经验对意象进行再创造）。A和C属于艺术创作阶段，B中的“传达”属创作环节。","multi":false},{"no":13,"t":"艺术本体论的核心问题是","o":["展示艺术的存在方式","说明艺术的本质","阐述艺术的特征","揭示艺术的规律"],"a":[0],"exp":"艺术本体论探讨艺术的根本存在方式，即“艺术怎样存在”。B（本质）、C（特征）、D（规律）虽相关，但本体论的核心是存在方式问题。","multi":false},{"no":14,"t":"艺术天才的形成主要由于","o":["纯粹的自然禀赋","纯粹的后天努力","天助神功","先天的生理心理结构与后天的实践"],"a":[3],"exp":"艺术天才既需要先天的生理心理禀赋，也离不开后天的实践和修养。纯粹的自然禀赋（A）或纯粹的后天努力（B）都片面，C（天助神功）属神秘主义解释。","multi":false},{"no":15,"t":"审美形态的形成和发展，归根到底离不开","o":["社会文化","历史发展","文学艺术","社会实践"],"a":[3],"exp":"审美形态的根源在于人类的社会实践，它是人在实践中与对象建立审美关系的历史产物。社会文化（A）、历史发展（B）、文学艺术（C）都是社会实践的具体表现或结果。","multi":false},{"no":16,"t":"审美形态是对审美对象的","o":["形象描述和感性认识","逻辑归类和理性描述","具体描述和抽象认识","概括描述和复杂认识"],"a":[1],"exp":"审美形态是对审美对象的逻辑归类和理性描述，如将美分为优美、崇高、悲剧、喜剧等范畴。A（形象描述、感性认识）停留在体验层面，C和D表述不准确。","multi":false},{"no":17,"t":"“小桥流水”使人产生","o":["现实感","优美感","崇高感","壮美感"],"a":[1],"exp":"“小桥流水”具有小巧、柔和、和谐、宁静的特征，符合“优美”的审美形态，使人产生优美感。崇高感和壮美感需要巨大、力量等特征，现实感不属于审美形态。","multi":false},{"no":18,"t":"悲剧的审美特征在于","o":["通过英雄的毁灭激发悲观的情绪","通过恶人的毁灭激发恐惧的情绪","通过肯定性体验展现否定性价值","通过否定性体验展现肯定性价值"],"a":[3],"exp":"悲剧通过对有价值事物的毁灭（否定性体验），最终肯定人的尊严、抗争精神和理想力量（肯定性价值）。A错在“激发悲观”，B错在“恶人的毁灭”，C颠倒了肯定与否定的关系。","multi":false},{"no":19,"t":"认为美学研究的对象是艺术的德国美学家是","o":["鲍姆加登","黑格尔","费希纳","康德"],"a":[1],"exp":"黑格尔明确将美学定义为“艺术哲学”，认为美学研究的对象是艺术。鲍姆加登（A）将美学定义为“感性认识的科学”，费希纳（C）是实验美学代表，康德（D）研究审美判断力。","multi":false},{"no":20,"t":"美学历史发展的第一阶段是","o":["审美经验","审美意识","审美现象","美学思想"],"a":[1],"exp":"美学发展的历史第一阶段是审美意识（人类最早的审美观念和感受），然后发展为美学思想，最后形成独立的美学学科。审美经验（A）是具体体验，审美现象（C）是研究对象，美学思想（D）是第二阶段。","multi":false},{"no":21,"t":"审美经验的构成要素主要有","o":["感知","情感","想象","理解","记忆"],"a":[0,1,2,3],"exp":"审美经验的基本构成要素是感知、情感、想象、理解，四者缺一不可。记忆（E）是想象的基础材料，但不作为独立的构成要素。","multi":true},{"no":22,"t":"下列学说中，从艺术本质角度界定艺术的有","o":["模仿说","表现说","有意味的形式说","符号说","载道说"],"a":[0,1,2,3],"exp":"模仿说（艺术是对现实的模仿）、表现说（艺术是情感的表现）、有意味的形式说（艺术是形式的意味）、符号说（艺术是情感的符号）都是从艺术本质角度界定艺术。载道说（E）是从艺术功能角度（教化）界定，而非本质角度。","multi":true},{"no":23,"t":"19世纪中叶以后，随着西方现代艺术的兴起而生成的审美形态是","o":["丑","荒诞","优美","崇高","悲剧"],"a":[0,1],"exp":"丑和荒诞是19世纪中叶以后随着现代艺术兴起而生成的审美形态。优美（C）、崇高（D）、悲剧（E）都是自古已有的审美形态，并非现代艺术兴起后才生成。","multi":true},{"no":24,"t":"对于鉴赏过程中“悟”的正确描述有","o":["接受者的初步感受和意象重建","主体的意象终于升华为意境的感悟","主体意识升华为高度自由的境界","艺术接受的最高阶段和理想境界","主体克服了艺术品符号与意义之间的矛盾"],"a":[1,2,3,4],"exp":"“悟”是艺术鉴赏的最高阶段（D），主体意象升华为意境（B），意识进入高度自由境界（C），并克服符号与意义的矛盾（E）。A（初步感受）属于“观”的阶段，而非“悟”，故不选。","multi":true},{"no":25,"t":"审美是一种","o":["理性活动","人生实践","认识活动","高级的人生境界","精神享受"],"a":[1,3,4],"exp":"审美是人生实践（B）的重要组成部分，是高级的人生境界（D），也是一种精神享受（E）。审美不是纯粹的理性活动（A）或认识活动（C），它融合感性与理性、情感与理解。","multi":true}],"essay":[{"no":26,"t":"审美态度","ans":"指主体在摆脱了日常的功利和实用态度之后，所产生的一种观照、欣赏的态度。","exp":"审美态度是审美活动发生的主观前提，要求主体悬置功利计较，以非实用的、愉悦的心态面对对象，专注于对象的形式和意蕴。","type":"名词解释"},{"no":27,"t":"荒诞","ans":"（1）荒诞的本义是指不合情理与不和谐；它的形式是怪诞、变形，它的内容是荒谬不真。（2）荒诞是对人生无意义的虚无性的审美感悟。","exp":"荒诞是20世纪现代主义艺术中形成的审美形态，它表现世界的非理性和人的异化，以变形、夸张的手法传达存在主义式的虚无体验。","type":"名词解释"},{"no":28,"t":"席勒的美育观","ans":"（1）席勒在《审美教育书简》中第一次提出了系统的美育理论。（2）认为美育是实现人的自由的唯一途径。（3）认为美育可以恢复人的感性与理性的统一，造就完整性，使人进入自由王国。","exp":"席勒将美育视为克服现代人性分裂、实现完整人格的唯一途径，通过审美教育调和感性冲动与理性冲动，使人达到真正的自由。","type":"名词解释"},{"no":29,"t":"审美惊异","ans":"（1）审美惊异主要表现为一种内在的精神召唤，与生活之间依然保持一种内在的深刻联系。（2）它是一种鲜活的生命感。（3）既依赖于主体自身条件，也依赖于对象的客观条件。","exp":"审美惊异是审美活动的起点，是主体被对象独特魅力所吸引而产生的惊奇、赞叹之情，它源于日常生活却又超越日常生活，带有强烈的新鲜感和生命活力。","type":"名词解释"},{"no":30,"t":"简析审美感知的基本特征。","ans":"（1）审美感知总是与情感活动紧紧地交织在一起。（2）审美感知具有积极的选择能力。（3）审美感知总是以完形的方式来把握对象的，因而具有整体性的特点。","exp":"审美感知不同于日常感知，它受情感驱动，主动选择对象的审美属性，并以整体性的方式把握对象形式，而非被动地接受零散信息。","type":"简答"},{"no":31,"t":"简述意境与意象的差别。","ans":"（1）意象主要关系到审美的广度，意境则主要关系到深度。（2）意境是意象的升华。（3）意象属于艺术范畴，意境的意义则更加宽泛。","exp":"意象是个别的审美形象，意境是意象群整体营造的深层境界。意象偏重感受的丰富性（广度），意境偏重意蕴的深远性（深度），且意境不仅限于艺术领域，也适用于自然和人生。","type":"简答"},{"no":32,"t":"简述美育的目的。","ans":"（1）作为一种教育方式，是人类全面教育的有机组成部分，是人类实现自我发展的重要途径。（2）一方面使人的审美感受能力和创造力得到培养和训练，另一方面使人的精神能够获得解放与自由，使个性获得全面而充分的发展。（3）最高目的在于成就审美的人生。","exp":"美育的目的不仅是培养审美技能，更在于通过情感陶冶和人格塑造，使人达到感性与理性和谐统一，最终实现自由、完满、诗意的人生境界。","type":"简答"},{"no":33,"t":"简述作为审美形态的喜剧的特征。","ans":"（1）包含着深刻的社会现实内容，以与现实错乱的形式表达出来。（2）具有不和谐、悖谬的形式特征。（3）其情感形式表现以笑为主。","exp":"喜剧通过夸张、讽刺、幽默等方式揭示现实中的矛盾，其笑既有批判性（讽刺），也有肯定性（幽默），在笑声中让人认识丑与荒诞，产生审美愉悦。","type":"简答"},{"no":34,"t":"简述审美关系的特征。","ans":"（1）审美关系不是理智认识关系，而是情感体验关系。（2）审美关系是通过感性形式建立起来的，是一种感性直观的关系。（3）审美关系是人与世界之间的自由关系。（4）审美关系在逻辑上先于审美主、客体而存在。","exp":"审美关系以情感体验为核心，通过感性直观实现人与世界的自由统一，它不同于认知和功利关系。审美主客体是在审美关系中生成和确立的，因此关系在逻辑上先于二者。","type":"简答"},{"no":35,"t":"试举例阐述审美意象的物态化和物化过程。","ans":"（1）意象的生产意味着意象得到物态化和物化的表达。艺术意象获得形式符号转化为物质实体。（2）物态化和物化是将意象深层潜意识的意义明晰化。（3）意象的物态化与物化也是一种生产，通过技巧与操作来完成。（4）艺术产品的价值首先取决于凝定在其中的意象；同时艺术品作为物态化的存在，为人类审美经验的交流和传播提供可能。","exp":"物态化是将内在心理意象转化为可感的物化形态（如用颜料、石材、声音等物质材料呈现）。例如，罗丹创作《思想者》，先将内心对沉思者的意象通过泥塑（物态化），再铸造成青铜雕像（物化）。这一过程不仅使意象得以固定和传播，也通过技巧操作深化了意象的表达。经过物态化与物化，意象从私人的心理存在转变为公共的艺术品，从而实现审美价值的交流和延续。","type":"论述"},{"no":36,"t":"结合实例说明审美活动是最具个性化的精神活动。","ans":"（1）审美所建构的是一个具有独特人生意味的诗意世界。（2）在审美活动中主体以物我两忘、天人合一为其突出特点。（3）审美活动把感性、个别性作为自己最基本的存在方式，不仅是具体的独特的，而且是一次性不可重复的。（4）审美的体验过程既是瞬间的，也可以是终身的体验，审美活动的具体内容永远随人生而不断变迁、深化和丰富。","exp":"同一审美对象在不同欣赏者心中产生不同的感受，如欣赏《红楼梦》，有人看到爱情悲剧，有人看到家族兴衰，有人看到人生哲理，这正是审美个性化的体现。再如，同一个人在不同年龄阶段重读《红楼梦》，体验也各不相同。审美活动始终以个体的感性经验和独特感悟为存在方式，每一次审美都是独一无二的、不可重复的精神事件。","type":"论述"}]},{"id":"1910","year":2019,"month":10,"label":"2019年10月","choice":[{"no":1,"t":"美学作为一门学科确立的时间是","o":["1850年","1750年","1650年","1550年"],"a":[1],"exp":"美学作为一门独立学科确立于1750年，德国哲学家鲍姆加登出版《美学》一书，首次使用“美学”（Aesthetica）这一术语，他也因此被称为“美学之父”。","multi":false},{"no":2,"t":"维特根斯坦认为，“与美学相联系的、最重要的可能是所谓的审美反应”，这实际上是强调美学研究的重点是","o":["审美经验","审美关系","审美形态","审美现象"],"a":[0],"exp":"维特根斯坦强调“审美反应”，即主体对审美对象的感受和体验，这指向审美经验。审美关系（B）是主客体之间的关联，审美形态（C）是美的类型划分，审美现象（D）过于宽泛。","multi":false},{"no":3,"t":"对审美趣味产生制约作用的主要因素是","o":["审美需要","审美理想","审美情感","审美经验"],"a":[1],"exp":"审美理想是主体关于完善的美的观念，它处于审美心理结构的最高层，对审美趣味起着导向和制约作用。审美需要（A）是动力，审美情感（C）是体验，审美经验（D）是积累。","multi":false},{"no":4,"t":"“兰亭也，不遭右军，则清湍修竹，芜没于空山矣。”这说明","o":["美是先于人而客观存在的","美具有不依赖于人的独立性","美是因为人才显现出来的","美存在于人的观念之中"],"a":[2],"exp":"这句话意为兰亭若不遇到王羲之（右军），其美景也会被埋没。说明美需要通过人的审美活动才能显现，美不是纯客观存在，而是在审美关系中生成的。D（存在于观念中）是主观唯心主义，与题意不符。","multi":false},{"no":5,"t":"杜夫海纳认为，审美对象是","o":["完善的感性","灿烂的感性","自然的感性","直观的感性"],"a":[1],"exp":"杜夫海纳在《审美经验现象学》中提出，审美对象是“灿烂的感性”，即感性在审美活动中达到最充分、最辉煌的呈现。完善的感性（A）、自然的感性（C）、直观的感性（D）均非杜夫海纳的表述。","multi":false},{"no":6,"t":"“劳动说”主张审美起源于人类的","o":["物质生产","石器生产","陶器生产","精神生产"],"a":[0],"exp":"“劳动说”认为审美起源于人类的物质生产劳动，劳动创造了人本身，也培养了人的审美感知能力。石器生产（B）、陶器生产（C）是物质生产的具体形式，精神生产（D）是劳动基础上发展起来的。","multi":false},{"no":7,"t":"下列诗句体现出“崇高”特点的是","o":["细雨鱼儿出，微风燕子斜","寒波澹澹起，白鸟悠悠下","行到水穷处，坐看云起时","落日照大旗，马鸣风萧萧"],"a":[3],"exp":"杜甫诗句“落日照大旗，马鸣风萧萧”描绘了雄浑苍茫的边塞景象，具有巨大、力量、气势等崇高特征。A、B、C均表现优美、宁静、和谐的画面。","multi":false},{"no":8,"t":"认为最美的图形是球形和圆形的是","o":["毕达哥拉斯学派","柏拉图学派","亚里士多德学派","智者学派"],"a":[0],"exp":"毕达哥拉斯学派认为数是万物的本原，球形和圆形因其几何上的完美对称而被视为最美的图形。柏拉图学派（B）关注理念，亚里士多德学派（C）关注实体，智者学派（D）关注修辞与辩论。","multi":false},{"no":9,"t":"恩格斯认为悲剧冲突的实质是","o":["好人遭受了不该遭受的厄运","怜悯与恐惧","永恒正义的冲突","历史的必然要求与这个要求实际上不可能实现之间的冲突"],"a":[3],"exp":"恩格斯在致拉萨尔的信中提出，悲剧冲突的实质是“历史的必然要求与这个要求的实际上不可能实现之间的冲突”。A是亚里士多德对悲剧主人公的描述，B是悲剧效果，C是黑格尔的观点。","multi":false},{"no":10,"t":"下列说法正确的是","o":["审美形态既是一种感性的形态，又是一种逻辑分类的形式","审美形态的形成与社会文化无关","审美形态首先是一种理性存在形式","审美形态与审美经验无关"],"a":[0],"exp":"审美形态既是感性呈现的形态，又是理性逻辑的分类范畴，具有二重性。B、C、D均错误——审美形态的形成离不开社会文化，它既是感性存在也与审美经验密切相关。","multi":false},{"no":11,"t":"“如清风，如云，如霞，如烟，如幽林曲涧”所描述的审美形态是","o":["自然美","社会美","优美","崇高"],"a":[2],"exp":"这段描述以轻柔、飘逸、幽静的形象为主，符合“优美”的特征——小巧、柔和、和谐、宁静。自然美（A）是美的类型，社会美（B）是美的领域，崇高（D）强调巨大与力量。","multi":false},{"no":12,"t":"认为“感性认识的不完善就是丑”的美学家是","o":["鲍姆加登","维柯","克罗齐","温克尔曼"],"a":[0],"exp":"鲍姆加登在《美学》中将美定义为“感性认识的完善”，丑则是“感性认识的不完善”。维柯（B）研究诗性智慧，克罗齐（C）主张直觉即表现，温克尔曼（D）研究古希腊艺术。","multi":false},{"no":13,"t":"柏拉图描述审美经验的高峰状态的学说是","o":["迷狂说","模仿说","分有说","洞穴说"],"a":[0],"exp":"柏拉图在《斐德若篇》中提出“迷狂说”，描述诗人在灵感状态下进入忘我的高峰体验。模仿说（B）是艺术本质论，分有说（C）是理念论，洞穴说（D）是认识论比喻。","multi":false},{"no":14,"t":"中国古代的“比德说”总是把自然","o":["艺术化","科学化","理论化","人格化"],"a":[3],"exp":"“比德说”将自然物的形态特征与人的道德品格相比附，如孔子“智者乐水，仁者乐山”，即把自然人格化。艺术化（A）、科学化（B）、理论化（C）均非“比德说”的特征。","multi":false},{"no":15,"t":"关于审美经验，表述正确的是","o":["纯粹的感性直观活动","纯粹的理性直观活动","抽象的理性思维活动","感性直观和本质直观的统一"],"a":[3],"exp":"审美经验既包含对感性形象的直观（感知），也包含对深层意蕴的把握（本质直观），二者统一于审美体验中。A、B、C都片面地强调了某一方面。","multi":false},{"no":16,"t":"审美主体在头脑中重新形成事物形象的心理功能是","o":["接近联想","类似联想","再造性想象","创造性想象"],"a":[2],"exp":"再造性想象是根据语言描述或图示在头脑中重新形成事物形象的心理功能。创造性想象（D）是创造全新形象。接近联想（A）和类似联想（B）属于联想而非想象。","multi":false},{"no":17,"t":"鲁迅说：“我以为感情正烈的时候，不宜作诗，否则锋芒太露，能将诗美‘杀掉’。”这段话说明，在审美经验中","o":["想象应受情感的制约","理智应受情感的制约","情感应受想象的制约","情感应受理智的制约"],"a":[3],"exp":"鲁迅指出感情过于强烈会破坏诗美，意味着审美创造需要理智对情感进行节制和调控，使情感表达适度含蓄。A、B、C均不符合鲁迅原意。","multi":false},{"no":18,"t":"“艺”在《说文解字》中被解释为","o":["文字","种植","艺术","舞蹈"],"a":[1],"exp":"《说文解字》释“艺”为“种也”，即种植之意，反映了“艺”的本义与农业劳作相关。文字（A）、艺术（C）、舞蹈（D）均为后起的引申义。","multi":false},{"no":19,"t":"意象的基本结构是","o":["知与意","意与象","情与意","当与象"],"a":[1],"exp":"意象由“意”（主体的情感、意念）和“象”（可感的形象）两个基本要素构成，二者融合统一。知与意（A）、情与意（C）均不全面，D无此术语。","multi":false},{"no":20,"t":"克罗齐主张","o":["艺术是情感符号","艺术是巫术仪式","艺术是理念","艺术是直觉"],"a":[3],"exp":"克罗齐在《美学原理》中提出“艺术即直觉”，认为艺术是主观情感的直觉表现。A是苏珊·朗格的观点，B是弗雷泽的观点，C是黑格尔的观点。","multi":false},{"no":21,"t":"克莱夫·贝尔认为，艺术是有意味的","o":["形式","内容","质料","结构"],"a":[0],"exp":"克莱夫·贝尔在《艺术》中提出“艺术是有意味的形式”，认为艺术的本质在于能引发审美情感的形式组合。内容（B）、质料（C）、结构（D）均不属其核心观点。","multi":false},{"no":22,"t":"陆机在《文赋》中说，“若夫应感之会，通塞之纪，来不可遏，去不可止，藏若景灭，行犹响起”，这是指艺术创作中的","o":["表达","灵感","动机","叙事"],"a":[1],"exp":"陆机这段话描述的是灵感来去无踪、不可预测的特征，灵感是艺术创作中突发的高峰创造状态。表达（A）、动机（C）、叙事（D）均非此句所指。","multi":false},{"no":23,"t":"认为艺术是“对理念的模仿的模仿”的古希腊美学家是","o":["毕达哥拉斯","芝诺","柏拉图","恩培多克勒"],"a":[2],"exp":"柏拉图认为艺术是模仿现实，而现实又是对理念的模仿，因此艺术是“模仿的模仿”，与真理隔了三层。毕达哥拉斯（A）、芝诺（B）、恩培多克勒（D）均无此观点。","multi":false},{"no":24,"t":"强调“天才”的艺术观是","o":["表现说","形式说","模仿说","游戏说"],"a":[0],"exp":"表现说（尤其是浪漫主义）强调艺术是天才的创造，天才凭借直觉和灵感表达独特情感。形式说（B）关注形式，模仿说（C）关注再现，游戏说（D）关注自由活动。","multi":false},{"no":25,"t":"艺术品赖以存在的媒介属于艺术品的","o":["物质实在层","形式符号层","意象世界层","意境超验层"],"a":[0],"exp":"艺术品赖以存在的物质材料（如画布、颜料、声音）属于物质实在层，它是艺术品最基础的层次。形式符号层（B）是色彩的排列组合，意象世界层（C）是审美形象，意境超验层（D）是深层意蕴。","multi":false},{"no":26,"t":"主张美育是一种趣味教育的中国近代美学家是","o":["王国维","鲁迅","梁启超","蔡元培"],"a":[2],"exp":"梁启超主张美育是“趣味教育”，强调通过审美培养人的生命情趣。王国维（A）将美育与德智体并称四育，蔡元培（D）主张“以美育代宗教”，鲁迅（B）也论述美育但非“趣味教育”的提出者。","multi":false},{"no":27,"t":"下列著作中属于西方美育理论经典的是","o":["《拉奥孔》","《论教育之宗旨》","《审美教育书简》","《谈美书简》"],"a":[2],"exp":"席勒的《审美教育书简》是西方美育理论的经典著作。A（莱辛）是艺术论，B（王国维）是中国美育文献，D（朱光潜）是中国现代美育著作。","multi":false},{"no":28,"t":"把美育等同于艺术教育，错误在于","o":["夸大了艺术在审美教育中的作用","肯定了艺术在审美教育中的作用","把美与善混为一谈","把美育混同于人格教育"],"a":[0],"exp":"美育不仅包括艺术教育，还涵盖自然美、社会美等领域的审美教育。将美育等同于艺术教育，是夸大了艺术在美育中的作用，忽略了美育更广阔的内涵。B是正确认识，C和D是其他误区。","multi":false},{"no":29,"t":"美育主要是一种“化育”，即","o":["说教感化","强制灌输","潜移默化","消遣娱乐"],"a":[2],"exp":"美育的主要特点是“潜移默化”，它通过情感熏陶在不知不觉中影响人，而非说教（A）、强制（B）或单纯的娱乐（D）。","multi":false},{"no":30,"t":"荀子认为人性和文化的生成是通过","o":["怡情养性","化性起伪","消融渣滓","美育群材"],"a":[1],"exp":"荀子提出“化性起伪”，认为通过礼乐教化可以改造人的自然本性，生成文化和人性。A（怡情养性）是美育效果，C（消融渣滓）是朱熹的观点，D（美育群材）是其他提法。","multi":false},{"no":31,"t":"构成审美对象的物质因素主要有","o":["色彩","线条","形体","音响","比例"],"a":[0,1,2,3],"exp":"构成审美对象的物质因素包括色彩、线条、形体、音响等。比例（E）属于形式关系而非物质因素本身，故不选。","multi":true},{"no":32,"t":"下列美学家中，属于自然主义的有","o":["桑塔亚那","托马斯·门罗","柏格森","克罗齐","叔本华"],"a":[0,1],"exp":"桑塔亚那和托马斯·门罗是自然主义美学的代表，主张用科学和自然主义方法研究审美。柏格森（C）是直觉主义，克罗齐（D）是表现主义，叔本华（E）是唯意志论，均不属于自然主义。","multi":true},{"no":33,"t":"下列关于艺术想象力的说法正确的有","o":["能够唤醒和引发丰富的形象","能够融合与整合形象","不同于日常的逻辑思维能力","主要靠概念来判断","是一种理性推理能力"],"a":[0,1,2],"exp":"艺术想象力能唤醒、融合形象（A、B），不同于日常逻辑思维（C）。D（靠概念判断）和E（理性推理）属于科学认知，不是艺术想象力的特征，故不选。","multi":true},{"no":34,"t":"正确理解美育的内涵，要遵循的原则有","o":["共时性与历时性相统一的原则","手段与效果相一致的原则","直接效果与间接效果兼顾的原则","形象性原则","独特性原则"],"a":[1,2,4,1,2,4],"exp":"理解美育内涵需遵循手段与效果一致（B）、直接与间接效果兼顾（C）、独特性（E）等原则。A（共时性与历时性）和D（形象性）不是理解美育内涵的原则性要求。","multi":true},{"no":35,"t":"下列关于柏拉图美育思想的正确表述有","o":["美育可以陶冶心灵","美育应该寓教于乐","艺术的影响有正面的也有负面的","美育应该注重实用","美育可以培养人的品德"],"a":[0,2,4],"exp":"柏拉图认为美育能陶冶心灵（A），艺术影响有正负面（C），能培养品德（E）。B（寓教于乐）是贺拉斯的观点，D（注重实用）与柏拉图美育观不符，故不选。","multi":true}],"essay":[{"no":36,"t":"简述美学成为一门独立学科的标志。","ans":"（1）有专门的、系统的美学著作问世，德国哲学家鲍姆加登1750年出版了《美学》一书，他也被称为“美学之父”。（2）形成了独立的、区别于其他学科的研究对象和范围。","exp":"美学学科的确立以鲍姆加登《美学》出版为主要标志，此后美学从哲学中分化出来，拥有独立的研究领域（审美现象、审美经验、艺术等），成为一门独立的理论学科。","type":"简答"},{"no":37,"t":"简述划分审美形态的基本标准。","ans":"（1）广泛性或普适性，即适用于各种艺术体裁和现实生活中的审美现象；（2）统摄性，即集杂多于统一；（3）历史性，即审美形态应该是民族审美文化的积淀，并且具有长久而持续的影响。","exp":"审美形态的划分需兼顾普遍性（适用范围广）、统摄性（能概括多种现象）和历史性（有文化积淀和持久影响），三者共同保证审美形态作为理论范畴的有效性。","type":"简答"},{"no":38,"t":"简述康德的崇高理论。","ans":"（1）崇高在形式上是无限的和没有秩序的；（2）崇高分为两种类型：“数学”的崇高和“力学”的崇高；（3）崇高首先引起人们生命力阻碍的感觉，接着是更强烈的生命力的爆发。","exp":"康德在《判断力批判》中系统论述崇高，认为崇高来自主体对无限对象的把握失败后理性超越而产生的间接快感，数学崇高（数量无限）和力学崇高（力量巨大）分别对应不同的超越方式。","type":"简答"},{"no":39,"t":"简述艺术品的开放性。","ans":"（1）艺术品是向艺术家开放的，这样，艺术家创造的意象世界才能物态化，物化为艺术品。（2）艺术品也是向接受者开放的，只有通过接受和欣赏，艺术品潜在的审美特征才可能转化为现实的审美价值。","exp":"艺术品不是一个封闭的实体，它在创造过程中向艺术家开放（需要艺术家完成），在接受过程中向欣赏者开放（需要欣赏者实现其价值），其意义在开放性的双向交流中生成。","type":"简答"},{"no":40,"t":"简述艺术的功能。","ans":"（1）艺术具有审美、娱乐消遣、认识、道德教育、宗教感化、思想启迪、政治宣传、心理平衡、社会干预、文化交流、商业广告等多种功能；（2）审美是艺术的核心功能。","exp":"艺术功能多元，但审美功能是最本质、最核心的，其他功能都需通过审美功能来实现，离开审美，艺术便失去其根本特性。","type":"简答"},{"no":41,"t":"简述美育的主要特点。","ans":"（1）诉诸感性。美育通过丰富的形象，以情感为中介，打动人的心灵，提升人的精神境界。（2）潜移默化。美育对于性情的陶冶不是一朝一夕的，而是逐渐沁入人的心灵，使人在不知不觉中受到影响。（3）能动性。美育不是强制性的，而是积极发挥人的能动性。","exp":"美育区别于德育、智育的根本在于“以情动人”“以美育人”，其效果是长期的、内化的，而非立竿见影或强制灌输。","type":"简答"},{"no":42,"t":"试论想象力在审美经验的构成阶段所起的作用。","ans":"（1）先验想象力能够打破主体与客体的浑然一体状态，从而形成审美活动所需要的审美距离。（2）经验想象力能够在先验想象力的基础上，通过改造主体在呈现阶段所获得的原初经验材料，形成关于审美对象的格式塔。","exp":"在审美经验的构成阶段，先验想象力为主体建立与对象之间的适当距离，使对象成为审美对象；经验想象力则对感知材料进行重组和整合，将分散的感性碎片建构为完整、有意义的审美形象。二者共同完成了从感知材料到审美对象的转化，是审美经验从呈现到构成的关键动力。","type":"论述"},{"no":43,"t":"唐代书法家孙过庭在论书法时指出：“若数画并布，其形各异；众点齐列，为体互乖。一点成一字之规，一字乃终篇之准。违而不犯，和而不同；留不常迟，遣不恒疾；带燥方润，将浓遂枯；泯规矩于方圆，遁钩绳之曲直；乍显乍晦，若行若藏；穷变态于毫端，合情调于纸上。”结合这段话，分析审美对象多样统一的形式规律。","ans":"（1）所谓多样，是指审美对象的整体中所包含的各要素在形式上的区别与差异；（2）所谓统一，是指审美对象各部分在整体中彼此关联、呼应、衬托、映照的内在关系；（3）“多样统一”就是寓多于一，在丰富多彩中保持着内在的一致性。","exp":"孙过庭这段书论完美体现了“多样统一”的形式规律。书法中“数画并布，其形各异”“众点齐列，为体互乖”体现了每一笔、每一画的独特性（多样）；但“一点成一字之规，一字乃终篇之准”说明各个局部又在整体中获得统一性（统一）。“违而不犯，和而不同”更是直接道出了多样统一的核心——既有变化（违/不同），又不失协调（不犯/和）。章法中的“乍显乍晦，若行若藏”在变化中保持了整体的节奏与连贯，最终“穷变态于毫端，合情调于纸上”，即在丰富的笔画变化中达成整体的和谐统一。这充分说明，审美对象的美在于将差异性要素有机整合为和谐的整体，即寓多于一，一中有多。","type":"案例"}]},{"id":"2008","year":2020,"month":8,"label":"2020年8月","choice":[{"no":1,"t":"美学学科确立的标志是鲍姆嘉通1750年出版的","o":["《判断力批判》","《审美教育书简》","《诗的哲学默想录》","《美学》"],"a":[3],"exp":"鲍姆嘉通于1750年出版《美学》（Aesthetica）一书，首次使用“美学”这一术语，标志着美学作为一门独立学科的确立。A是康德著作，B是席勒著作，C是鲍姆嘉通研究诗学的早期著作。","multi":false},{"no":2,"t":"下面关于审美意识和美学思想的表述错误的是","o":["美学的发展经历了由审美意识到美学思想再到美学学科的漫长历史过程","审美意识是人类在生存实践中萌发出来的","美学思想奠基于审美意识","审美意识奠基于美学思想"],"a":[3],"exp":"审美意识是美学思想的直接基础，先有审美意识（感性），后有美学思想（理性），最后形成独立的美学学科。D将二者关系颠倒，是错误的。A、B、C均表述正确。","multi":false},{"no":3,"t":"审美趣味的两重性主要是指","o":["先天性与后天性","观念性与实践性","个体性与社会性","现实性与理想性"],"a":[2],"exp":"审美趣味既是个体独特的偏好（个体性），又受社会文化环境影响（社会性），二者构成其两重性。A（先天与后天）、B（观念与实践）、D（现实与理想）均非审美趣味两重性的标准表述。","multi":false},{"no":4,"t":"每一种新媒介的出现都必然带来审美活动的变化，这说明审美活动具有","o":["自律性","他律性","功利性","物质性"],"a":[1],"exp":"媒介（如印刷术、摄影、数字技术）属于外部因素，媒介变化引起审美活动变化，说明审美活动受外部条件制约，具有“他律性”。自律性（A）强调自我规定，功利性（C）和物质性（D）均不准确。","multi":false},{"no":5,"t":"审美体验的深度主要取决于审美主体","o":["卓越的想象能力","饱满的审美情感","丰富的人生体验","高远的审美理想"],"a":[2],"exp":"审美体验的深度与主体的人生阅历、情感积累直接相关，人生体验越丰富，审美体验越深刻。想象能力（A）、审美情感（B）、审美理想（D）虽参与审美体验，但深度主要取决于人生体验的积淀。","multi":false},{"no":6,"t":"“大漠孤烟直，长河落日圆”所体现的形式美因素主要是","o":["色彩","线条","形体","音响"],"a":[1],"exp":"诗句中“直”（直线）和“圆”（圆形）是对线条和形状的描述，主要体现的是线条这一形式美因素。色彩（A）、形体（C）、音响（D）均不为此句的主要表现对象。","multi":false},{"no":7,"t":"杜夫海纳认为，要使审美对象获得现实的生命，审美主体就必须使自己","o":["现实化","非现实化","理想化","审美化"],"a":[1],"exp":"杜夫海纳在《审美经验现象学》中指出，审美主体需要“非现实化”——即脱离日常实用态度，进入想象和情感的世界，才能使审美对象获得生命。现实化（A）相反，理想化（C）和审美化（D）均非杜夫海纳的术语。","multi":false},{"no":8,"t":"博克认为，产生崇高的本能是","o":["维持种族生命延续的本能","维持个体生命的本能","社交的本能","性的本能"],"a":[1],"exp":"博克在《论崇高与优美》中认为，崇高源于自我保全的本能（维持个体生命），面对恐怖对象时产生的惊惧和兴奋；优美源于社交本能。A（种族延续）、C（社交）、D（性本能）均非博克对崇高的解释。","multi":false},{"no":9,"t":"审美形态形成的基础是人类的","o":["道德实践","精神实践","生存实践","宗教实践"],"a":[2],"exp":"审美形态的根源在于人类生存实践（含物质生产和社会生活），在长期实践中形成对美的类型区分。道德实践（A）、精神实践（B）、宗教实践（D）均为生存实践的具体方面，非根本基础。","multi":false},{"no":10,"t":"下列说法正确的是","o":["丑引起的情绪感受不是一种审美情感","丑主要表现为反常、混乱等形式","丑不是人们生存实践的表达形式","丑在美学中没有意义"],"a":[1],"exp":"丑作为审美形态，在形式上表现为反常、混乱、不和谐（B正确）。丑引起的情绪感受仍然是审美情感（A错误），丑是生存实践的否定性表达（C错误），丑在美学中有重要价值（D错误）。","multi":false},{"no":11,"t":"荒诞引起的主要是","o":["虚无感","悲剧感","滑稽感","厌恶感"],"a":[0],"exp":"荒诞表现世界的非理性和无意义，主要引发人的虚无感、荒诞感。悲剧感（B）源于悲剧，滑稽感（C）源于喜剧，厌恶感（D）并非荒诞的典型效果。","multi":false},{"no":12,"t":"在《审美教育书简》中主张“崇高能产生令人惊异的激情”的美学家是","o":["席勒","叔本华","尼采","西美尔"],"a":[0],"exp":"席勒在《审美教育书简》中论述了崇高的作用，认为崇高能激发人的激情和精神提升。叔本华（B）、尼采（C）、西美尔（D）虽论及崇高，但此句出自席勒。","multi":false},{"no":13,"t":"巴赫金的“狂欢化”理论所讨论的审美形态主要是","o":["悲剧","喜剧","荒诞","崇高"],"a":[1],"exp":"巴赫金的“狂欢化”理论源于对拉伯雷的研究，强调民间狂欢文化中的笑、颠覆、平等，主要讨论的是“喜剧”及笑的美学意义。悲剧（A）、荒诞（C）、崇高（D）均非狂欢化的核心。","multi":false},{"no":14,"t":"在西方悲剧理论史上，第一个对悲剧做出完整定义的美学家是","o":["柏拉图","亚里士多德","朗吉弩斯","西塞罗"],"a":[1],"exp":"亚里士多德在《诗学》中首次对悲剧做出完整定义：“悲剧是对一个严肃、完整、有一定长度的行动的模仿……借怜悯与恐惧使这种情感得到净化”。柏拉图（A）否定悲剧，朗吉弩斯（C）论崇高，西塞罗（D）论修辞。","multi":false},{"no":15,"t":"下列美学家中，属于科学主义者的是","o":["托马斯·门罗","叔本华","尼采","伽达默尔"],"a":[0],"exp":"托马斯·门罗是科学主义美学的代表，主张用科学实证方法研究审美。叔本华（B）是唯意志论，尼采（C）是生命哲学，伽达默尔（D）是解释学，均不属于科学主义。","multi":false},{"no":16,"t":"孙悟空等神话形象的产生主要是通过","o":["接近联想","对比联想","再造性想象","创造性想象"],"a":[3],"exp":"孙悟空等神话形象是全新的、非现实的艺术形象，由创造性想象生成，即整合多种素材创造出前所未有形象。接近联想（A）和对比联想（B）是低阶联想，再造性想象（C）是复现已有形象。","multi":false},{"no":17,"t":"“言有尽而意无穷”说明了审美理解具有","o":["直观性","超越性","多义性","超验性"],"a":[2],"exp":"“言有尽而意无穷”指语言有限而意蕴无限，同一作品可以有多重解读，体现了审美理解的多义性。直观性（A）属感知，超越性（B）和超验性（D）虽相关但不直接对应“无穷”的多重解释。","multi":false},{"no":18,"t":"在各种空间艺术中，最具主观性和精神性的是","o":["建筑","绘画","雕塑","戏剧"],"a":[1],"exp":"绘画通过线条、色彩、构图等表达画家的主观情感和精神世界，在空间艺术中最具主观性和精神性。建筑（A）偏重实用与构造，雕塑（C）偏重立体再现，戏剧（D）是综合艺术非纯粹空间艺术。","multi":false},{"no":19,"t":"“观古今于须臾，抚四海于一瞬”主要描述的是","o":["艺术观察能力","艺术理解能力","艺术想象能力","艺术情感能力"],"a":[2],"exp":"此句意为在瞬间观照古今、抚触四海，形容艺术想象突破时空界限的自由能力。观察能力（A）、理解能力（B）、情感能力（D）均不具此超越时空的特性。","multi":false},{"no":20,"t":"黑格尔认为，在各种艺术类型中成就最高的是","o":["象征型艺术","古典型艺术","浪漫型艺术","现代型艺术"],"a":[1],"exp":"黑格尔认为古典型艺术是内容与形式最完美的统一，成就最高。象征型艺术（A）形式压倒内容，浪漫型艺术（C）内容压倒形式，现代型艺术（D）非黑格尔分类。","multi":false},{"no":21,"t":"艺术的教育功能的实现必须借助于","o":["宗教功能","认识功能","道德功能","审美功能"],"a":[3],"exp":"艺术的教育功能必须通过审美功能来实现，即“寓教于乐”，否则就成为道德说教而非艺术。宗教功能（A）、认识功能（B）、道德功能（C）均非教育功能实现的必要中介。","multi":false},{"no":22,"t":"艺术存在于","o":["从艺术创造到艺术品到艺术接受的动态流程中","作者的创作活动中","艺术作品中","读者的接受活动中"],"a":[0],"exp":"艺术不是静态的实体，而是存在于创造→作品→接受的完整动态流程中。B、C、D都只是艺术存在的一个环节，不完整。","multi":false},{"no":23,"t":"下列说法错误的是","o":["接受者对艺术品的接受不是一蹴而就的","接受者对艺术品的接受没有终点","接受者对艺术品的接受会随着“期待视野”的变化而变化","接受者对艺术品的接受可以分为观、思、评三个阶段"],"a":[3],"exp":"艺术接受的过程通常分为“观、品、悟”三个阶段，而非“观、思、评”。“思”和“评”偏重理性分析，不符合审美体验的特征。A、B、C表述均正确。","multi":false},{"no":24,"t":"艺术意象的特征主要是","o":["现实性、社会性、感性和联想性","现实性、情感性、联想性和想象性","虚拟性、直观性、想象性和情感性","虚拟性、现实性、想象性和情感性"],"a":[2],"exp":"艺术意象的基本特征是虚拟性（非现实存在）、直观性（可感知）、想象性（由想象生成）、情感性（寄托情感）。现实性（A、B、D）不是意象的特征，意象是虚拟的。","multi":false},{"no":25,"t":"荣格的艺术观不同于弗洛依德，他认为艺术起源于","o":["集体无意识","个人无意识","性本能","艺术表现"],"a":[0],"exp":"荣格认为艺术起源于集体无意识和原型，而非弗洛伊德强调的个人无意识和性本能。B是弗洛伊德的关注点，C是弗洛伊德的核心，D过于笼统。","multi":false},{"no":26,"t":"梁启超把小说的感化作用概括为","o":["熏、观、感、讽","熏、浸、教、乐","熏、浸、刺、提","兴、观、群、怨"],"a":[2],"exp":"梁启超在《论小说与群治之关系》中将小说的感化作用概括为“熏、浸、刺、提”四种力。A、B均不符合，D（兴观群怨）是孔子论诗的功能。","multi":false},{"no":27,"t":"《淮南子》中说，“动诸琴瑟，形诸音声，而能使人为之哀乐”。这段话体现出的美育的特点是","o":["诉诸感性","潜移默化","能动性","无目的性"],"a":[0],"exp":"此句意为音乐能直接感动人的情感，使人产生哀乐之情，体现了美育“诉诸感性”的特点——通过感官直接打动人。潜移默化（B）是效果，能动性（C）是接受者的主动性，无目的性（D）不准确。","multi":false},{"no":28,"t":"美育与德育的关系是","o":["美育就是德育","美育与德育无关","美育与德育相互区别、相辅相成","美育与德育相互冲突、无法调和"],"a":[2],"exp":"美育以情感陶冶为主，德育以道德规范为主，二者不同（相互区别）；但美育有助于德育的内化，德育为美育提供价值导向，相辅相成。A、B、D均错误。","multi":false},{"no":29,"t":"提出“净化说”的古希腊美学家是","o":["柏拉图","苏格拉底","德谟克利特","亚里士多德"],"a":[3],"exp":"亚里士多德在《诗学》中提出悲剧“净化”说。柏拉图（A）否定诗和悲剧，苏格拉底（B）无系统美学理论，德谟克利特（C）论原子和影像。","multi":false},{"no":30,"t":"美育的特征是","o":["以刺激的方式娱乐人","以感性的方式陶冶人","以理性的方式教育人","以道德的方式感化人"],"a":[1],"exp":"美育的根本特征是以感性形象为媒介、以情感为中介陶冶人的心灵。A（刺激娱乐）是低层次的，C（理性教育）是智育，D（道德感化）是德育。","multi":false},{"no":31,"t":"史前时期就已出现的原始艺术形式有","o":["雕刻","绘画","音乐","舞蹈","戏剧"],"a":[0,1,2,3],"exp":"史前时期已有雕刻（如维纳斯像）、绘画（洞穴壁画）、音乐（骨笛）、舞蹈（岩画中的舞蹈形象）。戏剧（E）是后来发展起来的综合艺术形式，史前时期尚未出现。","multi":true},{"no":32,"t":"用来描述优美的词主要有","o":["轻盈","淡雅","精致","娇小","纤巧"],"a":[0,1,2,3,4],"exp":"优美以小巧、柔和、和谐、精致为特征，轻盈、淡雅、精致、娇小、纤巧都适用于描述优美。五个选项均正确。","multi":true},{"no":33,"t":"下列有关审美想象和审美情感的表述正确的有","o":["审美情感是审美想象的原动力","审美想象是审美情感的原动力","审美情感是审美想象的对象","审美想象是审美情感的对象","审美想象是一种理性推理能力"],"a":[0,2],"exp":"审美情感是推动想象展开的原动力（A正确），同时想象所创造的形象也是情感寄托的对象（C正确）。B颠倒了关系，D不成立，E错误——审美想象不是理性推理。","multi":true},{"no":34,"t":"在中国先秦时期的美育思想中，美育的途径主要包括","o":["诗教","乐教","家教","言教","身教"],"a":[0,1],"exp":"先秦美育的主要途径是“诗教”（以诗感发）和“乐教”（以乐陶冶），如孔子“兴于诗，立于礼，成于乐”。家教（C）、言教（D）、身教（E）是教育的一般方式，并非先秦美育思想中的特定途径。","multi":true},{"no":35,"t":"对于“美育是人格教育”这种观点，下列评价正确的有","o":["把美和善混为一谈","使美育沦为德育","取消了美育的独立性","忽视了美育对完善人格的作用","对美育内涵做出了科学的理解"],"a":[0,1,2],"exp":"“美育是人格教育”将美育等同于人格培养，混淆了美与善（A），使美育从属于德育（B），取消了美育的独立地位（C）。D与此观点相反——它恰恰强调了人格作用，E不正确，因为这一理解不科学、不全面。","multi":true}],"essay":[{"no":36,"t":"简述美学史上关于美学研究对象的主要观点。","ans":"（1）美学的研究对象是美和美的规律；（2）美学的研究对象是艺术；（3）美学的研究对象是审美经验和审美心理；（4）美学的研究对象是人和现实之间的审美关系。（答出任意三点即可）","exp":"美学史上对研究对象的认识经历了从“美”到“艺术”再到“审美经验”“审美关系”的演变，不同学派各有侧重，反映了美学学科的深化和发展。","type":"简答"},{"no":37,"t":"简述审美理想在审美活动中的作用。","ans":"（1）审美理想在一定程度上决定着主体对于对象的选择，以及所做出的审美判断；（2）审美理想作为一种人生修养，能够使审美活动成为主体人生实践的重要组成部分。","exp":"审美理想是主体关于美的最高标准，它引导主体选择什么对象、如何评价对象，同时审美理想本身也是人格修养的体现，使审美活动成为人生实践的内在环节。","type":"简答"},{"no":38,"t":"简述普列汉诺夫关于劳动与审美之间关系的基本看法。","ans":"（1）劳动先于审美；（2）只有通过劳动才能使审美需求从潜在性转化为现实性；（3）人的审美能力是在生产劳动中形成的，并与生产力发展的一定水平相一致。","exp":"普列汉诺夫在《没有地址的信》中系统论证了艺术起源于劳动。劳动创造了艺术表现的对象和工具，培养了人的节奏感、形式感等审美能力，审美意识随生产力发展而发展。","type":"简答"},{"no":39,"t":"简述审美经验与美感之间的差异。","ans":"（1）美感仅仅是指主体对于对象的主观感受，审美经验则是指人在审美活动中与对象所形成的审美关系；（2）美感是指主体在瞬间的感受和体验，审美经验则是指审美对象被构成并得到感受和评价的动态过程；（3）美感是指主体对于某种现成对象所做出的反应，因而实际上假定审美对象在审美活动开始之前就存在了，审美经验理论则主张审美对象是在具体的审美活动过程中才被建构起来的。","exp":"审美经验理论比“美感”概念更深入，它强调审美对象与审美主体的相互生成关系，是一个动态的、建构性的过程，而非主体的被动反应。","type":"简答"},{"no":40,"t":"简述美学史上关于审美情感的几种主要观点。","ans":"（1）客观论认为，审美对象的情感性质是其本身所固有的，与主体的主观态度无关；（2）主观论认为，审美情感是由主体投射或灌注到对象之中去的；（3）同构论认为，审美情感源于主客体之间的同构对应关系。","exp":"客观论（如柏拉图、黑格尔）强调美的客观性，主观论（如移情说）强调主体的投射，同构论（如格式塔心理学）强调主客体在结构上的相似性，三者从不同角度解释审美情感的来源。","type":"简答"},{"no":41,"t":"简述美育的功能。","ans":"（1）怡情养性。美育是通过审美对人的精神进行调节，以情动人，从而达到心理的平衡、人格的完善；（2）化性起伪。美育能够改造人性之“伪”，是一种完善本性、升华人格的方式。","exp":"美育通过情感陶冶实现怡情养性，使人心灵和谐；通过文化教化实现化性起伪，使自然本性提升为人性，二者共同构成美育的人格塑造功能。","type":"简答"},{"no":42,"t":"试论作为审美形态的悲剧与作为戏剧艺术的悲剧之间的差异与联系。","ans":"（1）差异：作为审美形态的悲剧比作为戏剧艺术的悲剧范围更广，还包括了广泛的社会历史现象；（2）联系：作为戏剧艺术的悲剧是作为审美形态的悲剧的典型形态。","exp":"审美形态的悲剧是对人生中具有冲突、抗争与毁灭特征的现象的哲学概括，它不仅存在于戏剧中，也存在于小说、诗歌、绘画乃至现实人生中。而戏剧艺术的悲剧是这种审美形态在戏剧体裁中的具体呈现，是最集中、最典型的悲剧表现方式。二者是普遍与特殊、本质与现象的关系：审美形态的悲剧为戏剧悲剧提供理论基础，戏剧悲剧是审美形态的悲剧的艺术实践和经典载体。","type":"论述"},{"no":43,"t":"鲁迅在谈到《红楼梦》时说道：“单是命意，就因读者的眼光而有种种：经学家看见《易》，道学家看见淫，才子看见缠绵，革命家看见排满，流言家看见宫闱秘事……”试结合这段话，谈谈艺术接受的主体性。","ans":"（1）接受主体必须调动自身的主体性因素，对创造者提供的文本和形式符号进行加工，才能完成艺术意象的再创造；（2）接受主体必须从自身的“期待视野”出发，对文本进行选择和取舍；（3）艺术品的形式是一种“图式化”结构，接受者必须在作品提供的框架中填补空白、揭示意义。","exp":"鲁迅这段话生动说明，同一部《红楼梦》在不同读者眼中呈现出完全不同意义，原因在于每个接受者都带着自己的知识背景、价值观念和审美偏好（即“期待视野”）进入阅读。经学家关注周易思想，道学家关注道德训诫，才子关注爱情，革命家关注政治，流言家关注秘闻——这充分证明艺术接受不是被动复制，而是主动再创造。接受者根据自身主体性因素对文本进行选择、解读和填补，使作品的意义在每一次接受中得以重新生成，这正是艺术接受主体性的核心体现。","type":"案例"}]},{"id":"2010","year":2020,"month":10,"label":"2020年10月","choice":[{"no":1,"t":"最早提出美的本质问题的美学家是","o":["黑格尔","马克思","柏拉图","鲍姆加登"],"a":[2],"exp":"柏拉图在《大希庇阿斯篇》中首次系统探讨“美本身是什么”，是西方美学史上最早提出美的本质问题的美学家。黑格尔（A）、马克思（B）和鲍姆加登（D）均晚于柏拉图。","multi":false},{"no":2,"t":"马克思实践概念的核心内涵是","o":["人的最基本的存在方式","人的最基本的精神生产方式","人的审美存在","人的历史存在"],"a":[0],"exp":"马克思认为实践是人的最基本的存在方式，是人类感性的、对象性的物质活动，是全部社会生活和历史的基础。B（精神生产）是实践的派生形式，C和D均不全面。","multi":false},{"no":3,"t":"审美理想是一种相对稳定的","o":["情感结构","价值取向","生存状态","道德修养"],"a":[1],"exp":"审美理想是主体关于完善的美的观念，是一种相对稳定的价值取向，主导着主体的审美判断和追求。情感结构（A）是心理构成，生存状态（C）是存在方式，道德修养（D）属德育范畴。","multi":false},{"no":4,"t":"影响主体审美趣味的主要因素是","o":["生理遗传","先天气质","家庭背景","社会条件"],"a":[3],"exp":"审美趣味虽然有个体差异，但主要受后天社会条件（文化传统、教育背景、时代风尚等）影响。生理遗传（A）和先天气质（B）不是主要因素，家庭背景（C）是社会条件的一部分，不够全面。","multi":false},{"no":5,"t":"“和而不同”、“违而不犯”所描述的形式规律是","o":["整齐一律","节奏韵律","对称均衡","多样统一"],"a":[3],"exp":"“和而不同”指在统一中有变化，“违而不犯”指在变化中有协调，二者共同体现了“多样统一”的形式规律。整齐一律（A）强调一致，节奏韵律（B）强调重复与变化，对称均衡（C）强调平衡。","multi":false},{"no":6,"t":"在20世纪我国美学研究领域占据优势地位的审美发生理论是","o":["游戏说","生物本能说","巫术说","劳动说"],"a":[3],"exp":"20世纪中国美学在马克思主义指导下，占据主导地位的是普列汉诺夫的“劳动说”，认为审美起源于人类的生产劳动实践。游戏说（A）、生物本能说（B）、巫术说（C）均非中国美学界的主导理论。","multi":false},{"no":7,"t":"下列说法正确的是","o":["优美是阳刚的人生境界","优美使人感到紧张","优美是和谐的人生境界","优美使人感到振奋"],"a":[2],"exp":"优美以和谐、宁静、柔顺为特征，体现了和谐的人生境界。A将优美与阳刚混淆（阳刚属崇高），B（紧张）和D（振奋）属崇高和悲剧的特征。","multi":false},{"no":8,"t":"《判断力批判》的作者是","o":["笛卡尔","歌德","莱辛","康德"],"a":[3],"exp":"《判断力批判》是康德的三大批判之一，系统论述了审美判断力和目的论判断力。笛卡尔（A）著《方法谈》，歌德（B）是文学家，莱辛（C）著《拉奥孔》。","multi":false},{"no":9,"t":"亚里士多德认为，喜剧是","o":["紧张和期待突然消失于虚无","内心突然的荣耀感","对比较坏的人的摹仿","把无价值的东西毁灭给人看"],"a":[2],"exp":"亚里士多德在《诗学》中认为，喜剧是对“比较坏的人”（滑稽可笑之人）的模仿，使人发笑而无需引起痛苦。A是康德对笑的解释，B是霍布斯的“突然荣耀说”，D是鲁迅论喜剧。","multi":false},{"no":10,"t":"朗吉弩斯认为","o":["崇高是伟大心灵的回声","崇高源于人的安全需要","崇高令人感到愉悦","崇高令人感到敬畏"],"a":[0],"exp":"朗吉弩斯在《论崇高》中提出，崇高是“伟大心灵的回声”，强调崇高来自作者庄严伟大的思想。B是博克的观点，C和D是康德对崇高的描述，非朗吉弩斯所述。","multi":false},{"no":11,"t":"黑格尔在悲剧研究中引入了","o":["理性思维","辩证思维","抽象思维","具象思维"],"a":[1],"exp":"黑格尔首次将辩证思维引入悲剧理论，提出悲剧是两种合理伦理力量的冲突与和解，在矛盾中实现“永恒正义”。理性思维（A）和抽象思维（C）是哲学的一般方法，具象思维（D）是艺术思维方式。","multi":false},{"no":12,"t":"从内容上看，荒诞更接近于","o":["悲剧","喜剧","滑稽","崇高"],"a":[0],"exp":"荒诞虽然形式上可能有怪诞和可笑，但其内容是对人生无意义、非理性的揭示，本质上更接近“悲剧”的沉重感。喜剧（B）和滑稽（C）以笑为主，崇高（D）以超越为主，均与荒诞不同。","multi":false},{"no":13,"t":"下列美学家中不属于经验主义者的是","o":["夏夫兹博里","荷加斯","哈奇生","奥古斯丁"],"a":[3],"exp":"奥古斯丁是中世纪神学美学家，不属于经验主义。夏夫兹博里（A）、荷加斯（B）、哈奇生（C）均为英国经验主义美学的重要代表。","multi":false},{"no":14,"t":"伽达默尔的美学思想属于","o":["自然主义","科学主义","解释学","存在学"],"a":[2],"exp":"伽达默尔是解释学美学的代表，其《真理与方法》将解释学应用于美学和艺术理解。自然主义（A）如桑塔亚那，科学主义（B）如托马斯·门罗，存在学（D）与海德格尔相关。","multi":false},{"no":15,"t":"中国古代诗人常常以香草喻君子，这属于美学理论中的","o":["畅神说","比德说","模仿说","再现说"],"a":[1],"exp":"“比德说”将自然物与人的道德品格相比附，如屈原以香草比喻君子的高洁品德。畅神说（A）强调自然对人的精神愉悦，模仿说（C）和再现说（D）是西方艺术本质论。","multi":false},{"no":16,"t":"英加登所说的艺术作品的“形而上质”体现了审美经验的","o":["直观性","超越性","直接功利性","间接功利性"],"a":[1],"exp":"“形而上质”如崇高、悲剧等深层意蕴，引导欣赏者超越具体现实进入精神境界，体现了审美经验的超越性。直观性（A）属感知层面，功利性（C、D）与超越性相反。","multi":false},{"no":17,"t":"马克思所说的“能感受形式美的眼睛”表明，审美经验的构成要素包括","o":["感知","想象","情感","理解"],"a":[0],"exp":"“感受形式美的眼睛”强调的是审美感知能力，即通过感官直接把握对象的形式美，因此属于感知这一构成要素。想象（B）、情感（C）、理解（D）也参与审美经验，但此句强调感知。","multi":false},{"no":18,"t":"审美经验中的联想活动不包括","o":["接近联想","类似联想","对比联想","创造联想"],"a":[3],"exp":"审美经验中的联想包括接近联想（A）、类似联想（B）、对比联想（C）。“创造联想”不是标准术语，联想本身是对已有经验的联结，而“创造”属于想象的高级形式。","multi":false},{"no":19,"t":"钱钟书说：“理之在诗，如水中盐、蜜中花，体匿性存，无痕有味。”这说明审美经验中的理解活动具有","o":["非概念性","非功利性","多义性","超验性"],"a":[0],"exp":"钱钟书此语说明诗中的道理（理）不直接以概念形式出现，而是融化在感性形象中，“体匿性存”体现了审美理解的非概念性——不依赖抽象概念而存在。B（非功利性）、C（多义性）、D（超验性）均不是此句的直接所指。","multi":false},{"no":20,"t":"中国古代书法艺术所蕴含的意象属于","o":["抽象","仿象","兴象","喻象"],"a":[0],"exp":"书法意象通过线条、结构等形式符号表达情感，不模仿具体物象，也不直接比喻意义，属于“抽象”型意象。仿象（B）模仿物象，兴象（C）触物起情，喻象（D）借喻表意，均不符合书法的特点。","multi":false},{"no":21,"t":"绘画对于生宣熟宣的严格要求，注重的是艺术的","o":["意境超验层","形式符号层","物质实在层","意象世界层"],"a":[2],"exp":"生宣熟宣是绘画的物质材料（纸张），属于艺术品的“物质实在层”。形式符号层（B）是色彩线条的排列，意象世界层（D）是审美形象，意境超验层（A）是深层意蕴。","multi":false},{"no":22,"t":"五四时期的新诗鼓励青年参与社会变革运动，这主要体现的是艺术的","o":["道德教育功能","社会干预功能","宗教感化功能","娱乐消遣功能"],"a":[1],"exp":"新诗鼓励青年参与社会变革，体现了艺术对社会生活的干预和推动作用，属于“社会干预功能”。道德教育功能（A）侧重品德培养，宗教感化（C）和娱乐消遣（D）均不符合。","multi":false},{"no":23,"t":"下列说法正确的是","o":["意境是一种形而上的人生境界","意境是一种形而下的人生境界","意境与中国人的哲学意识无关","意境一词早在先秦典籍中就出现了"],"a":[0],"exp":"意境超越具体意象，指向深远的哲理和情感空间，是一种“形而上”的人生境界。B（形而下）错误，C（与哲学无关）错误，D（先秦出现）错误——意境范畴形成于唐代。","multi":false},{"no":24,"t":"黑格尔认为，人类最初的艺术类型是","o":["象征型艺术","古典型艺术","浪漫型艺术","具象型艺术"],"a":[0],"exp":"黑格尔认为艺术发展三阶段中最初是象征型艺术（如古代东方建筑），理念找不到合适形式，形式压倒内容。古典型（B）是第二阶段，浪漫型（C）是第三阶段，具象型（D）非黑格尔术语。","multi":false},{"no":25,"t":"荣格把无意识分为","o":["民族无意识与人类无意识","个人无意识与个别无意识","个人无意识与集体无意识","集体无意识与潜意识"],"a":[2],"exp":"荣格将无意识分为个人无意识（个体压抑的记忆）和集体无意识（人类普遍的原型）。A、B、D均不是荣格的划分方式。","multi":false},{"no":26,"t":"提出乐教的作用在于“消融渣滓”的美学家是","o":["孔子","朱熹","孟子","老子"],"a":[1],"exp":"朱熹在论述乐教功能时提出“消融渣滓”之说，意为通过音乐陶冶消除人心中的杂念和私欲。孔子（A）强调“成于乐”，孟子（C）主性善，老子（D）尚自然，均无此表述。","multi":false},{"no":27,"t":"西方最早明确谈到审美教育的美学家是","o":["毕达哥拉斯","亚里士多德","德谟克利特","柏拉图"],"a":[3],"exp":"柏拉图在《理想国》中最早明确论述审美教育，强调用高尚文艺作品陶冶青少年心灵。毕达哥拉斯（A）谈数的和谐，亚里士多德（B）论悲剧净化，德谟克利特（C）论摹仿。","multi":false},{"no":28,"t":"美育的特点是","o":["诉诸理性、潜移默化、能动性","强制教育、诉诸感性、潜移默化","诉诸感性、潜移默化、能动性","行政命令、诉诸感性、能动性"],"a":[2],"exp":"美育的特点是诉诸感性（以情感打动）、潜移默化（长期熏陶）、能动性（发挥主体主动性）。A错在“诉诸理性”，B错在“强制”，D错在“行政命令”。","multi":false},{"no":29,"t":"美育与德育的关系是","o":["美育与德育相互促进","美育与德育相互冲突","美育等于德育","美育与德育无关"],"a":[0],"exp":"美育和德育相互区别（方式不同），但相互促进——美育通过情感陶冶有助于道德内化，德育为美育提供价值导向。B、C、D均错误。","multi":false},{"no":30,"t":"对于“美育是情感教育”这种观点，正确的评价是","o":["体现了中国天人合一的思维方式","体现了西方二元对立的思维方式","对美育与情感教育的关系做出了正确解释","对美育的内涵做出了科学理解"],"a":[1],"exp":"“美育是情感教育”将美育仅归结为情感培养，割裂了美育中情感与理性、感性与理性的统一，体现了西方二元对立的思维方式。A（天人合一）是中国思维方式，C和D夸大了这一观点的正确性。","multi":false},{"no":31,"t":"关于审美经验的非功利性的正确说法有","o":["审美经验与对象的实际存在无关","审美经验与对象的实际存在有关","审美经验的主要功能是让主体产生感官的快适","审美经验的主要功能不是让主体产生感官的快适","审美经验能够间接地满足主体的功利需要"],"a":[0,3,4],"exp":"审美经验虽与对象实际存在无关（A，指向意象而非实物），主要功能不是感官快适而是精神愉悦（D），但能间接满足功利需要（E，如陶冶情操有助社会和谐）。B（有关）和C（感官快适）与“非功利性”相悖。","multi":true},{"no":32,"t":"按照布洛的“审美距离说”，在审美经验中作用较大的感觉方式有","o":["视觉","听觉","触觉","嗅觉","味觉"],"a":[0,1],"exp":"布洛认为视觉和听觉更容易建立“心理距离”，因为它们不像触觉、嗅觉、味觉那样直接涉及物理接触和生理反应，更有利于保持审美观照的态度。触觉（C）、嗅觉（D）、味觉（E）因与身体直接接触，较难产生距离。","multi":true},{"no":33,"t":"艺术的非核心功能有","o":["审美功能","娱乐功能","认识功能","教育功能","道德功能"],"a":[1,2,3,4],"exp":"艺术的核心功能是审美功能（A），娱乐（B）、认识（C）、教育（D）、道德（E）都属于非核心功能，它们都需通过审美功能来实现。","multi":true},{"no":34,"t":"先秦儒家认为，美育的主要目的是实现","o":["天人关系的和谐","人际关系的和谐","家国关系的和谐","国家关系的和谐","人神关系的和谐"],"a":[0,1],"exp":"先秦儒家美育（如孔子的诗教乐教）旨在实现天人和谐（人与自然的和谐）和人际和谐（人与人的和谐）。C（家国）和D（国家）是政治层面的和谐，E（人神）是宗教层面的和谐，均非儒家美育的主要目的。","multi":true},{"no":35,"t":"美育根本上是一种特殊的人生境界的教育。对于这种观点的正确理解有","o":["把审美境界看作一种自由的人生境界","把造就审美的人作为美育的最高目的","把在审美活动中生成的美作为自由人生境界的感性显现","恢复了长期以来被遮蔽的美与人生实践的真实关系","强调了审美活动与日常活动的不同"],"a":[0,1,2,3],"exp":"该观点正确：审美境界是自由的人生境界（A），美育最高目的是造就审美的人（B），美是自由境界的感性显现（C），恢复了美与人生的真实关系（D）。E（强调与日常活动的不同）虽然正确，但不属于对该观点核心内涵的理解，故不选。","multi":true}],"essay":[{"no":36,"t":"简要说明美学属于人文学科而不属于社会科学的原因。","ans":"（1）研究对象不同。社会科学主要研究呈现为物化形态的社会现象，如社会关系、社会组织、社会制度等；人文学科则更多关注非物化形态的社会现象，如精神、理想、信念、价值等；（2）研究方式不同。社会科学力求判断的客观性和公正性。人文学科则不追求研究的客观性，往往要求研究者的参与和投入。","exp":"美学研究的是人的精神、情感、价值等主观性领域，属于人文学科范畴。社会科学以实证方法研究可量化的社会结构，而美学需要理解、体验和阐释，离不开研究者的主体参与。","type":"简答"},{"no":37,"t":"简述构成审美对象的物质因素。","ans":"（1）色彩。是事物各种审美条件中最重要的感性原料。（2）线条。是构成客体审美条件的一种重要的感性材料。（3）形状。是一切审美对象得以存在的最基本的层次。（4）音响。是人的一种听觉对象，也是客体审美条件的构成要素。（答出三点即可）","exp":"审美对象的物质因素包括色彩、线条、形状、音响等，它们作为感性材料，是审美对象赖以呈现的物质基础，通过形式组合产生美感。","type":"简答"},{"no":38,"t":"简述审美形态的历史性。","ans":"（1）审美形态的形成是特定的社会历史发展阶段的产物；（2）审美形态的具体内涵是在历史发展中不断演变的。","exp":"审美形态不是一成不变的，如“崇高”在不同时代有不同的内涵（古代重在自然力量，现代重在精神品格）；“荒诞”作为审美形态则是20世纪现代社会的产物，充分体现了审美形态的历史性。","type":"简答"},{"no":39,"t":"简述丑成为审美形态的原因。","ans":"（1）由丑引起的情绪感受与现实的反感不同，它包含着主体对生存实践的观照和体悟，因而仍然是一种审美情感；（2）丑表现为反常、混乱等形式，但从这些不和谐的形式中，仍能让人感受到人生的意义与价值。","exp":"丑成为审美形态，是因为在审美活动中，丑被形式化后，主体能从中获得对生活的深刻体悟——不是对丑本身的欣赏，而是通过丑反衬美，或在丑中看到人性的挣扎和生存的真相。","type":"简答"},{"no":40,"t":"简述审美态度在审美呈现中的作用。","ans":"（1）审美态度是指主体在摆脱了日常的功利和实用态度之后，所建立的一种观照、欣赏的态度；（2）审美态度能够改变主体在日常生活中与对象的分离和对立关系，建立起水乳交融、密不可分的关系。","exp":"审美态度是审美活动的主观前提，它使主体从功利态度转向观赏态度，从而让对象成为“审美对象”，让主体进入审美体验，实现主客交融。","type":"简答"},{"no":41,"t":"简述理解美育内涵需要遵循的主要原则。","ans":"（1）手段与效果相一致的原则；（2）直接效果与间接效果兼顾的原则；（3）独特性原则，即美育不同于智育、德育等其他教育方式的本质属性。","exp":"理解美育不能只看手段或只看效果，要兼顾二者；既要看到美育的即时感受，也要看到其长远影响；还要明确美育区别于其他教育方式的核心特性——以情感为中介、以感性为途径、以自由人格为目的。","type":"简答"},{"no":42,"t":"试论审美对象的有限性和无限性。","ans":"（1）审美对象尽管并非一种实物而只是一种意象，但都离不开一定的“物”，因而总是具体的、有限的；（2）审美对象能使人看到更多、更深、更远的东西，因而具有无限性；（3）审美对象的无限性就寄寓在它的有限性中，审美对象的不确定性和不可穷尽性就根源于它那既与过去沟通又向未来开放的生成性结构之中。","exp":"审美对象既是有限的（它依赖具体的物质媒介和感性形式，如一首诗、一幅画），又是无限的（它指向深远的意蕴，如李商隐《锦瑟》的语言有限但意蕴无穷）。有限性是无限性的载体，无限性是有限性的升华，二者辩证统一于审美对象的开放性结构之中。","type":"论述"},{"no":43,"t":"根据下面张孝祥的词，谈谈你对“艺术的核心功能是审美”这一命题的理解。洞庭青草，近中秋，更无一点风色。玉鉴琼田三万顷，著我扁舟一叶。素月分辉，明河共影，表里俱澄澈。悠然心会，妙处难与君说。应念岭表经年，孤光自照，肝胆皆冰雪。短发萧骚襟袖冷，稳泛沧溟空阔。尽把西江，细斟北斗，万象为宾客。叩舷独啸，不知今夕何夕！","ans":"（1）此词上景下情，萧疏空阔、清澈空灵的景与怡情山水、孤高自傲的情相互交融，意象生动、富有意境；（2）读者从鉴赏中能体验到一种超凡脱俗的审美感受，这是他从词中获得的最重要收获；（3）意象、意境在本质上是虚拟的、审美的，以意象世界作为核心的艺术品的首要功能只能是审美。","exp":"张孝祥此词描绘洞庭湖中秋月夜的澄澈空阔，抒发了词人超然物外、孤高自洁的情怀。读者阅读时首先获得的不是道德教训或科学知识，而是被“玉鉴琼田”“素月分辉”“表里俱澄澈”等意象所打动，产生审美愉悦和精神升华。即使词中隐含了词人被贬岭南的感慨，也是通过意象和意境来传达，以审美的方式呈现。这说明艺术的首要功能是审美——通过创造美的意象来打动人心、净化情感、提升精神，其他功能都需依附于审美功能才能实现。","type":"案例"}]},{"id":"2104","year":2021,"month":4,"label":"2021年4月","choice":[{"no":1,"t":"格式塔理论研究美学的角度是","o":["伦理学","心理学","艺术学","哲学"],"a":[1],"exp":"格式塔理论（完形心理学）从心理学的角度研究审美知觉，强调知觉的整体性和组织性，如“整体大于部分之和”。伦理学（A）研究道德，艺术学（C）研究艺术现象，哲学（D）是美学的传统基础但非格式塔的特定角度。","multi":false},{"no":2,"t":"美学研究的对象是","o":["美和美的规律","艺术","审美活动","审美经验"],"a":[2],"exp":"当代美学普遍认为，美学研究的对象是审美活动。美和美的规律（A）、艺术（B）、审美经验（D）都是审美活动中的具体方面或结果，审美活动是统摄性的核心范畴。","multi":false},{"no":3,"t":"主体进行审美判断的总的原则和尺度是","o":["审美理想","审美需要","审美趣味","审美态度"],"a":[0],"exp":"审美理想是主体关于完善的美的观念，是进行审美判断的总原则和最高尺度。审美需要（B）是动力，审美趣味（C）是具体偏好，审美态度（D）是主观前提。","multi":false},{"no":4,"t":"审美趣味的特点是","o":["无可争辩","具有好坏之分","没有明显的个性色彩","没有客观的评价标准"],"a":[1],"exp":"审美趣味虽然有“趣味无争辩”的说法，但仍有高下、雅俗之分，可以依据审美理想和修养加以评判。A（无可争辩）是休谟的观点但被辩证看待，C（无个性色彩）错误，D（无客观标准）不准确——尽管标准不是唯一的，但仍有客观依据。","multi":false},{"no":5,"t":"审美需要是","o":["人所独有的生命需要","一切生物共有的生命需要","人所独有的生理需要","一切生物共有的高级需要"],"a":[0],"exp":"审美需要是人类特有的精神需要，是人对精神自由和情感愉悦的内在追求，属于高级生命需要而非生理需要。B、C、D均否认了审美需要的人类独有性。","multi":false},{"no":6,"t":"认为审美对象是“灿烂的感性”的美学家是","o":["休谟","哈奇生","杜夫海纳","狄尔泰"],"a":[2],"exp":"杜夫海纳在《审美经验现象学》中提出，审美对象是“灿烂的感性”，即感性在审美活动中达到最充分、最辉煌的呈现。休谟（A）和哈奇生（B）是英国经验主义者，狄尔泰（D）是解释学美学家。","multi":false},{"no":7,"t":"在中国古代，黄色与王权相联系，这说明色彩的审美意义具有","o":["形象性","具象性","物质性","象征性"],"a":[3],"exp":"黄色与王权相联系，是色彩被赋予了特定的文化含义和社会意义，体现了色彩的象征性。形象性（A）和具象性（B）指色彩的可感性，物质性（C）指色彩的物理属性。","multi":false},{"no":8,"t":"认为“任何神话都是用想象和借助想象以征服自然力，支配自然力，把自然力加以形象化”的美学家是","o":["康德","歌德","马克思","恩格斯"],"a":[2],"exp":"此句出自马克思《〈政治经济学批判〉导言》，论述神话与想象力的关系，强调神话是原始人类借助想象征服自然的方式。康德（A）论崇高与优美，歌德（B）论艺术与自然，恩格斯（D）更多论述历史唯物主义。","multi":false},{"no":9,"t":"审美形态的历史性表现为","o":["在一定的历史条件下形成和演变","与人们的审美理想无关","能够超越历史条件的限制","内涵是固定不变的"],"a":[0],"exp":"审美形态是在特定历史条件下形成和发展的，其内涵随历史演变。B（与审美理想无关）错误，C（超越历史限制）和D（固定不变）均错误，历史性意味着变迁性和具体性。","multi":false},{"no":10,"t":"亚里士多德悲剧理论的艺术基础是","o":["古罗马悲剧","古希腊悲剧","古罗马史诗","古希腊史诗"],"a":[1],"exp":"亚里士多德的悲剧理论以古希腊悲剧（如索福克勒斯、欧里庇得斯的作品）为艺术基础，其《诗学》中的定义和原则都是从古希腊悲剧实践中总结出来的。古罗马悲剧（A）晚于亚里士多德，史诗（C、D）不是悲剧理论的基础。","multi":false},{"no":11,"t":"康德把崇高划分为","o":["伦理学的崇高和心理学的崇高","悲剧的崇高和喜剧的崇高","数学的崇高和力学的崇高","社会的崇高和自然的崇高"],"a":[2],"exp":"康德在《判断力批判》中将崇高分为“数学的崇高”（数量上的无限大）和“力学的崇高”（力量上的巨大）。A、B、D均非康德的分类方式。","multi":false},{"no":12,"t":"下列诗句中，体现了优美这一审美形态的是","o":["大漠孤烟直，长河落日圆","星垂平野阔，月涌大江流","吴楚东南坼，乾坤日夜浮","寒波澹澹起，白鸟悠悠下"],"a":[3],"exp":"“寒波澹澹起，白鸟悠悠下”描绘的是宁静、柔和、和谐的景象，体现优美。A、B、C均以宏大、壮阔的意象表现崇高或壮美。","multi":false},{"no":13,"t":"以讽刺和幽默为主要表现形式的审美形态是","o":["悲剧","荒诞","崇高","喜剧"],"a":[3],"exp":"喜剧以讽刺（尖锐批判）和幽默（温和诙谐）为主要表现形式。悲剧（A）以冲突和毁灭为主，荒诞（B）以怪诞和虚无为主，崇高（C）以巨大和力量为主。","multi":false},{"no":14,"t":"尼采认为，悲剧产生于古希腊的","o":["酒神精神和日神精神","宗教精神和理性精神","建筑和雕刻","戏剧和音乐"],"a":[0],"exp":"尼采在《悲剧的诞生》中提出，悲剧产生于酒神精神（狄奥尼索斯，代表激情、陶醉）和日神精神（阿波罗，代表理性、形式）的融合。B（宗教与理性）、C（建筑雕刻）、D（戏剧音乐）均非尼采的专门解释。","multi":false},{"no":15,"t":"创作主体与接受主体之间的中介是","o":["艺术家","艺术品","批评家","艺术意象"],"a":[1],"exp":"艺术品是连接艺术家（创作主体）和欣赏者（接受主体）的中介与桥梁。艺术家（A）是创作主体，批评家（C）是第三方阐释者，艺术意象（D）是艺术品的内核而非中介。","multi":false},{"no":16,"t":"介于审美和实用之间的艺术形态是","o":["建筑","雕塑","绘画","音乐"],"a":[0],"exp":"建筑既有实用功能（居住、使用），又有审美功能（形式美），是介于审美与实用之间的艺术形态。雕塑（B）、绘画（C）、音乐（D）的审美功能占主导，实用功能较弱或不存在。","multi":false},{"no":17,"t":"黑格尔把艺术分为","o":["象征型、古典型、写实型","象征型、古典型、浪漫型","象征型、具象型、浪漫型","象征型、古典型、抽象型"],"a":[1],"exp":"黑格尔按理念与形式的关系，将艺术分为象征型（形式压倒内容）、古典型（内容与形式统一）、浪漫型（内容压倒形式）。写实型（A）、具象型（C）、抽象型（D）均非黑格尔的分类术语。","multi":false},{"no":18,"t":"布瓦洛主张戏剧必须严格遵循","o":["同一律","三一律","矛盾律","排中律"],"a":[1],"exp":"布瓦洛是法国古典主义理论家，在《诗艺》中主张戏剧必须遵循“三一律”（时间、地点、情节的统一）。同一律（A）、矛盾律（C）、排中律（D）是逻辑学的三大规律。","multi":false},{"no":19,"t":"艺术接受过程的第一阶段是","o":["评","品","观","悟"],"a":[2],"exp":"艺术接受过程分为三个阶段：观（初步感知和意象重建）、品（深入体味和意象充实）、悟（意境升华和心灵共鸣），第一阶段是“观”。评（A）是批评环节，品（B）是第二阶段，悟（D）是第三阶段。","multi":false},{"no":20,"t":"“书不尽言，言不尽意”这句话出自","o":["《周易》","《离骚》","《淮南子》","《乐记》"],"a":[0],"exp":"“书不尽言，言不尽意”出自《周易·系辞》，指出语言和文字在表达意义时的局限性。B（屈原）、C（刘安）、D（儒家礼乐文献）均非此语出处。","multi":false},{"no":21,"t":"认为灵感来自神灵凭附的美学家是","o":["泰勒斯","德谟克利特","柏拉图","毕达哥拉斯"],"a":[2],"exp":"柏拉图在“迷狂说”中提出，灵感是神灵凭附在诗人身上的结果，诗人处于迷狂状态时才能创作。泰勒斯（A）是自然哲学家，德谟克利特（B）虽论灵感但更强调自然，毕达哥拉斯（D）论数的和谐。","multi":false},{"no":22,"t":"下列观点中，出自陆机《文赋》的是","o":["发愤著书","文以载道","诗缘情而绮靡","知人论世"],"a":[2],"exp":"“诗缘情而绮靡”出自陆机《文赋》，强调诗歌源于情感且文辞华美。A（司马迁）、B（韩愈等）、D（孟子）均不属《文赋》。","multi":false},{"no":23,"t":"对“哀而不伤，乐而不淫”理解正确的是","o":["阴阳相得","道法自然","习与性成","过犹不及"],"a":[3],"exp":"“哀而不伤，乐而不淫”出自孔子，强调情感表达应适度、有节制，即“过犹不及”的中庸思想。A（阴阳相得）是道家宇宙观，B（道法自然）是老子核心，C（习与性成）涉及习惯与本性。","multi":false},{"no":24,"t":"梁启超认为，美育是一种","o":["道德教育","人格教育","艺术教育","趣味教育"],"a":[3],"exp":"梁启超明确提出，美育是“趣味教育”，强调通过审美培养人的生命情趣。A（道德教育）是德育，B（人格教育）是蔡元培的提法，C（艺术教育）是美育的途径而非本质。","multi":false},{"no":25,"t":"提出“美育即情商”这一命题的美学家是","o":["王国维","胡适","宗白华","朱光潜"],"a":[3],"exp":"朱光潜曾以“美育即情商”的通俗说法，强调美育培养人的情感能力和生命感受力。王国维（A）首倡美育与德智体并称，胡适（B）主要论文学革命，宗白华（C）论意境与美学散步。","multi":false},{"no":26,"t":"下列表述中，不属于席勒美育理论的是","o":["从哲学高度解释了美育的独特目的","揭示了美育的价值是完善人性","回答了完善人性的方式","认为美育就是人格教育"],"a":[3],"exp":"席勒认为美育是完善人性的途径，但“美育就是人格教育”不是席勒的原话，人格教育是蔡元培等人的提法。A、B、C均为席勒在《审美教育书简》中的主要观点。","multi":false},{"no":27,"t":"审美教育的目的与审美活动所追求的价值具有","o":["同一性","差异性","对立性","因果性"],"a":[0],"exp":"审美教育的目的（培养完整人性、实现精神自由）与审美活动所追求的价值（自由、超越、情感愉悦）在本质上是一致的，具有同一性。B（差异性）、C（对立性）、D（因果性）均不符合。","multi":false},{"no":28,"t":"康德认为，美是道德的","o":["象征","形象","感性显现","理性底蕴"],"a":[0],"exp":"康德在《判断力批判》中提出“美是道德的象征”，认为美通过感性形式间接地指向道德理念。B（形象）、C（感性显现，黑格尔用语）、D（理性底蕴）均非康德的表述。","multi":false},{"no":29,"t":"艺术欣赏能够帮助主体确立远大的人生理想，这表明审美经验具有","o":["直观性","非功利性","情感性","超越性"],"a":[3],"exp":"艺术欣赏使人超越现实局限，上升到对人生理想的追求，体现了审美经验的超越性。直观性（A）是感知特征，非功利性（B）是态度特征，情感性（C）是心理特征。","multi":false},{"no":30,"t":"交感思考出现于审美经验的","o":["呈现阶段","构成阶段","评价阶段","回味阶段"],"a":[1],"exp":"交感思考是审美经验构成阶段中主体与对象之间的精神交流和情感互动，使审美理解成为双向交流。呈现阶段（A）是感知把握，评价阶段（C）是判断，回味阶段（D）是后续反思。","multi":false},{"no":31,"t":"以下学说中，属于审美发生理论的有","o":["生物本能说","性欲升华说","劳动说","符号说","移情说"],"a":[0,2],"exp":"审美发生理论探讨审美活动的起源，包括生物本能说（A）、劳动说（C）等。B（性欲升华说，弗洛伊德）属于生物本能说的一种，但官方答案未纳入；D（符号说）是艺术本质论，E（移情说）是审美心理学理论。","multi":true},{"no":32,"t":"悲剧作为审美形态的特点主要有","o":["个体性","社会性","和谐性","超越性","肯定性与否定性的结合"],"a":[1,3,4],"exp":"悲剧的特点包括：社会性（冲突源于社会历史矛盾）、超越性（在毁灭中超越）、肯定性与否定性的结合（否定性体验中展现肯定性价值）。A（个体性）和C（和谐性）是优美的特征，不属于悲剧。","multi":true},{"no":33,"t":"美育所培养的审美的人需要具备","o":["敏锐的审美能力","良好的审美趣味","健康的人生态度","完善的心理结构","丰富的个性魅力"],"a":[0,1,2,3,4],"exp":"美育培养的“审美的人”应是全面发展的，具备敏锐审美能力（A）、良好审美趣味（B）、健康人生态度（C）、完善心理结构（D）、丰富个性魅力（E），五个选项均正确。","multi":true},{"no":34,"t":"对贺拉斯“寓教于乐”的原则理解正确的有","o":["德育与智育相统一","美育与智育相统一","教育功能与娱乐功能相统一","美育与德育相统一","直接教育人"],"a":[2,3],"exp":"“寓教于乐”强调教育功能与娱乐功能的统一（C），以及美育（通过审美愉悦）与德育（实现教化目的）的统一（D）。A（德育与智育）、B（美育与智育）均非贺拉斯原意，E（直接教育人）与“寓教”的间接性相悖。","multi":true},{"no":35,"t":"倡导“内在感官说”的美学家有","o":["休谟","哈奇生","夏夫兹博里","博克","洛克"],"a":[1,2],"exp":"“内在感官说”主要由夏夫兹博里（C）和哈奇生（B）倡导，认为人类有专门感知美的内在感官。休谟（A）和博克（D）属于经验主义美学家但非“内在感官说”的主要代表，洛克（E）是认识论哲学家。","multi":true}],"essay":[{"no":36,"t":"简述美学的学科属性。","ans":"（1）美学最初是从哲学中分化出来的，但在后来的发展过程中，逐渐受到了各种社会科学以及自然科学的影响，从而使其学科属性变得复杂化了。（2）从美学发展的历史和现状着眼，我们认为美学是一门研究审美现象的综合性人文学科。","exp":"美学既与哲学有着深厚渊源，又广泛吸收心理学、社会学、人类学等学科的方法，研究审美现象时既需要哲学思辨，也需要实证分析。但其核心归属仍是人文学科，因为审美活动的价值、意义问题无法通过纯粹科学方法解决。","type":"简答"},{"no":37,"t":"简述审美惊异产生的条件。","ans":"（1）审美惊异就是人在一定的现实境遇中由于与客体对象的直接契合所产生出来的一种迥异于日常生活经验的特殊心境。（2）审美惊异的产生既依赖于主体一定的自身条件，也依赖于对象本身一定的客观条件。（3）从主体方面说，必须具备相当的审美修养和审美能力，从对象方面说，也必须具备某种独特之处。","exp":"审美惊异是审美活动的起点，它不是凭空产生的，需要主体有审美准备（修养、心境），也需要对象有能激发惊奇的独特形式或意蕴，二者相遇时产生“如初相见”的新鲜感和震撼感。","type":"简答"},{"no":38,"t":"简述卢卡契关于原始巫术与模仿艺术之间关系的基本观点。","ans":"卢卡契认为巫术为模仿艺术的形成所作的准备主要体现在两个方面：第一，在巫术中为了达到某一目的，就必须对达到这一目的的实际过程进行逼真的模仿。第二，巫术中对生活过程的模仿是在一种虚拟的情境中进行的，它本身并不是一种实际的生活过程，而是与实际生活过程的暂时中断。","exp":"卢卡契揭示巫术活动为艺术的产生准备了两个关键条件：一是模仿能力（对现实的再现），二是虚拟情境（与现实的距离）。这使巫术成为从实用活动到审美活动的重要过渡。","type":"简答"},{"no":39,"t":"简述柏拉图的美育思想。","ans":"（1）柏拉图是西方最早明确谈到审美教育的哲学家。（2）他认为通过审美教育可以陶冶人的心灵，必须从幼年起就对人施行严格的教育。（3）柏拉图想通过高尚的文艺作品培养和陶冶青少年的心灵，他很重视音乐教育。","exp":"柏拉图强调美育对塑造灵魂的重要性，尤其注重音乐教育，认为节奏和乐调能深入心灵。他主张严格筛选文艺内容，以培养青少年的节制和美德，其美育观服务于理想国的政治目标。","type":"简答"},{"no":40,"t":"简述审美感知的特点。","ans":"（1）审美感知作为审美经验的构成要素，总与情感活动紧紧地交织在一起。（2）能动性和选择性是审美感知活动的显著特点。（3）审美感知总以完形的方式来把握对象，因而具有整体性的特点。","exp":"审美感知不同于日常感知，它受情感驱动，主动选择对象的审美属性，并以整体性的方式把握对象形式，而非被动地接受零散信息。","type":"简答"},{"no":41,"t":"简述布洛的审美距离说。","ans":"（1）审美距离是布洛提出的一个审美心理学概念，是主体在审美活动中必须与对象保持一定的心理距离。（2）审美距离能够使主体摆脱利害关系的束缚，以非功利的态度来对待事物。（3）审美主体只有与对象拉开一定的审美距离，才能对其做出具有普遍性的审美评价。","exp":"布洛认为适当的心理距离是审美态度的核心，距离过近（太功利）会阻碍审美，距离过远（太冷漠）也会失去审美关联。只有保持“不即不离”的距离，才能进入纯粹的审美观照。","type":"简答"},{"no":42,"t":"试论审美形态与文化之间的关系。","ans":"就审美形态与宗教的关系而言：（1）西方审美形态的孕育一开始就与宗教意识密切联系，悲剧与喜剧的区分就与古希腊人的祭神及狂欢活动，即常讲的酒神精神和日神精神有关。（2）西方悲剧里崇尚的实际是一种牺牲精神，是为宗教理想而献身从而在人生中求得永恒的行动。（3）中国审美文化具有世俗化特征，表现为：①把上帝、神灵人格化与把人的祖先神灵化合二为一，即祭祖犹如祭神；②与世俗的享乐主义和现世思想相结合，如道教文化。就审美形态与哲学的关系而言：（1）古希腊哲学强调从形式与质料之间的二元关系的角度分析艺术作品与美，并且强调形式构成的相对独立性。（2）文艺复兴之后，以人为本的理性主义就成为西方美学主要的哲学基础。","exp":"审美形态不是纯然自足的形式，而是特定文化土壤的产物。宗教为审美形态提供精神气质（如西方的悲剧精神、日神酒神传统），哲学为审美形态提供理论框架（如形式与质料、理性主义）。中国文化中的世俗化倾向则塑造了不同于西方的审美形态特征。审美形态与文化相互渗透、互为表征，文化是审美形态的深层根源，审美形态是文化精神的感性显现。","type":"论述"},{"no":43,"t":"结合具体作品，谈谈绘画艺术的审美特征。","ans":"（1）对绘画的欣赏首先要关注它内在的意蕴。在我国古代，有“观画之法，先观气韵，次观笔意、骨法位置敷染，然后形似”的说法（《画鉴》）。（2）其次要掌握绘画的基本语言的审美性质。（3）画面内在的韵律，也就是动感的捕捉是绘画美的灵魂。（4）在空间艺术的各种形态中，绘画最具有主观性和精神性。","exp":"以中国传统绘画为例：顾恺之《洛神赋图》注重“气韵生动”，通过线条的飞动和人物神态传达情感意蕴（内在意蕴）；画中“春蚕吐丝”般的线条和淡雅设色（基本语言），使画面呈现出流动的韵律感（内在韵律）；画家在实景之外营造出缥缈的神仙意境，体现了绘画作为空间艺术中最具主观性和精神性的特征。再如西方绘画，达·芬奇《蒙娜丽莎》通过光影晕染和微妙的表情，呈现了超越画面本身的深层意蕴。绘画区别于其他艺术的核心，在于它能在二维平面上通过形式语言（线条、色彩、构图）的创造性组合，既描绘可见世界，又表达不可见的内心世界和精神气象。","type":"案例"}]},{"id":"2110","year":2021,"month":10,"label":"2021年10月","choice":[{"no":1,"t":"美学思想是","o":["系统的理论思考","朦胧的审美体验","具体的审美活动","主观的审美感受"],"a":[0],"exp":"美学思想是对审美现象进行系统化、理论化的思考成果，区别于朦胧的审美体验（B）、具体的审美活动（C）和主观的审美感受（D），后者是美学思想的源头而非本身。","multi":false},{"no":2,"t":"鲍姆嘉通认为，美学是研究","o":["美的科学","艺术的科学","美感经验的科学","感性认识的科学"],"a":[3],"exp":"鲍姆嘉通在《美学》中定义美学为“感性认识的科学”（Aesthetica），旨在弥补理性认识之外的感性认识领域。A是柏拉图等的观点，B是黑格尔的观点，C是现代美学的倾向。","multi":false},{"no":3,"t":"在审美心理结构中处于最高位置的是","o":["审美趣味","审美理想","审美需要","审美观念"],"a":[1],"exp":"审美理想是主体关于完善的美的观念，在审美心理结构中处于最高位置，统摄和引导审美趣味、审美需要等。审美需要（C）是动力，审美趣味（A）是偏好，审美观念（D）是具体认知。","multi":false},{"no":4,"t":"“状难写之景如在目前，含不尽之意见于言外”，这句话说明审美对象具有","o":["实体性","确定性","有限性","开放性"],"a":[3],"exp":"此句意为描绘难以描写的景象如在眼前，包含无尽的意蕴在语言之外，说明审美对象的意蕴是开放、无限生成的，具有开放性。实体性（A）、确定性（B）、有限性（C）均与此意相反。","multi":false},{"no":5,"t":"审美对象是","o":["先于审美主体而存在的","审美活动得以发生的前提","由审美主体主观创造的","在审美活动中现实生成的"],"a":[3],"exp":"审美对象不是在审美活动之前就存在的客观实体，而是在审美活动中由主体与对象共同建构生成的。A是客观主义观点，B颠倒关系，C是主观唯心主义。","multi":false},{"no":6,"t":"提出“劳动先于艺术”这一命题的美学家是","o":["马克思","普列汉诺夫","卢卡契","列宁"],"a":[1],"exp":"普列汉诺夫在《没有地址的信》中明确提出“劳动先于艺术”的命题，系统论证了艺术起源于劳动。马克思（A）虽奠定理论基础但未直接提出此命题，卢卡契（C）和列宁（D）也论述相关但非最早提出者。","multi":false},{"no":7,"t":"在审美形态的划分标准中，统摄性是指","o":["同一性","地域性","融具体于抽象","集杂多于统一"],"a":[3],"exp":"审美形态的“统摄性”是指能将多种审美现象和特征集为一体，即“集杂多于统一”，如悲剧包含冲突、抗争、毁灭等多种因素。A（同一性）、B（地域性）、C（融具体于抽象）均不准确。","multi":false},{"no":8,"t":"明确把美划分为“秀美”与“威严”两种类型的美学家是","o":["西塞罗","休谟","黑格尔","席勒"],"a":[0],"exp":"古罗马美学家西塞罗最早明确将美划分为“秀美”（优美）与“威严”（崇高）两种类型。休谟（B）论趣味，黑格尔（C）论理念，席勒（D）论美育，均晚于西塞罗。","multi":false},{"no":9,"t":"审美形态具有民族性与世界性，这说明了审美形态的","o":["普适性","历史性","贯通性","二重性"],"a":[3],"exp":"审美形态既具有民族性（特定文化语境中形成），又具有世界性（人类普遍审美经验），这体现了审美形态的“二重性”。普适性（A）过于绝对，历史性（B）侧重时间维度，贯通性（C）不准确。","multi":false},{"no":10,"t":"认为优美不会给人带来任何压抑的美学家是","o":["康德","荷迦兹","苏格拉底","柏拉图"],"a":[0],"exp":"康德在《判断力批判》中认为，优美直接带来愉悦，不会给人带来压抑；崇高则先有压抑后有快感。荷迦兹（B）论形式美，苏格拉底（C）和柏拉图（D）均未作此区分。","multi":false},{"no":11,"t":"开启现代丑学的是","o":["波德莱尔的《恶之花》","雨果的《克伦威尔序》","阿多诺的《美学理论》","罗森克兰兹的《丑的美学》"],"a":[3],"exp":"德国美学家罗森克兰兹1853年出版《丑的美学》，首次系统研究丑，开启了现代丑学。波德莱尔（A）是文学实践，雨果（B）提出美丑对照原则，阿多诺（C）是20世纪理论，均非最早系统研究。","multi":false},{"no":12,"t":"博克进行比较研究的两种审美形态是","o":["悲剧与喜剧","荒诞与丑","壮美与滑稽","优美与崇高"],"a":[3],"exp":"博克在《论崇高与优美》中对“优美”与“崇高”两种审美形态进行了系统比较研究，分析其不同特征和起源。悲剧与喜剧（A）是亚里士多德的研究对象，荒诞与丑（B）是现代课题。","multi":false},{"no":13,"t":"杜威的美学思想属于","o":["解释学","实用主义","存在主义","分析美学"],"a":[1],"exp":"杜威是美国实用主义哲学的代表，其美学著作《艺术即经验》是实用主义美学的经典。解释学（A）如伽达默尔，存在主义（C）如萨特，分析美学（D）如维特根斯坦。","multi":false},{"no":14,"t":"叔本华认为审美是一种","o":["感性活动","理性活动","意志活动","观审活动"],"a":[3],"exp":"叔本华认为审美是“观审”（无利害的静观），主体在审美中暂时摆脱意志的束缚，成为纯粹的认识主体。A和B片面，C与叔本华观点相反——审美正是摆脱意志的活动。","multi":false},{"no":15,"t":"“智者乐水，仁者乐山”，这体现了中国古代的","o":["比德说","畅神说","言志说","比兴说"],"a":[0],"exp":"“比德说”将自然物的形态特征与人的道德品格相比附，智者乐水（水的灵动象征智慧）、仁者乐山（山的沉稳象征仁德）正是比德说的典型体现。畅神说（B）强调精神愉悦，言志说（C）论诗言志，比兴说（D）是诗歌手法。","multi":false},{"no":16,"t":"夏夫兹博里认为，审辨美丑的能力依赖于","o":["内在感官","外在感官","视觉器官","听觉器官"],"a":[0],"exp":"夏夫兹博里提出“内在感官说”，认为人类有专门审辨美丑的“内在感官”（或“第六感官”），不同于外在五官。外在感官（B）、视觉（C）、听觉（D）均属外在感官，不能单独完成审美判断。","multi":false},{"no":17,"t":"在英加登看来，审美经验开始于","o":["审美感知","审美理解","原始情感","原始想象"],"a":[2],"exp":"英加登认为审美经验以“原始情感”为起点，这种情感是主体被对象打动的最初反应，然后才展开感知和想象。A（审美感知）是后续环节，B（理解）和D（想象）是在情感驱动下发展的。","multi":false},{"no":18,"t":"审美经验中最活跃的要素是","o":["感知","想象","情感","理解"],"a":[2],"exp":"情感是审美经验中最活跃的要素，它驱动感知、激发想象、渗透理解，使审美体验充满生命活力。想象（B）虽活跃，但受情感驱动；感知（A）是基础，理解（D）是深化。","multi":false},{"no":19,"t":"立普斯提出了","o":["净化说","移情说","心理距离说","审美距离说"],"a":[1],"exp":"立普斯是“移情说”的主要代表，认为审美欣赏实质上是主体将自我情感投射到对象之中。A（净化说）是亚里士多德，C（心理距离说）和D（审美距离说）是布洛。","multi":false},{"no":20,"t":"雕塑属于","o":["时间艺术","语言艺术","空间艺术","视听艺术"],"a":[2],"exp":"雕塑以三维立体形式存在于空间中，属于空间艺术。时间艺术（A）如音乐，语言艺术（B）如文学，视听艺术（D）如戏剧、电影。","multi":false},{"no":21,"t":"但丁提出，文学作品除了字面意义外，还有","o":["抽象的意义","神秘的意义","现代的意义","传统的意义"],"a":[1],"exp":"但丁在《致斯加拉大亲王书》中提出，文学作品有四种意义：字面意义、譬喻意义、道德意义、神秘意义。他特别强调作品除了字面意义外还有“神秘的意义”（即寓言性或超验意义）。A、C、D均非但丁的表述。","multi":false},{"no":22,"t":"艺术接受的核心是","o":["形式的鉴赏","作品的评价","意义的阐释","意象的重建"],"a":[3],"exp":"艺术接受的核心是欣赏者根据作品提供的符号系统，在自身经验基础上重建艺术意象，完成审美体验。形式的鉴赏（A）是表层，作品的评价（B）和意义的阐释（C）都是重建后的结果。","multi":false},{"no":23,"t":"黑格尔认为古典型艺术的代表是","o":["古埃及的雕刻","古埃及的建筑","古巴比伦的建筑","古希腊的雕刻"],"a":[3],"exp":"黑格尔认为古典型艺术是内容与形式的完美统一，其代表是古希腊雕刻（如菲迪亚斯作品）。古埃及艺术（A、B）属于象征型，古巴比伦建筑（C）也属象征型。","multi":false},{"no":24,"t":"“观古今于须臾，抚四海于一瞬”，这句话指的是艺术创造活动中的","o":["艺术想象力","艺术敏感","艺术技巧","艺术灵感"],"a":[0],"exp":"此句（陆机《文赋》）形容艺术想象超越时空界限的自由创造能力。艺术敏感（B）是感受的敏锐，艺术技巧（C）是操作方法，艺术灵感（D）是突发状态。","multi":false},{"no":25,"t":"克莱夫·贝尔提出的艺术理论是","o":["心理距离说","有意味的形式说","欲望升华说","集体无意识说"],"a":[1],"exp":"克莱夫·贝尔在《艺术》中提出“有意味的形式”理论。A（心理距离说）是布洛，C（欲望升华说）是弗洛伊德，D（集体无意识说）是荣格。","multi":false},{"no":26,"t":"美育在中国成为一个独立的学科开始于","o":["明清","近代","现代","当代"],"a":[1],"exp":"美育在中国作为独立学科始于近代（清末民初），以王国维、蔡元培等人的倡导为标志。明清（A）有美育思想但非独立学科，现代（C）和当代（D）是发展期。","multi":false},{"no":27,"t":"提出“美育群材，其犹人之于艺乎”的是","o":["孔子","徐干","孟子","王勃"],"a":[1],"exp":"此语出自东汉徐干《中论·艺纪》，强调美育对于培养人才就像技艺对人一样重要。孔子（A）、孟子（C）、王勃（D）均无此表述。","multi":false},{"no":28,"t":"席勒认为实现自由的唯一途径是","o":["人格教育","情感教育","道德教育","审美教育"],"a":[3],"exp":"席勒在《审美教育书简》中认为，只有通过审美教育才能克服人性的分裂，实现感性与理性的统一，从而进入自由王国。A（人格教育）是结果，B（情感教育）是部分，C（道德教育）是德育。","multi":false},{"no":29,"t":"贺拉斯“寓教于乐”的原则强调","o":["美育与德育的统一","美育与智育的统一","美育与体育的统一","德育与智育的统一"],"a":[0],"exp":"贺拉斯“寓教于乐”强调美育（通过审美愉悦）与德育（实现道德教化）的统一。B（美育与智育）、C（美育与体育）、D（德育与智育）均非贺拉斯此语的核心。","multi":false},{"no":30,"t":"美育的怡情养性功能指的是","o":["通过调节达到心理平衡","追求智力的提高","依靠强制的手段","依靠道德说教"],"a":[0],"exp":"美育的“怡情养性”功能是指通过审美活动调节人的情感，达到心理平衡和人格完善。B是智育功能，C和D与美育的“潜移默化”特性相悖。","multi":false},{"no":31,"t":"审美经验的直观性包括","o":["非理性直观","本质直观","理性直观","知性直观","感性直观"],"a":[1,4],"exp":"审美经验的直观性包括“感性直观”（对形象的直接感知）和“本质直观”（对深层意蕴的直接把握）。A（非理性直观）、C（理性直观）、D（知性直观）均不是审美直观的规范分类。","multi":true},{"no":32,"t":"审美理解的特征有","o":["想象性","情感性","概念性","非概念性","多义性"],"a":[3,4],"exp":"审美理解的特征包括非概念性（不依赖抽象概念）和多义性（允许多重解读）。想象性（A）和情感性（B）是想象和情感的特征，概念性（C）与审美理解相反。","multi":true},{"no":33,"t":"对广义的美育理解正确的有","o":["泛指审美活动具有的教育功能","泛指利用审美塑造人的教育活动","泛指社会、学校、家庭进行的教育活动","具有感染人、影响人、教育人的功能","与智育、德育无关"],"a":[0,1,3],"exp":"广义美育泛指审美活动的教育功能（A）、利用审美塑造人的教育（B）、具有感染人教育人的功能（D）。C（社会学校家庭）是一般教育的范畴而非美育特有，E（与德育智育无关）错误。","multi":true},{"no":34,"t":"在美育与宗教的关系上，蔡元培认为","o":["美育是民族的，宗教是世界的","美育是进步的，宗教是保守的","美育是普及的，宗教是有界的","美育是自由的，宗教是强制的","美育是理性的，宗教是感性的"],"a":[1,2,3],"exp":"蔡元培提出“以美育代宗教”，认为美育是进步的、普及的、自由的；宗教是保守的、有界的、强制的。A（美育是民族的，宗教是世界的）和E（美育是理性的）均不是蔡元培的原话。","multi":true},{"no":35,"t":"“艺术游戏说”的代表人物有","o":["康德","席勒","斯宾塞","温克尔曼","费希特"],"a":[0,1,2],"exp":"艺术游戏说认为艺术起源于人类的游戏冲动，代表人物有康德（提出自由游戏）、席勒（系统论述游戏冲动）、斯宾塞（发展游戏说）。温克尔曼（D）研究古希腊艺术，费希特（E）是哲学家。","multi":true}],"essay":[{"no":36,"t":"简述美学与社会科学的差异。","ans":"（1）研究对象不同。美学的研究对象是人的审美活动，社会科学的研究对象则是社会关系。（2）研究方法不同。美学研究要求主体亲自体验和参与，社会科学则要求排除主体的情感介入。","exp":"美学属于人文学科，关注人的精神、情感、价值等主观性领域，要求研究者投入体验和理解；社会科学关注社会结构等客观现象，追求价值中立和客观判断，二者在研究对象和方法上有根本区别。","type":"简答"},{"no":37,"t":"简述审美体验的整体性特征。","ans":"（1）是诸种人生体验的浓缩和凝聚。（2）是各种实际人生体验的净化和升华。（3）是对人生整体价值和根本意义的领悟和玩味。","exp":"审美体验不是零散的感受，而是将多种人生经验整合、提炼、升华，形成对生命整体意义的深刻把握，使人在有限体验中触及无限价值。","type":"简答"},{"no":38,"t":"简述荒诞的基本特点。","ans":"（1）荒诞是一种对人生存在无意义状态的体悟。（2）荒诞的表现形式是怪诞、变形、不合理。（3）荒诞具有反理性的特征，表现世界的不可理解和人的异化。（按官方答案，本题与第37题答案重复，此处按标准知识点补充）","exp":"荒诞是20世纪现代审美形态，其核心是对世界非理性和人生虚无的深刻感受，在艺术中通过夸张、变形、反逻辑等手法呈现，引发观众的震惊和反思。","type":"简答"},{"no":39,"t":"简述审美形态的兼容性。","ans":"（1）审美形态是多种审美因素的有机融合。（2）审美形态可以与各种审美风格和艺术体裁相容。","exp":"审美形态不是单一纯粹的模式，而是多种因素的综合体。例如悲剧可以兼容崇高、优美、丑等多种元素，也可以体现在戏剧、小说、绘画等不同艺术体裁中，具有广泛的兼容性。","type":"简答"},{"no":40,"t":"简述审美经验的非功利性特征。","ans":"（1）从审美对象的角度看，审美经验只涉及事物的外观和形式，与事物的实际存在无关，因此不会与对象发生利害关系。（2）从审美主体的角度看，审美经验的基本功能在于满足人们的审美需要，这就要求排除各种功利因素的干扰。","exp":"审美经验以直觉观照为主，不追求对象的实际占有或实用价值，主体搁置功利计较，专注于对象的形式和意蕴，从而获得自由的审美愉悦。","type":"简答"},{"no":41,"t":"简述梁启超的美育思想。","ans":"（1）美育是一种趣味教育，不同于强制教育。（2）美育是一种情感教育，具有动之以情的特征。（3）美育以感化的方式教育人。","exp":"梁启超强调美育的“趣味”本质，认为美育通过情感感染而非强制灌输来教育人，其“熏、浸、刺、提”说进一步揭示了美育潜移默化的特点。","type":"简答"},{"no":42,"t":"试论审美理想与人生理想的关系。","ans":"（1）审美理想作为一种人生修养，使审美活动成为主体人生实践的重要组成部分。审美活动通过诉诸人的情感，使主体的人生信念更加坚定，从而对主体的人生理想带来巨大影响。（2）审美理想并不仅仅是审美活动本身的产物，而是主体全部人生实践的结晶，因此人生理想在一定意义上决定了审美理想。","exp":"审美理想与人生理想相互渗透、双向塑造。一方面，人生理想（如对真善美的追求）为审美理想提供价值方向，使审美判断具有深刻的精神内涵；另一方面，审美理想通过情感陶冶和境界提升，使人更坚定地追求崇高的人生理想。二者统一于人的生存实践之中，共同构成完整的人格境界。","type":"论述"},{"no":43,"t":"结合下面的诗歌，谈谈艺术意象的基本特征。赠汪伦李白李白乘舟将欲行，忽闻岸上踏歌声。桃花潭水深千尺，不及汪伦送我情。","ans":"（1）虚拟性。艺术意象具有非现实性，是由艺术家虚构和创造出来的。（2）直观性。艺术意象可以被主体直接感知，不需经过自觉的理性反思。（3）想象性。艺术意象是想象的产物，不同于单纯的回忆表象。（4）情感性。艺术家创造意象的活动饱含着情感，因而意象具有强烈的感染力。","exp":"这首诗充分体现了艺术意象的基本特征：虚拟性——“桃花潭水深千尺”并非实写，而是艺术夸张的虚拟意象；直观性——“桃花潭水”“踏歌声”等意象直接诉诸读者的感官想象；想象性——诗人通过想象将潭水之深与友情之厚联结，创造了独特的意象组合；情感性——“不及汪伦送我情”将全部意象凝结于深厚友情之中，使读者感受到强烈的情感冲击。这四者共同构成完整的艺术意象，使其超越了对送别场景的简单再现，成为千古传诵的审美结晶。","type":"案例"}]},{"id":"2204","year":2022,"month":4,"label":"2022年4月","choice":[{"no":1,"t":"认为美的本质问题是个伪命题的美学家是","o":["黑格尔","杜威","维特根斯坦","马克思"],"a":[2],"exp":"维特根斯坦从分析哲学角度认为“美”的本质无法精确定义，美的本质问题是一个没有意义的伪命题。黑格尔（A）和马克思（D）都探讨美的本质，杜威（B）从经验角度论美。","multi":false},{"no":2,"t":"下列关于审美关系和审美活动之间关系的表述正确的是","o":["先有审美关系才有审美活动","审美关系是通过审美活动而建构起来的","审美活动是通过审美关系而建构起来的","审美活动的根本动力是人的审美关系"],"a":[1],"exp":"审美关系不是先在的，而是在具体的审美活动中生成和建构起来的。没有审美活动，审美关系就无从产生。A颠倒了关系，C和D都将审美关系置于审美活动之前。","multi":false},{"no":3,"t":"“霜叶红于二月花”中构成“霜叶”之美的物质因素是","o":["线条","形状","色彩","音响"],"a":[2],"exp":"此句以“红”字突出霜叶的色彩之美，色彩是构成其美感的主要物质因素。线条（A）、形状（B）、音响（D）均非此句的核心表现对象。","multi":false},{"no":4,"t":"马克思说：“像拉斐尔这样的个人是否能顺利地发展他的天才，这就完全取决于需要，而这种需要又取决于分工以及由于分工产生的人们所受教育的条件。”这说明影响主体审美趣味形成的主要因素是","o":["个人所处的家庭条件","个人的职业选择","个人所处的社会条件","个人的天赋资质"],"a":[2],"exp":"马克思强调社会分工和教育等社会条件决定艺术家才能的发展，说明审美趣味的形成主要受社会条件制约。家庭条件（A）和天赋资质（D）虽有一定影响，但非马克思强调的主要因素。","multi":false},{"no":5,"t":"下列选项中与审美理想关系最为密切的是","o":["自然天赋和资质","个人爱好和倾向","家庭背景和交往","人生修养和境界"],"a":[3],"exp":"审美理想是主体关于完善的美的观念，与主体的人生修养和精神境界密切相关。自然天赋（A）和家庭背景（C）是外在条件，个人爱好（B）是趣味层面，均非审美理想的核心。","multi":false},{"no":6,"t":"审美趣味是个人在审美活动和审美评价中所表现出来的","o":["主观爱好和倾向","客观态度和立场","总的原则和尺度","人生理想与信仰"],"a":[0],"exp":"审美趣味是主体在审美活动中表现出的个人化的主观爱好和倾向。B（客观态度）不准确，C（总的原则尺度）是审美理想，D（人生理想信仰）是更高层次。","multi":false},{"no":7,"t":"下列选项中不属于审美形态划分标准的是","o":["普适性","统摄性","历史性","正统性"],"a":[3],"exp":"审美形态的划分标准包括普适性（广泛适用）、统摄性（集杂多于统一）、历史性（文化积淀和持久影响）。“正统性”不是审美形态划分的标准，美学不预设正统与非正统的等级。","multi":false},{"no":8,"t":"在西方美学史上，优美演化为与崇高并举的审美形态，这种现象发生在","o":["中世纪","文艺复兴时期","近代","现代"],"a":[2],"exp":"在近代（17-18世纪），博克、康德等美学家将优美与崇高并举，使之成为两种并列的基本审美形态。中世纪（A）美学以神学为主，文艺复兴（B）时期优美尚未与崇高并举，现代（D）已进入更多形态的拓展。","multi":false},{"no":9,"t":"审美形态具有","o":["贯通性","永恒性","一元性","主观性"],"a":[0],"exp":"审美形态之间具有贯通性，即不同审美形态可以相互渗透、兼容，如悲剧中可以有崇高，荒诞中可以有丑。B（永恒性）错误——审美形态是历史的；C（一元性）错误——审美形态是多元的；D（主观性）不全面。","multi":false},{"no":10,"t":"加缪的小说《局外人》所体现的审美形态是","o":["悲剧","喜剧","荒诞","崇高"],"a":[2],"exp":"加缪是存在主义哲学家，《局外人》表现世界非理性和人的异化、无意义感，是荒诞审美形态的典型代表。A（悲剧）强调冲突与毁灭，B（喜剧）强调笑，D（崇高）强调超越，均不符合。","multi":false},{"no":11,"t":"《丑的美学》一书的作者是","o":["康德","恩格斯","李斯托威尔","罗森克兰兹"],"a":[3],"exp":"德国美学家罗森克兰兹于1853年出版《丑的美学》，首次系统研究丑这一审美形态。康德（A）论崇高与优美，恩格斯（B）论悲剧，李斯托威尔（C）著《近代美学史评述》。","multi":false},{"no":12,"t":"“明月照积雪”“长河落日圆”，这两句诗所体现的审美形态是","o":["优美","婉约","中和","崇高"],"a":[3],"exp":"“明月照积雪”有清冷宏大之感，“长河落日圆”有苍茫壮阔之势，二者都带有雄伟、辽阔的崇高特征。优美（A）强调和谐小巧，婉约（B）偏柔美，中和（C）是儒家美学范畴。","multi":false},{"no":13,"t":"在审美经验的构成要素中，处于基础地位的是","o":["感知","想象","情感","理解"],"a":[0],"exp":"感知是审美经验的起点和基础，没有感知就无法获得审美对象的感性材料。想象（B）在感知基础上加工，情感（C）是动力，理解（D）是深化。","multi":false},{"no":14,"t":"夏夫兹博里认为审辨美丑的能力依赖于","o":["视觉器官","听觉器官","内在感官","外在感官"],"a":[2],"exp":"夏夫兹博里提出“内在感官说”，认为人类有专门审辨美丑的内在感官（第六感官），不同于外在五官。视觉（A）和听觉（B）是外在感官的具体形式，外在感官（D）整体上不具备审美判断的专门性。","multi":false},{"no":15,"t":"屈原常以香草喻君子，这类现象被概括为","o":["畅神","缘情","比兴","比德"],"a":[3],"exp":"以香草喻君子是将自然物与人的道德品格相比附，属于“比德说”。畅神（A）强调精神愉悦，缘情（B）强调情感表达，比兴（C）是诗歌表现手法。","multi":false},{"no":16,"t":"“欲把西湖比西子，淡妆浓抹总相宜”体现的联想类型是","o":["接近联想","类似联想","关系联想","创造联想"],"a":[1],"exp":"将西湖（自然景观）与西子（美人）相比，二者在“美”的属性上相似，属于类似联想。接近联想（A）基于时空接近，关系联想（C）基于因果关系，创造联想（D）不是标准术语。","multi":false},{"no":17,"t":"审美感知体现了审美经验的","o":["超越性","直观性","非功利性","功利性"],"a":[1],"exp":"审美感知是对对象感性形象的直接把握，体现了审美经验的直观性。超越性（A）是深层体验，非功利性（C）是态度特征，功利性（D）与审美经验相悖。","multi":false},{"no":18,"t":"模仿说和表现说对艺术进行定义的角度是","o":["艺术的本质","艺术的起源","艺术的功能","艺术的存在"],"a":[0],"exp":"模仿说（艺术是对现实的模仿）和表现说（艺术是情感的表现）都是从“艺术的本质”角度界定艺术是什么。B（起源）如游戏说、劳动说，C（功能）如娱乐说，D（存在）如本体论。","multi":false},{"no":19,"t":"意象往往要借助于形式符号层的指示，才能在鉴赏者心中形成","o":["感性的表象","明确的逻辑","实存的物象","纯粹的判断"],"a":[0],"exp":"艺术品的形式符号层（色彩、线条、词语等）引导鉴赏者在心中生成感性的表象（即意象）。B（明确的逻辑）是理性认知，C（实存的物象）是客观实体，D（纯粹的判断）是康德术语。","multi":false},{"no":20,"t":"模仿说的合理性在于","o":["始终肯定人的主体因素","始终抓住艺术与现实世界的关系","始终注重艺术的情感因素","始终强调艺术的形式因素"],"a":[1],"exp":"模仿说的核心贡献在于始终强调艺术与现实世界的联系，为艺术找到了客观基础。其不足在于忽视了主体因素（A）和情感因素（C），形式因素（D）也不是模仿说关注的重点。","multi":false},{"no":21,"t":"提出“诗意是表现心灵状态的”这一命题的理论家是","o":["柏格森","克罗齐","叔本华","狄尔泰"],"a":[3],"exp":"狄尔泰是解释学美学家，提出“诗意是表现心灵状态的”，强调艺术是对生命体验的表达。柏格森（A）论直觉，克罗齐（B）主张“艺术即直觉”，叔本华（C）论意志与表象。","multi":false},{"no":22,"t":"在感性形态上与对象相似的意象类型是","o":["兴象","仿象","喻象","抽象"],"a":[1],"exp":"“仿象”是对客观物象的模仿，在感性形态上与对象具有相似性。兴象（A）触物起情，喻象（C）借喻表意，抽象（D）舍弃具象性，均不以相似性为特征。","multi":false},{"no":23,"t":"将艺术品分为语音层、语义层、图式层、客体层的理论家是","o":["布隆博格","英伽登","汉斯力克","海德格尔"],"a":[1],"exp":"英伽登在《文学的艺术作品》中将文学作品分为语音层、语义层、图式化观相层、客体层四个层次。布隆博格（A）是艺术史家，汉斯力克（C）论音乐，海德格尔（D）论存在与艺术。","multi":false},{"no":24,"t":"艺术接受的核心是","o":["意象的重建","意象的创造","内容的理解","形式的分析"],"a":[0],"exp":"艺术接受的核心是欣赏者依据作品符号，在自身经验基础上“重建”意象，而非被动接受或纯理性分析。意象的创造（B）属于艺术家，内容理解（C）和形式分析（D）是接受的部分环节。","multi":false},{"no":25,"t":"从历史上看，艺术天才是","o":["不存在的","客观存在的","与先天条件无关的","与后天实践无关的"],"a":[1],"exp":"艺术天才是客观存在的现象，既有先天禀赋也有后天修养。A（不存在）否认天才，C（与先天无关）和D（与后天无关）都片面。","multi":false},{"no":26,"t":"王国维把美育与德育、智育、体育并称为“四育”的著作是","o":["《论教育之宗旨》","《人间词话》","《〈红楼梦〉评论》","《宋元戏曲史》"],"a":[0],"exp":"王国维在《论教育之宗旨》中首次将美育与德、智、体并称“四育”。B是词学理论，C是红学论文，D是戏曲史著作，均非此文。","multi":false},{"no":27,"t":"率先把“美育”一词引入中国的学者是","o":["鲁迅","朱光潜","梁启超","蔡元培"],"a":[3],"exp":"蔡元培率先将“美育”一词引入中国并系统倡导。鲁迅（A）和梁启超（C）都论及美育但晚于蔡元培，朱光潜（B）是后来者。","multi":false},{"no":28,"t":"西方最早明确谈到审美教育的是","o":["柏拉图","亚里士多德","席勒","苏格拉底"],"a":[0],"exp":"柏拉图在《理想国》中最早明确论述审美教育，强调用高尚文艺作品陶冶青少年。亚里士多德（B）论悲剧净化，席勒（C）系统化美育理论，苏格拉底（D）无系统美育论述。","multi":false},{"no":29,"t":"贺拉斯在谈到文艺的功能时提出了","o":["“审美教育”的概念","“趣味教育”的概念","“人格教育”的概念","“寓教于乐”的原则"],"a":[3],"exp":"贺拉斯在《诗艺》中提出了“寓教于乐”的原则。A（审美教育）是席勒，B（趣味教育）是梁启超，C（人格教育）是蔡元培。","multi":false},{"no":30,"t":"车尔尼雪夫斯基认为“形象在美的领域中占着统治地位”，这说明美育的特点是","o":["诉诸感性","强制性","被动性","无目的性"],"a":[0],"exp":"车尔尼雪夫斯基强调美的形象性，说明美育通过感性形象来打动人，体现了“诉诸感性”的特点。强制性（B）和被动性（C）与美育相悖，无目的性（D）不准确。","multi":false},{"no":31,"t":"审美理想集中反映了主体的","o":["生理需要","艺术修养","审美趣味","人生修养","人生境界"],"a":[1,2,3,4],"exp":"审美理想集中反映主体的艺术修养（B）、审美趣味（C）、人生修养（D）和人生境界（E）。生理需要（A）属于本能层面，与审美理想无关。","multi":true},{"no":32,"t":"审美经验的超越性体现在","o":["精神世界对物质世界的超越","理想世界对现实世界的超越","超验世界对经验世界的超越","生活世界对艺术世界的超越","真实世界对虚拟世界的超越"],"a":[0,1,2],"exp":"审美经验的超越性表现为从物质到精神（A）、从现实到理想（B）、从经验到超验（C）的超越。D（生活超越艺术）和E（真实超越虚拟）不符合审美超越的方向。","multi":true},{"no":33,"t":"空间艺术主要包括","o":["建筑","雕塑","绘画","音乐","文学"],"a":[0,1,2],"exp":"空间艺术以空间存在方式呈现，包括建筑、雕塑、绘画。音乐（D）是时间艺术，文学（E）是语言艺术（兼具时间性）。","multi":true},{"no":34,"t":"先秦儒家的美育思想认为，审美活动主要是为了实现","o":["天人关系的和谐","人际关系的和谐","国家关系的和谐","民族关系的和谐","阶级关系的和谐"],"a":[0,1],"exp":"先秦儒家（如孔子）美育的核心目标是实现天人和谐（A）和人际和谐（B）。国家关系（C）、民族关系（D）、阶级关系（E）不是儒家美育的直接目的。","multi":true},{"no":35,"t":"下列关于亚里士多德的“净化说”理解正确的有","o":["悲剧具有净化作用","喜剧具有净化作用","净化与美育无关","净化是情感的陶冶","借助怜悯与恐惧可以使情感得以净化"],"a":[0,3,4],"exp":"亚里士多德认为悲剧（A）通过怜悯与恐惧（E）使情感得到净化（D），即情感的陶冶。喜剧（B）不是净化说的对象，净化与美育（C）密切相关而非无关。","multi":true}],"essay":[{"no":36,"t":"简述马克思实践概念的基本内涵。","ans":"（1）马克思的“实践”概念覆盖了人的全部社会生活，既包括最基础的物质生产活动，又包括政治活动、道德活动、艺术审美活动和其他种种精神生产活动，以及人们的日常生活活动。（2）马克思的实践概念是生成性的。感性个体的实践造成了个人的感性世界，人类总体的实践造成了人向人诞生和自然向人生成的历史行程和整个人类的生活世界。（3）在马克思那里，物质生产劳动是人最基础的实践活动，它最终决定着包括艺术、审美活动在内的精神生产活动和人的一切其他实践活动。","exp":"马克思的实践概念是全面的、动态的、以物质生产为基础的，它不仅是认识论的基石，更是存在论的基础，为理解审美活动的本质提供了哲学根据。","type":"简答"},{"no":37,"t":"简述审美形态的生成性特征。","ans":"审美形态的生成性有两方面的内涵：（1）一是指审美形态的历史生成。审美形态是在特定历史条件下形成的，随历史发展而演变。（2）二是指审美形态的个体相对性生成。审美形态在个体审美体验中具体生成，不同主体可能对同一形态有不同的感受和理解。","exp":"生成性揭示了审美形态不是固定不变的抽象范畴，而是在历史和个体两个维度中动态生成的，体现了审美形态的开放性和生命活力。","type":"简答"},{"no":38,"t":"简述“丑”成为特殊审美形态的原因。","ans":"（1）审美对象不是与现实世界相分裂的孤立对象，审美主体也不是一成不变的、抽象的、永恒的人，丑必然会与美一起进入审美实践之中。（2）人生境界也分层次，有高低，其中也包含丑的因素，在特定意义上，丑也可以显现为一种人生境界。（3）丑是人类异化劳动的感性存在状态和结果。（4）非理性主义、个人主义、实用主义、心理分析等哲学、美学思潮，都为丑走进审美领域奠定了思想基础。（5）艺术创作在一百多年间包含了大量对于丑的描绘和创造，呈现出了以丑代美的趋势，客观上为丑成为特殊审美形态奠定了现实基础。","exp":"丑之所以成为审美形态，是因为在审美实践中，丑被形式化和意义化后，能引发主体对生存的深刻反思，从否定性体验中获得精神启示。","type":"简答"},{"no":39,"t":"简述艺术品鉴赏过程的三个阶段。","ans":"（1）观。接受者透过艺术的形式符号在直观层次上初步感受和重建意象，在主体意识中形成不完整或粗浅的意象。（2）品。接受者根据各自的审美文化心理结构和经验，凝神观照，发挥想象力，细致地体味作品，充实、丰富、发展意象。（3）悟。主体对艺术品的意象品鉴渐入佳境后，终于升华为对意境的感悟，意识在一瞬间升华为高度自由的境界。","exp":"鉴赏是由浅入深的递进过程：观是感性接触，品是深入玩味，悟是精神升华，三者共同构成完整的接受体验。","type":"简答"},{"no":40,"t":"简述艺术意象的虚拟性。","ans":"（1）虚拟性是现实性的反面，意象一经物态化和物化进入艺术品中，便成为艺术意象，也就同时进入了非现实的层次。（2）意象可以“任意”地编造和虚构，有时甚至可以违背现实的常情常理。它可以表现现实世界所没有的、所不应有的、甚至不可能有的东西，不必是符合实存的现实。（3）即使表现现实中已有的或可能有的东西，也采取一种非现实的形态，意象的这种非现实性就是虚拟性。","exp":"虚拟性是艺术意象区别于现实物象的根本特征之一，它使艺术可以超越现实的限制，自由地创造审美世界。","type":"简答"},{"no":41,"t":"简述审美教育的主要内涵。","ans":"理解审美教育的内涵需要遵循三条原则：（1）手段与效果相一致的原则。（2）直接效果与间接效果兼顾的原则。（3）独特性原则。","exp":"审美教育的内涵不能简单理解为情感教育或人格教育，它应以审美体验为手段，以达到精神自由为目的，既要看到即时感受，也要看到长远影响，同时要区别于智育、德育，保持自身的独特性。","type":"简答"},{"no":42,"t":"论述审美情感在审美经验中对于审美想象的作用。","ans":"（1）审美情感是审美想象的原动力。情感驱动想象活动的展开，没有情感的内在推动，想象无法被激活。（2）情感不仅是审美想象的动力，而且在某种意义上也是审美想象的对象和内容。想象活动所创造的意象，往往承载和表达着特定的情感。（3）情感活动对审美想象的支配和调节，渗透在艺术形象的塑造和意境的营造之中，使想象有方向、有深度、有感染力。","exp":"审美经验中，情感与想象相互渗透、相互激发。情感为想象提供动力和素材，想象为情感提供形象和表达。例如，杜甫“感时花溅泪，恨别鸟惊心”中，忧国忧民的情感驱动想象，将花鸟意象赋予悲情色彩，情感与想象融为一体，共同构成深刻的审美体验。没有情感的想象是空洞的，没有想象的情感是抽象的，二者在审美经验中不可分割。","type":"论述"},{"no":43,"t":"苏珊·朗格说：“当你在欣赏舞蹈的时候，你并不是在观看眼前的物质物——往四处奔跑的人、扭动的身体等；你看到的是几种相互作用着的力。正是凭借这些力，舞蹈才显得上举、前进、退缩或减弱……演员所作的一切都是为了创造出一个能够使我们真实看到的东西，而我们实际看到的却是一种虚的实体。”试结合苏珊·朗格的这段话，分析说明审美对象的非实体性特征。","ans":"（1）一种舞蹈形象并不等于舞蹈演员本身，而是由舞蹈演员的身体动作、布景、灯光、音响等因素共同创造出来的一种幻象，这种幻象是作为一个浸透着情感的形象对我们起作用的，它引领我们到达一个蕴含丰富人生意义的独特境界，但是，它却并非由眼睛直接看到，而只能由审美主体（观众）的审美体验来具体地确认。（2）审美对象不仅不是一种物质实体，而且它也不是精神性的实体。它只是物质与精神、客观与主观相互渗透从而熔铸成的一种独特意象。","exp":"苏珊·朗格这段话揭示了审美对象的非实体性本质。审美对象不是物理实体的直接呈现，而是在审美活动中生成的“虚的实体”——它依赖物质载体（演员的身体、舞台等），但不等同于这些物质物；它存在于观众的审美体验中，而非客观空间中。例如，舞蹈《天鹅湖》中，观众看到的不是演员的肌肉和汗水，而是“天鹅”的优雅形象和情感律动，这个形象是物质、动作、音乐、灯光和观众想象共同建构的审美意象，既非纯物质也非纯精神，而是一种主客交融的非实体性存在。这正是审美对象区别于日常对象的根本特征。","type":"案例"}]},{"id":"2210","year":2022,"month":10,"label":"2022年10月","choice":[{"no":1,"t":"下列关于审美与自由的关系理解正确的是","o":["自由是进入审美的充分条件","自由是通向审美的根本途径","审美是实现自由的唯一途径","自由与审美无关"],"a":[1],"exp":"审美是人在自由状态下的精神活动，自由是通向审美的根本途径。A将自由说成“充分条件”过于绝对（自由不等于审美），C“唯一途径”是席勒观点但非普遍正确，D明显错误。","multi":false},{"no":2,"t":"下列关于马克思主义实践观的理解不正确的是","o":["社会实践包括生产劳动、阶级斗争和艺术活动等","实践具有生成性","实践是人的感性活动","精神生产是最基础的实践活动"],"a":[3],"exp":"马克思主义认为物质生产劳动是最基础的实践活动，精神生产建立在物质生产基础之上，因此D“精神生产是最基础的实践活动”错误。A、B、C均为马克思主义实践观的正确表述。","multi":false},{"no":3,"t":"“昔我往矣，杨柳依依。今我来思，雨雪霏霏。”这充分彰显了审美活动的","o":["感性特征","理性特征","价值特征","认识特征"],"a":[2],"exp":"此诗句以景写情，表达了离别与归来的深沉情感，体现了审美活动能满足人的精神需要、启迪人生感悟的价值特征。感性特征（A）是形式，理性（B）和认识（D）不全面。","multi":false},{"no":4,"t":"认为审美活动是性欲升华的一种基本途径的美学家是","o":["博克","达尔文","弗洛伊德","荣格"],"a":[2],"exp":"弗洛伊德从精神分析学出发，认为审美是性欲升华的途径之一。博克（A）论崇高与优美，达尔文（B）论生物本能，荣格（D）论集体无意识。","multi":false},{"no":5,"t":"“只有当人充分是人的时候，他才游戏；只有当人游戏的时候，他才是完全的人”，这一命题的提出者是","o":["康德","席勒","卢梭","马克思"],"a":[1],"exp":"此句出自席勒《审美教育书简》，将“游戏”视为人性实现的标志。康德（A）论游戏与自由但未出此语，卢梭（C）论自然教育，马克思（D）论劳动。","multi":false},{"no":6,"t":"对于欣赏者来说，“作品只在与他的能力相应的程度上存在”，这说明","o":["审美对象是现成给予的","审美对象是先于审美主体而存在的","审美对象是审美活动得以发生的前提","审美对象是在审美活动中生成的"],"a":[3],"exp":"此句出自杜夫海纳，强调审美对象不是在作品之外客观存在，而是在欣赏者的审美能力与之相遇的活动中生成的。A、B是客观主义观点，C颠倒关系。","multi":false},{"no":7,"t":"黑格尔认为，艺术意识产生于","o":["惊异","兴趣","欲望","实践"],"a":[0],"exp":"黑格尔认为艺术意识起源于“惊异”，即人对世界的惊奇和好奇，促使人们用艺术的方式把握世界。兴趣（B）、欲望（C）、实践（D）均非黑格尔所强调的起点。","multi":false},{"no":8,"t":"审美体验区别于一般生活体验的主要特点是","o":["整体性","功利性","目的性","零散性"],"a":[0],"exp":"审美体验是各种人生体验的浓缩、净化和升华，具有整体性，是对人生整体意义的领悟。功利性（B）和目的性（C）是一般生活体验的特征，零散性（D）与之相反。","multi":false},{"no":9,"t":"下列关于崇高内涵的理解不正确的是","o":["崇高是一种对立和冲突的审美体验","崇高的价值载体首先是体现冲突与抗争的艺术作品","崇高体现了伟大超越的人生境界","崇高和悲剧具有相同属性"],"a":[3],"exp":"崇高和悲剧虽然都涉及冲突和超越，但二者并非“相同属性”——崇高强调力量感与超越，悲剧强调毁灭与抗争中的价值肯定。A、B、C均为崇高的正确理解。","multi":false},{"no":10,"t":"喜剧的形式特征是","o":["不和谐","和谐","紧张","壮阔"],"a":[0],"exp":"喜剧通过不和谐、悖谬、错乱的形式表现可笑的内容，其形式特征是不和谐。和谐（B）是优美的特征，紧张（C）是悲剧或崇高的特征，壮阔（D）是崇高的特征。","multi":false},{"no":11,"t":"认为悲剧产生于日神精神与酒神精神的统一的美学家是","o":["亚里士多德","黑格尔","叔本华","尼采"],"a":[3],"exp":"尼采在《悲剧的诞生》中提出悲剧源于日神精神（理性、形式）与酒神精神（激情、生命）的统一。亚里士多德（A）论净化，黑格尔（B）论冲突，叔本华（C）论意志。","multi":false},{"no":12,"t":"雨果《巴黎圣母院》中的敲钟人卡西莫多这一形象所体现的审美形态是","o":["荒诞","优美","丑","中和"],"a":[2],"exp":"卡西莫多外形丑陋（驼背、独眼），但内心善良，其形象体现了“丑”的审美形态——在反常、不和谐中蕴含深层意义。荒诞（A）体现无意义，优美（B）体现和谐，中和（D）是儒家范畴。","multi":false},{"no":13,"t":"荒诞体现了人生的","o":["丰富性","和谐性","超越性","虚无性"],"a":[3],"exp":"荒诞是对人生存在无意义状态的体悟，体现了人生的虚无性。丰富性（A）和和谐性（B）是优美人生态度，超越性（C）是崇高和悲剧的特征。","multi":false},{"no":14,"t":"提出“蛇形线是最美的线条”的美学家是","o":["荷迦兹","博克","哈奇生","休谟"],"a":[0],"exp":"荷迦兹在《美的分析》中提出“蛇形线是最美的线条”，认为它富于变化和动感。博克（B）论崇高与优美，哈奇生（C）论内在感官，休谟（D）论趣味。","multi":false},{"no":15,"t":"西方美学史上强调审美经验的超验性的是","o":["古希腊美学","中世纪美学","经验主义美学","科学主义美学"],"a":[1],"exp":"中世纪美学将美与上帝相联系，强调审美经验的超验性（超越世俗、指向神圣）。古希腊（A）重和谐，经验主义（C）重感性，科学主义（D）重实证。","multi":false},{"no":16,"t":"主张把审美经验与生命体验联系起来的解释学美学家是","o":["施莱尔马赫","狄尔泰","海德格尔","伽达默尔"],"a":[1],"exp":"狄尔泰是解释学美学家，强调审美经验是“生命体验”的表达和理解。施莱尔马赫（A）是解释学先驱，海德格尔（C）和伽达默尔（D）也属解释学传统，但明确将审美经验与“生命体验”联系起来的是狄尔泰。","multi":false},{"no":17,"t":"审美活动中的象征现象主要体现了审美经验的","o":["直观性","超越性","功利性","非功利性"],"a":[1],"exp":"象征通过具体形象暗示更深层的精神意蕴，使审美经验超越感性表象，体现了超越性。直观性（A）是感知特征，功利性（C）和非功利性（D）是态度特征。","multi":false},{"no":18,"t":"中国古代美学中可归入表现说的是","o":["缘情说","畅神说","比德说","比兴说"],"a":[0],"exp":"“缘情说”主张艺术源于情感表达，属于表现说。畅神说（B）强调精神愉悦，比德说（C）强调道德比附，比兴说（D）是诗歌手法。","multi":false},{"no":19,"t":"艺术意象可以为主体感官直接把握，这体现出的艺术意象的特征是","o":["情感性","虚拟性","想象性","感性直观性"],"a":[3],"exp":"艺术意象可以被感官直接感知，这体现了它的“感性”或“感性直观性”特征。情感性（A）是内容，虚拟性（B）和想象性（C）是生成方式。","multi":false},{"no":20,"t":"艺术创作主体与接受主体之间的中介是","o":["创作经验","灵感","艺术品","创作技巧"],"a":[2],"exp":"艺术品是连接艺术创作主体和接受主体的中介与桥梁。创作经验（A）、灵感（B）、创作技巧（D）都是创作过程中的因素，而非中介。","multi":false},{"no":21,"t":"艺术品的核心是","o":["艺术体裁","艺术语言","艺术意象","艺术题材"],"a":[2],"exp":"艺术意象是艺术品的核心，它是审美价值的载体。艺术体裁（A）是形式类别，艺术语言（B）是媒介，艺术题材（D）是材料。","multi":false},{"no":22,"t":"构成艺术作品中的色彩、线条、音符、词语等属于","o":["意境超验层","意象世界层","物质实在层","形式符号层"],"a":[3],"exp":"色彩、线条、音符、词语等是艺术品的符号形式，属于形式符号层。物质实在层（C）是材质，意象世界层（B）是审美形象，意境超验层（A）是深层意蕴。","multi":false},{"no":23,"t":"创作主体孕育艺术意象的第一步是","o":["艺术敏感","艺术形式","艺术修养","艺术技巧"],"a":[0],"exp":"艺术敏感是艺术家感受和体验世界、孕育意象的基础与起点。艺术形式（B）是表达方式，艺术修养（C）和艺术技巧（D）是后续环节。","multi":false},{"no":24,"t":"恩格斯说，他从巴尔扎克的小说中得到的社会历史知识，比从历史学家那里得到的还要多。这体现了艺术的","o":["审美功能","娱乐功能","认识功能","道德教育功能"],"a":[2],"exp":"恩格斯的话说明艺术能提供社会历史知识，体现艺术的认识功能。审美功能（A）是核心功能，娱乐功能（B）和道德教育功能（D）均非此句所指。","multi":false},{"no":25,"t":"贝多芬的《命运》交响曲属于","o":["空间艺术","时间艺术","造型艺术","综合艺术"],"a":[1],"exp":"音乐以时间中的声音为媒介，属于时间艺术。空间艺术（A）如雕塑，造型艺术（C）如绘画，综合艺术（D）如戏剧。","multi":false},{"no":26,"t":"提出美育具有熏、浸、刺、提四种力的美学家是","o":["王国维","宗白华","梁启超","鲁迅"],"a":[2],"exp":"梁启超在《论小说与群治之关系》中提出美育的四种力：熏、浸、刺、提。王国维（A）、宗白华（B）、鲁迅（D）均无此概括。","multi":false},{"no":27,"t":"西方美育思想开端于","o":["古希腊","中世纪","古典主义时期","启蒙时期"],"a":[0],"exp":"西方美育思想始于古希腊，柏拉图最早明确谈到审美教育。中世纪（B）美育从属于神学，古典主义（C）和启蒙时期（D）是发展期。","multi":false},{"no":28,"t":"将美育等同于艺术教育，这种看法","o":["是对美育内涵的科学理解","准确看到了艺术在美育中的地位和作用","夸大了艺术在美育中的地位和作用","突出了美育的独立地位"],"a":[2],"exp":"美育不仅包括艺术教育，还包括自然美、社会美等领域。将美育等同于艺术教育，夸大了艺术的作用，忽视了美育更广阔的内涵。A、B、D均不正确。","multi":false},{"no":29,"t":"儒家认为美育的目的在于使人进入","o":["和谐境界","逍遥境界","虚无境界","宗教境界"],"a":[0],"exp":"儒家美育追求天人和谐、人际和谐的境界。逍遥境界（B）是道家的追求，虚无境界（C）是佛教或荒诞的体现，宗教境界（D）非儒家的核心目标。","multi":false},{"no":30,"t":"下列属于美育功能的是","o":["开发智力","化性起伪","强健体魄","启蒙思想"],"a":[1],"exp":"“化性起伪”（荀子）是美育的重要功能，即通过教化转化本性。开发智力（A）是智育，强健体魄（C）是体育，启蒙思想（D）虽有美育因素但非美育的核心功能。","multi":false},{"no":31,"t":"构成审美活动动力机制的主要因素有","o":["审美需要","审美趣味","审美理想","审美态度","审美距离"],"a":[0,1,2],"exp":"审美活动的动力机制由审美需要（动力来源）、审美趣味（导向偏好）、审美理想（最高尺度）构成。审美态度（D）和审美距离（E）是审美活动的前提条件，而非动力机制。","multi":true},{"no":32,"t":"划分审美形态的标准主要有","o":["普适性","统摄性","思想性","历史性","政治性"],"a":[0,1,3],"exp":"划分审美形态的标准包括普适性（广泛适用）、统摄性（集杂多于统一）、历史性（文化积淀和持久影响）。思想性（C）和政治性（E）不是划分审美形态的标准。","multi":true},{"no":33,"t":"康德的审美游戏论涉及到的审美经验的构成要素主要有","o":["评价","情感","想象","理智","判断"],"a":[2,3],"exp":"康德在审美游戏论中强调“想象”与“理智”（知性）的自由协调游戏。评价（A）是结果，情感（B）是心理体验但不是康德游戏论的核心构成要素，判断（E）是能力而非构成要素。","multi":true},{"no":34,"t":"美育的主要特点有","o":["诉诸感性","潜移默化","无目的性","诉诸理性","能动性"],"a":[0,1,4],"exp":"美育的特点是诉诸感性（A）、潜移默化（B）、能动性（E）。无目的性（C）是康德美学的概念，诉诸理性（D）是智育的特点。","multi":true},{"no":35,"t":"美育与德育的区别在于","o":["美育侧重于人的情感角度，德育侧重于意志角度","美育是动于心，德育则带有强制性","美育对人的感化使人亲和，德育则提出严肃的道德规范","美育是人格教育，德育是情感教育","美育是艺术教育，德育是趣味教育"],"a":[0,1,2],"exp":"美育与德育的区别：美育侧重情感、德育侧重意志（A）；美育动之于心，德育带有强制性（B）；美育使人亲和，德育提出严肃规范（C）。D和E将二者关系完全颠倒，错误。","multi":true}],"essay":[{"no":36,"t":"简述美学研究的核心方法。","ans":"（1）美学研究的核心方法是哲学方法。（2）审美活动是人类最高级、最复杂的一种精神活动，这决定了只能用哲学的方法而不能用科学和实验方法进行研究。（3）美学涉及到人生在世的深层本源问题，只有靠哲学方法才能掌握。","exp":"美学始终是哲学的重要分支，审美本质、价值、意义等问题无法通过实证方法解决，必须依靠哲学思辨、逻辑推演和理论建构来把握。","type":"简答"},{"no":37,"t":"简述审美活动作为价值活动的特殊性。","ans":"（1）审美活动所追求的不是一般的价值，而是能满足人的心灵需要的精神价值。（2）审美活动所追求的不是一般的精神价值，而是能帮助人领悟人生真谛，并激励人不断去创造人生意义的一种独特的精神价值。","exp":"审美价值区别于实用价值和道德价值，它直接作用于人的情感和精神世界，使人获得超越性的生命体验和意义领悟，具有不可替代的独特性。","type":"简答"},{"no":38,"t":"简述审美对象的开放性。","ans":"（1）所谓开放性是指审美对象具有不确定性和不可穷尽性。（2）审美对象是在事物由实向虚的转化中生成的，这就使对象摆脱了现实的羁绊，从而具有了一定的空灵性和开放性。","exp":"审美对象不是封闭固定的实体，其意蕴在不同时代、不同主体的审美活动中不断生成和延展，故具有无限的开放性和可阐释性。","type":"简答"},{"no":39,"t":"简述审美经验超越性的主要体现。","ans":"（1）审美经验能够实现从物质世界向精神世界的超越。（2）审美经验能够实现从现实世界向理想世界的超越。（3）审美经验能够实现从经验世界向超验世界的超越。","exp":"审美经验的超越性使人摆脱功利和现实的束缚，从感性上升到精神，从有限飞升到无限，从日常经验触及超验意义，这是审美经验区别于日常经验的核心特征。","type":"简答"},{"no":40,"t":"简述审美经验的动态过程。","ans":"（1）呈现阶段。审美主体从审美态度出发，通过感知使对象的特征在主体的意识中呈现出来。（2）构成阶段。审美主体通过想象与对象拉开一定的距离，并且形成关于对象的格式塔。（3）评价阶段。审美主体通过与对象的精神交流进行交感思考，并对对象的审美价值做出评价。","exp":"审美经验是动态发展的三阶段过程，从感知呈现、想象建构到情感评价，层层深入，最终完成完整的审美体验。","type":"简答"},{"no":41,"t":"简述席勒美育思想的重要性。","ans":"（1）从哲学的高度解释了审美教育的独特目的，把审美教育的目的和审美活动的性质内在地统一起来。（2）揭示了审美教育的价值是实现完满人性。（3）回答了走向完满人性的方式，揭示了人性统一的根据。","exp":"席勒将美育提高到哲学高度，认为它是克服现代人性分裂、实现自由的唯一途径，奠定了美育作为独立学科的理论基础，对后世美育思想影响深远。","type":"简答"},{"no":42,"t":"论述审美形态的二重性。","ans":"（1）审美形态的二重性指的是民族性与世界性。（2）审美形态的民族性体现在每个民族的审美形态都具有自己的特殊性，与其他民族大异其趣。（3）审美形态的世界性是指各民族的审美形态有许多相通之处。","exp":"审美形态既是民族的（在特定文化语境中形成，如中国“意境”、西方“崇高”），又是世界的（人类审美经验的共通性，如优美、悲剧等具有跨文化的普遍性）。民族性使审美形态丰富多彩，世界性使审美形态具有可交流性。二者不是对立的，而是辩证统一的：任何审美形态都从民族文化土壤中生长出来，同时又因触及人类共同的精神需求而具有世界意义。二重性是审美形态的基本属性，体现了审美活动的个体性与普遍性的统一。","type":"论述"},{"no":43,"t":"以下面这首诗为例，说明艺术意象的情感性。闻官军收河南河北杜甫剑外忽传收蓟北，初闻涕泪满衣裳。却看妻子愁何在，漫卷诗书喜欲狂。白日放歌须纵酒，青春作伴好还乡。即从巴峡穿巫峡，便下襄阳向洛阳。","ans":"（1）艺术意象的情感性形成于艺术家创作意象的过程中。（2）情感与“意”有密切联系，是艺术家创造意象的重要动力与导引，并伴随着意象创造的全过程。（3）艺术意象中总是渗透着某种形态的情感因素，使意象具有强烈的感染力。","exp":"杜甫此诗以“忽传收蓟北”的喜讯为触发，全诗意象都被“喜欲狂”的情感所贯穿和驱动。“涕泪满衣裳”是喜极而泣，“漫卷诗书”是动作意象，“放歌纵酒”是行为意象，“即从巴峡穿巫峡”是想象意象，这些意象并非客观写景，而是被强烈的情感（惊喜、兴奋、归乡渴望）所浸透和塑造。意象中的“意”正是杜甫听闻胜利后的复杂情感——既有国恨家仇的解除之喜，又有归乡的急切，这种情感使意象产生了极强的感染力和共鸣力。如果没有情感作为动力和灵魂，这些意象将只是干瘪的词汇组合。正是情感赋予了意象以生命和深度，使之成为千古传诵的审美结晶。","type":"案例"}]},{"id":"2304","year":2023,"month":4,"label":"2023年4月","choice":[{"no":1,"t":"柏拉图认为美学研究的对象是","o":["美的事物","美本身","美感","艺术"],"a":[1],"exp":"柏拉图在《大希庇阿斯篇》中提出“美本身”的问题，认为美学应研究超越具体美事物的“美的理念”（美本身）。美的事物（A）是现象层面，美感（C）是主体感受，艺术（D）是美的载体，均非柏拉图所强调的美学核心对象。","multi":false},{"no":2,"t":"审美关系从属于人与世界的","o":["反映关系","存在论关系","认识关系","实在论关系"],"a":[1],"exp":"审美关系是人与世界之间的自由、情感、感性直观的关系，从属于人与世界的“存在论关系”（即人在实践中与世界建立的整体性关系）。反映关系（A）和认识关系（C）是认识论的范畴，实在论关系（D）是哲学本体论的一种，均不准确。","multi":false},{"no":3,"t":"马克思认为影响主体审美趣味的主要因素是","o":["先天条件","家庭条件","个人条件","社会条件"],"a":[3],"exp":"马克思强调社会分工和教育等社会条件决定艺术家才能的发展，审美趣味的形成主要受社会条件制约。先天条件（A）、家庭条件（B）、个人条件（C）都有影响，但马克思强调的根本因素是社会的、历史的条件。","multi":false},{"no":4,"t":"席勒认为，在审美的国度里，每个人都是","o":["快乐的公民","自由的公民","富有的公民","闲适的公民"],"a":[1],"exp":"席勒在《审美教育书简》中认为，审美教育使人获得自由，在审美国度里人人都是“自由的公民”。快乐（A）、富有（C）、闲适（D）均非席勒的核心表述——他追求的是人性的完整和精神自由。","multi":false},{"no":5,"t":"“多样统一”这一形式规律最本质的特点是","o":["整齐一律","均衡对称","对比反差","和而不同"],"a":[3],"exp":"“多样统一”的本质是“和而不同”——在变化中保持统一，在统一中容纳变化。整齐一律（A）过于单调，均衡对称（B）是具体形式，对比反差（C）偏重差异，均不全面。","multi":false},{"no":6,"t":"认为动物也具有美感的是","o":["康德","卡西尔","达尔文","柏格森"],"a":[2],"exp":"达尔文从进化论角度认为动物（如鸟类）也具有对美的感受能力，这属于“生物本能说”。康德（A）强调人类审美判断的普遍性，卡西尔（B）论符号，柏格森（D）论直觉，均不认为动物有美感。","multi":false},{"no":7,"t":"广义的审美形态包括自然美、艺术美和","o":["人体美","工艺美","社会美","心灵美"],"a":[2],"exp":"广义审美形态包括自然美、艺术美和社会美三大类。人体美（A）和心灵美（D）属于社会美范畴，工艺美（B）属于艺术美范畴。","multi":false},{"no":8,"t":"审美形态的二重性是指民族性与","o":["地域性","时代性","阶级性","世界性"],"a":[3],"exp":"审美形态的二重性是指民族性与世界性的统一。地域性（A）包含于民族性，时代性（B）是历史性，阶级性（C）是意识形态属性，均非二重性的对应概念。","multi":false},{"no":9,"t":"最基本的两种审美形态是","o":["优美与崇高","悲剧与喜剧","丑与荒诞","崇高与滑稽"],"a":[0],"exp":"优美与崇高是最基本的两种审美形态，分别体现和谐与冲突、柔美与壮美两大类型。悲剧与喜剧（B）是戏剧类型，丑与荒诞（C）是现代形态，崇高与滑稽（D）不是并称的基本形态。","multi":false},{"no":10,"t":"博克认为崇高感源于人类的","o":["安全需要","社交需要","生殖需要","道德需要"],"a":[0],"exp":"博克在《论崇高与优美》中认为崇高源于自我保全的安全需要（面对恐怖对象的惊惧），优美源于社交需要。社交需要（B）对应优美，生殖需要（C）和道德需要（D）均非博克观点。","multi":false},{"no":11,"t":"古希腊悲剧属于","o":["性格悲剧","命运悲剧","社会悲剧","历史悲剧"],"a":[1],"exp":"古希腊悲剧（如索福克勒斯《俄狄浦斯王》）以主人公无法逃脱命运的安排为核心，属于“命运悲剧”。性格悲剧（A）如莎士比亚，社会悲剧（C）如易卜生，历史悲剧（D）是后来的分类。","multi":false},{"no":12,"t":"现代丑学的开端是","o":["卢梭的《忏悔录》","莱辛的《拉奥孔》","罗森克兰兹的《丑的美学》","克罗齐的《美学原理》"],"a":[2],"exp":"罗森克兰兹1853年出版《丑的美学》，首次系统研究丑，开启了现代丑学。卢梭（A）是文学作品，莱辛（B）论诗画界限，克罗齐（D）论直觉表现，均非丑学的开端。","multi":false},{"no":13,"t":"在古希腊的审美经验理论中，“净化说”的倡导者是","o":["巴门尼德","苏格拉底","柏拉图","亚里士多德"],"a":[3],"exp":"亚里士多德在《诗学》中提出悲剧的“净化”作用。巴门尼德（A）论存在，苏格拉底（B）论道德，柏拉图（C）否定悲剧，均非净化说的倡导者。","multi":false},{"no":14,"t":"英国经验主义美学所处的时代是","o":["古希腊","中世纪","近代","现代"],"a":[2],"exp":"英国经验主义美学（如夏夫兹博里、哈奇生、休谟、博克等）盛行于17-18世纪的近代。古希腊（A）和中世纪（B）早于经验主义，现代（D）晚于经验主义。","multi":false},{"no":15,"t":"中国古代美学中把自然物人格化的理论是","o":["畅神说","比德说","缘情说","童心说"],"a":[1],"exp":"“比德说”将自然物的形态特征与人的道德品格相比附，即把自然人格化。畅神说（A）强调精神愉悦，缘情说（C）强调情感表达，童心说（D）是李贽的文学理论。","multi":false},{"no":16,"t":"在审美感知中，主体与客体的关系是","o":["相互分离","相互对立","相互交融","互不相关"],"a":[2],"exp":"审美感知中主体与客体是相互交融、物我合一的，而非分离（A）、对立（B）或不相关（D）。审美感知本身就包含情感投入和主客互动。","multi":false},{"no":17,"t":"在审美经验的构成要素中，中国古代儒家美学重视的是","o":["感知","想象","情感","理解"],"a":[3],"exp":"儒家美学强调“以理节情”“以道制欲”，重视理性理解对情感的节制和引导，即理解这一要素。感知（A）是基础，想象（B）是道家更重视，情感（C）虽重要但须受理智约束。","multi":false},{"no":18,"t":"审美活动中最典型、最高级的形态是","o":["生产活动","娱乐活动","科学活动","艺术活动"],"a":[3],"exp":"艺术活动是审美活动中最典型、最高级的形态，因为它以创造和欣赏美为核心，集中体现了审美的自由性、创造性和精神性。生产活动（A）和科学活动（C）不是审美活动，娱乐活动（B）是审美活动的低层次体现。","multi":false},{"no":19,"t":"主张美学研究的对象是“美的艺术”的美学家是","o":["费希特","黑格尔","叔本华","尼采"],"a":[1],"exp":"黑格尔明确将美学定义为“美的艺术的哲学”，认为美学研究的对象是艺术。费希特（A）论知识学，叔本华（C）论意志，尼采（D）论悲剧，均不如此明确界定。","multi":false},{"no":20,"t":"苏珊·朗格所倡导的艺术观是","o":["游戏说","符号说","原型说","集体无意识说"],"a":[1],"exp":"苏珊·朗格提出“艺术是人类情感的符号形式的创造”，属于符号说。游戏说（A）是席勒、斯宾塞，原型说（C）和集体无意识说（D）是荣格。","multi":false},{"no":21,"t":"中国古代美学家韩愈主张","o":["文以载道","诗以言志","音由心生","诗缘情"],"a":[0],"exp":"韩愈是唐代古文运动领袖，主张“文以载道”，强调文章应承载儒家之道。诗以言志（B）是先秦儒家观点，音由心生（C）是《乐记》观点，诗缘情（D）是陆机观点。","multi":false},{"no":22,"t":"艺术活动开端于","o":["意象的产生","意境的营造","感官的触发","情感的抒发"],"a":[0],"exp":"艺术活动以意象的产生为开端——艺术家首先在心中形成审美意象，然后进行物态化表达。意境的营造（B）是高级阶段，感官触发（C）和情感抒发（D）都是意象产生的条件和内容。","multi":false},{"no":23,"t":"最重要的艺术创造力是","o":["认识能力","观察力","表达能力","想象力"],"a":[3],"exp":"想象力是意象生成的核心能力，是艺术创造中最具决定性的力量。认识能力（A）和观察力（B）是基础，表达能力（C）是物化阶段，想象力贯穿整个创造过程。","multi":false},{"no":24,"t":"在艺术接受的过程中，主体的精神升华到高度自由境界的阶段是","o":["观","感","品","悟"],"a":[3],"exp":"艺术接受的“悟”阶段是主体精神升华为高度自由境界的阶段。观（A）是初步感知，品（C）是深入体味，感（B）不是标准术语。","multi":false},{"no":25,"t":"审美是艺术的","o":["唯一功能","次要功能","核心功能","间接功能"],"a":[2],"exp":"审美是艺术的核心功能，艺术的认识、教育、娱乐等功能都需通过审美功能来实现。审美不是唯一功能（A，艺术有多元功能），也不是次要（B）或间接（D）功能。","multi":false},{"no":26,"t":"中国古代美育思想的源头可以追溯到","o":["先秦","两汉","魏晋","唐宋"],"a":[0],"exp":"中国古代美育思想源头在先秦，孔子提出“兴于诗，立于礼，成于乐”等美育思想。两汉（B）、魏晋（C）、唐宋（D）都是先秦之后的发展期。","multi":false},{"no":27,"t":"西方中世纪美学主张","o":["美育应服务于信仰","美育应服务于认知","美育应服务于政治","美育应服务于科学"],"a":[0],"exp":"中世纪美学是神学的婢女，美育服务于宗教信仰。认知（B）是智育，政治（C）是古希腊或近代，科学（D）是现代，均非中世纪特征。","multi":false},{"no":28,"t":"中国古代人性觉醒、个性发展的时代是","o":["夏商周时期","先秦时期","魏晋时期","唐宋时期"],"a":[2],"exp":"魏晋时期是人性觉醒、个性发展的时代，如“魏晋风度”中士人的自由精神和对个体价值的张扬。夏商周（A）和先秦（B）是奠基期，唐宋（D）是成熟期但以魏晋为转折。","multi":false},{"no":29,"t":"美育的主要特点之一是","o":["受动性","规范性","能动性","强制性"],"a":[2],"exp":"美育的特点是能动性（主体主动参与）、诉诸感性、潜移默化。受动性（A）和强制性（D）相反，规范性（B）是德育的特点。","multi":false},{"no":30,"t":"美育的根本价值取向是培养","o":["全面发展的人","道德高尚的人","理性的人","感性的人"],"a":[0],"exp":"美育的目标是培养全面发展的人——感性与理性和谐统一、个性和社会性协调发展。道德高尚（B）是德育目标，理性（C）是智育目标，感性（D）片面，不完整。","multi":false},{"no":31,"t":"对于欣赏者来说，“作品只在与他的能力相应的程度上存在”。这说明审美对象","o":["是一种精神实体","是先于审美活动而存在的","只存在于审美活动中","只存在于主体的主观经验中","是在审美活动中生成的"],"a":[2,4],"exp":"此句说明审美对象只存在于审美活动中（C），是在审美活动中生成的（E）。它不是精神实体（A），不是先于活动存在（B），也不只存在于主观经验（D）——它需要主客互动。","multi":true},{"no":32,"t":"审美经验具有非功利性的原因在于","o":["与对象的实际存在相关","与对象的实际存在无关","与主体的物质需要相关","与主体的物质需要无关","与主体的认知需要相关"],"a":[1,3],"exp":"审美经验的非功利性表现为：与对象实际存在无关（B），与主体的物质需要无关（D）。A和C与功利性相关，E（认知需要）是认识活动而非审美活动的特征。","multi":true},{"no":33,"t":"下列关于艺术存在方式的表述正确的有","o":["艺术首先存在于意象世界中","艺术只能存在于人的审美活动中","艺术存在于艺术创造——艺术品——艺术接受的动态流程中","艺术只存在于艺术家的创作活动中","艺术只存在于读者的接受活动中"],"a":[0,1,2],"exp":"艺术存在于意象世界（A）、人的审美活动（B）以及创造—作品—接受的动态流程（C）中。D和E都只强调了一个环节，不完整。","multi":true},{"no":34,"t":"蔡元培的“美育代宗教说”主张","o":["美育是自由的，宗教是强制的","美育是进步的，宗教是保守的","美育是普及的，宗教是有界的","美育是趣味教育，宗教是道德教育","美育是感化教育，宗教是情感教育"],"a":[0,1,2],"exp":"蔡元培认为美育是自由的、进步的、普及的；宗教是强制的、保守的、有界的。D（趣味教育是梁启超）和E（感化教育）不是蔡元培“美育代宗教说”的内容。","multi":true},{"no":35,"t":"席勒美育思想的理论贡献有","o":["从哲学高度解释了美育的目的","把美育的价值界定为完善人性","提出了“寓教于乐”的主张","认为美育就是道德教育","回答了完满人性的方式"],"a":[0,1,4],"exp":"席勒的贡献包括从哲学高度解释美育目的（A）、将美育价值界定为完善人性（B）、回答完满人性的方式（E）。C（寓教于乐）是贺拉斯，D（美育就是道德教育）不是席勒观点——席勒认为美育是完善人性的独特途径，不等同于德育。","multi":true}],"essay":[{"no":36,"t":"简述美学学科的建立过程。","ans":"（1）美学学科的建立经过了从审美意识，到美学思想，再到美学学科的过程。（2）美学作为一门独立学科的形成以鲍姆嘉通1750年出版的《美学》一书为标志。","exp":"人类先有朦胧的审美意识（原始社会），然后发展出系统的美学思想（古希腊至近代），最后在18世纪由鲍姆嘉通确立为独立学科，这是美学学科建立的历史逻辑。","type":"简答"},{"no":37,"t":"简述亚里士多德的悲剧观。","ans":"（1）悲剧是对于一个严肃、完整、有一定长度的行动的模仿。（2）悲剧能够引起人们的恐惧与怜悯，使人们的灵魂得到净化和陶冶。","exp":"亚里士多德在《诗学》中第一次为悲剧做出完整定义，强调悲剧模仿严肃的行动，并通过恐惧与怜悯实现情感净化，奠定了西方悲剧理论的基础。","type":"简答"},{"no":38,"t":"简述优美与美的关系。","ans":"（1）广义的美包括各种审美形态，狭义的美是指优美。（2）优美是美最一般的形态。","exp":"在美学中，“美”有广狭二义。广义的美涵盖优美、崇高、悲剧、喜剧、丑、荒诞等所有审美形态；狭义的美特指优美——即和谐、宁静、柔顺的审美形态，是美最典型、最普遍的表现。","type":"简答"},{"no":39,"t":"简述艺术模仿说的主要缺陷。","ans":"（1）把艺术的本质局限于认识活动，忽视了艺术的审美特征。（2）忽视了艺术活动的主体性和表现性，未能全面揭示艺术的本质。","exp":"模仿说强调艺术对现实的再现，但艺术不仅是认识，更是情感表达和创造；模仿说忽略了艺术家主体的能动性，也未能解释艺术形式的独立审美价值。","type":"简答"},{"no":40,"t":"简述艺术想象力的特点。","ans":"（1）艺术想象力是指艺术家孕育艺术意象的主要能力。（2）艺术想象力不同于日常的逻辑思维能力，它不运用抽象的概念和推理。（3）艺术想象力可以创造出独特的心理时空，整合心理意象，创造出新的艺术意象。","exp":"艺术想象力是创造性的、情感驱动的、突破时空限制的，它与逻辑思维不同，是艺术创造中最核心的心理能力。","type":"简答"},{"no":41,"t":"简述马克思的美育思想。","ans":"（1）马克思美育思想的出发点是对异化现实的批判。（2）马克思认为美育的基本任务是培养全面发展的人。","exp":"马克思从资本主义异化出发，认为美育的目标是克服人的片面发展，通过审美和艺术实践，恢复人的丰富性和完整性，培养感性与理性和谐统一的全面发展的人。","type":"简答"},{"no":42,"t":"论审美对象在审美经验中得以呈现的主体条件。","ans":"（1）主体需要摆脱日常的功利和实用态度，采取观照、欣赏的态度，才能与对象建立审美关系。（2）主体不仅借助于感觉器官，还必须借助于整个身心，才能充分把握审美对象。","exp":"审美对象的呈现不是客观给予的，而是依赖主体的审美态度——只有悬置功利计较，以“无所为”的心态投入观照，对象才转化为审美对象。同时，审美感知不是纯感官的，而是身心合一、情感参与的完整体验，需要主体调动全部生命经验才能深入把握对象的意蕴。这两个条件是审美活动发生和审美对象显现的主观基础。","type":"论述"},{"no":43,"t":"老一辈无产阶级革命家习仲勋曾经说过，他在青年时代阅读了左翼作家蒋光慈的小说《少年漂泊者》之后，深受感动，产生了强烈的共鸣，激励他下定决心走上了革命道路。请结合上述事例，说明审美理想对于人生实践的作用。","ans":"（1）审美理想是人生修养的重要组成部分，因此能够使审美活动在人生实践中发挥重要作用。（2）艺术作品能够对人的精神产生巨大的感染力，从而给读者的人生理想和生活道路带来巨大的影响和变化。","exp":"蒋光慈《少年漂泊者》通过艺术意象和情感表达，展现了被压迫青年的抗争精神和革命理想，深深打动了青年习仲勋。这部作品不仅是艺术欣赏的对象，更承载了特定的审美理想（对正义、解放的追求），这种审美理想通过情感共鸣转化为人生理想，激励他投身革命实践。这一事例说明，审美理想不是脱离现实的空想，而是通过审美体验内化为人的精神力量，进而影响其人生选择和实践活动。审美活动通过情感染人，使人在美的熏陶中坚定信念、提升境界，最终在实践中实现人生价值。","type":"案例"}]},{"id":"2310","year":2023,"month":10,"label":"2023年10月","choice":[{"no":1,"t":"主张美学的研究对象是审美关系的美学家是","o":["朱光潜","蔡元培","蒋孔阳","宗白华"],"a":[2],"exp":"蒋孔阳在《美学新论》中明确提出“美学的根本问题是研究人对现实的审美关系”。朱光潜（A）主张美学研究艺术，蔡元培（B）倡导美育，宗白华（D）研究意境与中国美学，均不属此。","multi":false},{"no":2,"t":"美学学科的诞生","o":["以柏拉图的《理想国》为标志","以亚里士多德的《诗学》为标志","以鲍姆嘉通的《美学》为标志","以黑格尔的《美学》为标志"],"a":[2],"exp":"美学作为独立学科诞生的标志是鲍姆嘉通1750年出版《美学》一书。柏拉图《理想国》（A）和亚里士多德《诗学》（B）是美学思想源头，黑格尔《美学》（D）是体系化著作但晚于鲍姆嘉通。","multi":false},{"no":3,"t":"“忧心忡忡的穷人甚至对最美丽的景色都无动于衷”，这说明审美活动","o":["没有直接的功利性","具有直接的功利性","没有间接的功利性","具有强烈的功利性"],"a":[0],"exp":"马克思这句话说明审美活动需要主体摆脱功利羁绊——穷人因生存压力无法进入审美状态，反证审美活动本身没有直接的功利性。B、D与题意相反，C不准确（审美有间接功利）。","multi":false},{"no":4,"t":"马克思认为，一般美感中最大众化的形式是","o":["形体的感觉","线条的感觉","色彩的感觉","声音的感觉"],"a":[2],"exp":"马克思认为色彩感觉是一般美感中最大众化的形式，因为色彩最直观、最普遍地为人们所感知。形体（A）、线条（B）、声音（D）均不如色彩具有大众化特征。","multi":false},{"no":5,"t":"审美活动得以发生的基本前提是","o":["生物本能","游戏冲动","物质生产","艺术活动"],"a":[2],"exp":"物质生产劳动是人类最基本的实践活动，是审美活动发生的基本前提。生物本能（A）和游戏冲动（B）是审美发生理论但非基本前提，艺术活动（D）是审美活动的高级形态。","multi":false},{"no":6,"t":"我国的史前绘画最早见于","o":["旧石器时代","新石器时代","青铜时代","铁器时代"],"a":[1],"exp":"我国史前绘画最早见于新石器时代的彩陶纹饰和岩画。旧石器时代（A）我国尚未发现明确绘画遗存，青铜时代（C）和铁器时代（D）晚于新石器时代。","multi":false},{"no":7,"t":"对审美对象进行归类与描述的是","o":["审美风格","审美形态","审美趣味","审美理念"],"a":[1],"exp":"审美形态是对审美对象进行逻辑归类和理性描述的范畴体系，如优美、崇高、悲剧等。审美风格（A）是艺术作品风格，审美趣味（C）是主体偏好，审美理念（D）是哲学概念。","multi":false},{"no":8,"t":"下列诗句中体现了崇高风格的是","o":["明月松间照","细雨鱼儿出","大江流日夜","池塘生春草"],"a":[2],"exp":"“大江流日夜”以浩荡奔流的江水和日夜不停的时空意象，体现壮阔宏大的崇高风格。A（王维）和B（杜甫）表现优美宁静，D（谢灵运）表现清新自然。","multi":false},{"no":9,"t":"能够唤起轻松愉悦的感受的审美形态是","o":["悲剧","荒诞","优美","壮美"],"a":[2],"exp":"优美以和谐、宁静、柔顺为特征，能唤起轻松愉悦的感受。悲剧（A）唤起怜悯与恐惧，荒诞（B）唤起虚无感，壮美（D）唤起震撼与敬畏。","multi":false},{"no":10,"t":"构成悲剧内涵的三个核心因素是","o":["冲突、抗争与和解","冲突、抗争与毁灭","冲突、抗争与解放","冲突、抗争与自由"],"a":[1],"exp":"悲剧的核心要素是冲突（社会、命运或内心）、抗争（主人公的奋斗）与毁灭（有价值事物的损失）。和解（A）、解放（C）、自由（D）均非悲剧的必然要素。","multi":false},{"no":11,"t":"喜剧的情感载体是","o":["笑","怒","哀","怨"],"a":[0],"exp":"喜剧的基本情感载体是“笑”——包括讽刺的笑、幽默的笑。怒（B）、哀（C）、怨（D）均非喜剧的主要情感载体。","multi":false},{"no":12,"t":"丑不是一种","o":["人类学范畴","社会学范畴","美学范畴","政治学范畴"],"a":[3],"exp":"丑首先是一种美学范畴（C），也是人类学（A）和社会学（B）的研究对象，但不是政治学范畴（D）。政治学研究权力与治理，不研究丑的本质。","multi":false},{"no":13,"t":"主张运用科学方法来研究审美经验的美学家是","o":["桑塔亚那","托马斯·门罗","杜威","苏珊·朗格"],"a":[1],"exp":"托马斯·门罗是科学主义美学的代表，主张用科学实证方法研究审美经验。桑塔亚那（A）是自然主义，杜威（C）是实用主义，苏珊·朗格（D）是符号学。","multi":false},{"no":14,"t":"奥古斯丁的审美经验理论属于","o":["实验美学","心理学美学","科学美学","神学美学"],"a":[3],"exp":"奥古斯丁是中世纪教父哲学家，其美学思想以神学为基础，认为美来自上帝，属于神学美学。实验美学（A）、心理学美学（B）、科学美学（C）均为现代美学流派。","multi":false},{"no":15,"t":"在审美经验的各个领域中，与道德活动关系最为密切的是","o":["艺术","社会","自然","科学"],"a":[1],"exp":"社会美（社会领域的审美）与道德活动关系最为密切，因为社会现象常涉及善恶评价。艺术（A）也涉及道德但不如社会直接，自然（C）和科学（D）与道德关系较远。","multi":false},{"no":16,"t":"康德认为，审美判断是","o":["从普遍出发寻找特殊","从感性出发寻找理性","从理性出发寻找感性","从特殊出发寻找普遍"],"a":[3],"exp":"康德认为审美判断是“反思判断”，从特殊（具体的审美感受）出发寻找普遍（美的共通感），而非从普遍概念出发演绎。A是规定判断的特征。","multi":false},{"no":17,"t":"把审美情感归结为主客体之间的同构对应关系的美学流派是","o":["经验主义美学","行为主义美学","精神分析美学","格式塔心理学美学"],"a":[3],"exp":"格式塔心理学美学认为审美情感源于主客体之间在力的结构上的同构对应关系（如“力的图式”）。经验主义（A）强调感官，行为主义（B）忽视内在，精神分析（C）强调无意识。","multi":false},{"no":18,"t":"在审美经验的构成要素中，处于基础层面的是","o":["感知","想象","情感","理解"],"a":[0],"exp":"感知是审美经验的起点和基础，没有感知就无法获得审美对象的感性材料。想象（B）、情感（C）、理解（D）都在感知基础上展开。","multi":false},{"no":19,"t":"布洛认为，获得审美愉悦的前提是主体与对象","o":["融为一体","保持距离","相互对立","互不相关"],"a":[1],"exp":"布洛的“心理距离说”认为审美愉悦的前提是主体与对象保持适度的心理距离，既不过近（功利）也不过远（冷漠）。融为一体（A）是体验结果而非前提，对立（C）和不相关（D）均不正确。","multi":false},{"no":20,"t":"“美的艺术”这一概念最早出现于","o":["古希腊","古罗马","中世纪","近代"],"a":[3],"exp":"“美的艺术”（fine arts）概念在18世纪近代才明确形成，将艺术与技艺区分，强调艺术的审美目的。古希腊（A）和古罗马（B）时期艺术与技艺未分化，中世纪（C）艺术服务于宗教。","multi":false},{"no":21,"t":"所有艺术品都包含","o":["情节","人物","意象","象征"],"a":[2],"exp":"意象是艺术品不可或缺的核心要素。情节（A）和人物（B）只存在于叙事艺术中，象征（D）是部分艺术品的特征。","multi":false},{"no":22,"t":"提出灵感是一种迷狂现象的美学家是","o":["泰勒斯","德谟克利特","赫拉克利特","柏拉图"],"a":[3],"exp":"柏拉图在“迷狂说”中提出灵感是神灵凭附的迷狂状态。泰勒斯（A）是自然哲学家，德谟克利特（B）也论灵感但非“迷狂”，赫拉克利特（C）论万物流动。","multi":false},{"no":23,"t":"主体通过模仿对象世界创造出来的意象是","o":["仿象","兴象","喻象","抽象"],"a":[0],"exp":"仿象是对客观物象的模仿性再现，与对象具有相似性。兴象（B）触物起情，喻象（C）借喻表意，抽象（D）舍弃具象。","multi":false},{"no":24,"t":"艺术接受者重建的意象","o":["与创造者所创造的意象完全相同","受艺术符号的暗示与引导","可以完全脱离作品中的意象","与艺术家创造的意象毫无关系"],"a":[1],"exp":"接受者重建的意象受到艺术品中艺术符号的暗示与引导，而非完全自由（C、D）或完全相同（A）。接受者是在作品提供的框架内进行意象重建。","multi":false},{"no":25,"t":"将艺术划分为象征型、古典型与浪漫型三种形态的美学家是","o":["黑格尔","索绪尔","贝尔","笛卡尔"],"a":[0],"exp":"黑格尔按理念与形式的关系将艺术分为象征型、古典型、浪漫型三种形态。索绪尔（B）是语言学家，贝尔（C）提出“有意味的形式”，笛卡尔（D）是哲学家。","multi":false},{"no":26,"t":"我国先秦时期的美育思想一般蕴含于","o":["宗教思想","乐教思想","礼教思想","政教思想"],"a":[1],"exp":"先秦美育思想主要蕴含于“乐教”之中，如《乐记》和孔子“成于乐”的思想。宗教（A）在先秦不占主导，礼教（C）侧重于规范，政教（D）侧重政治。","multi":false},{"no":27,"t":"我国春秋战国时期的美育理想是","o":["和","乐","美","礼"],"a":[0],"exp":"春秋战国时期美育的核心理想是“和”——天人和谐、人际和谐。“乐”是手段，“礼”是规范，“美”是对象，均非理想本身。","multi":false},{"no":28,"t":"贺拉斯的“寓教于乐说”主张","o":["智育与德育相统一","教育与音乐相统一","美育与体育相统一","美育与德育相统一"],"a":[3],"exp":"贺拉斯“寓教于乐”强调美育（通过审美愉悦）与德育（实现教化目的）的统一。A是智育与德育，B是教育与音乐，C是美育与体育，均不准确。","multi":false},{"no":29,"t":"下列艺术形式中最能体现我国明清时期美育思想的是","o":["小说","散文","音乐","建筑"],"a":[0],"exp":"明清时期小说繁荣，如《红楼梦》《三国演义》等具有深刻的美育功能，体现了这一时期的美育思想。散文（B）、音乐（C）、建筑（D）均不如小说具有代表性。","multi":false},{"no":30,"t":"西方美育思想开端于","o":["古希腊罗马","中世纪","文艺复兴","启蒙运动"],"a":[0],"exp":"西方美育思想开端于古希腊罗马时期，柏拉图最早明确谈到审美教育。中世纪（B）美育从属神学，文艺复兴（C）和启蒙运动（D）是发展期。","multi":false},{"no":31,"t":"唯物主义美学认为","o":["美是主观的","美是客观的","美由美感决定","美不是由美感决定","美就是美感"],"a":[1,3],"exp":"唯物主义美学认为美是客观的（B），美不是由美感决定的（D）。A（美是主观的）、C（美由美感决定）、E（美就是美感）均属唯心主义美学观点。","multi":true},{"no":32,"t":"审美经验的直观性表现为","o":["生动性","具体性","直接性","抽象性","间接性"],"a":[0,1,2],"exp":"审美经验的直观性表现为生动性（形象鲜活）、具体性（感性具体）、直接性（无需推理）。抽象性（D）和间接性（E）与直观性相反。","multi":true},{"no":33,"t":"苏珊·朗格主张","o":["艺术是人类情感的符号形式","艺术符号是一种非逻辑抽象的符号","艺术符号所表现的是个人瞬间的情绪","艺术符号表现的是人类的普遍情感","艺术符号能展示人的“生命形式”"],"a":[0,1,3,4],"exp":"苏珊·朗格认为艺术是人类情感的符号形式（A），是非逻辑抽象的符号（B），表现人类普遍情感（D），能展示“生命形式”（E）。C（个人瞬间情绪）不符合——朗格强调普遍性而非个人瞬间。","multi":true},{"no":34,"t":"先秦儒家美学典籍《乐记》主张，审美活动能实现","o":["天人关系的和谐","人际关系的和谐","政治关系的和谐","宗教关系的和谐","人神关系的和谐"],"a":[0,1],"exp":"《乐记》认为审美活动（乐）能实现天人和谐（A）和人际和谐（B）。政治关系（C）、宗教关系（D）、人神关系（E）均非《乐记》核心论述。","multi":true},{"no":35,"t":"席勒的《审美教育书简》","o":["是第一部系统的美育著作","第一次提出“审美教育”这一概念","标志着美育作为一门独立学科的出现","系统论述了美育的性质、特征与社会作用","提出了“净化说”"],"a":[0,1,2,3],"exp":"席勒《审美教育书简》是第一部系统美育著作（A），首次提出“审美教育”概念（B），标志着美育作为独立学科出现（C），系统论述美育（D）。E（净化说）是亚里士多德提出的，非席勒。","multi":true}],"essay":[{"no":36,"t":"简述美学研究方法的多元性。","ans":"（1）美学是一门综合性的人文学科，它的研究方法应当是多样的、综合的。（2）美学研究具体的审美现象，审美现象是多样的复杂的。（3）美学研究需要广泛吸收其它人文学科以及自然科学、社会科学的方法。","exp":"审美现象的复杂性决定了研究方法不能单一，美学的综合性要求哲学思辨、心理学分析、社会学考察等多方法并用，形成多元互补的研究格局。","type":"简答"},{"no":37,"t":"简述审美趣味的特征。","ans":"（1）审美趣味具有鲜明的个性特征。（2）影响主体审美趣味的主要因素是其所面临的后天因素或社会条件，因此，审美趣味又必然具有一定的社会性。","exp":"审美趣味既有个人偏好（个性），又受社会文化影响（社会性），二者构成其基本特征。趣味既有独特性，也有可评判的高下之分。","type":"简答"},{"no":38,"t":"简述马克思恩格斯的悲剧观。","ans":"（1）悲剧产生于历史的必然要求和这个要求实际上不可能实现之间的冲突。（2）悲剧冲突是历史的冲突和社会的冲突。","exp":"马克思主义悲剧观将悲剧从个人命运提升到历史社会层面，认为悲剧是历史发展的必然性与现实条件的局限性之间的矛盾，具有深刻的社会历史内涵。","type":"简答"},{"no":39,"t":"简述荒诞成为特殊审美形态的原因。","ans":"（1）以特殊的实践方式显示其特殊存在价值。（2）拉近了审美实践与人生实践的距离。（3）揭示了西方理性主义的成果。","exp":"荒诞通过否定性体验揭示人生的无意义状态，使审美实践直接切入人生现实，打破了理性主义的乐观幻想，成为现代人对自身处境的审美反思。","type":"简答"},{"no":40,"t":"简述审美经验呈现阶段的主客体关系。","ans":"（1）主体必须采取一种非功利的态度，才能与客体之间建立审美关系。（2）主体进入审美状态之后，就与客体处于水乳交融、密不可分的关系之中。","exp":"呈现阶段主体搁置功利，以审美态度观照对象，主客之间不是认识关系而是交融关系，对象在主体意识中呈现为审美对象。","type":"简答"},{"no":41,"t":"简述亚里士多德的美育思想。","ans":"（1）美育具有净化功能。（2）审美功能应与教育功能有机统一。（3）美育不同于道德教育。","exp":"亚里士多德提出悲剧的“净化说”，认为艺术通过情感宣泄实现教育功能，但美育不是直接的道德说教，而是通过审美愉悦实现教化，与德育有区别。","type":"简答"},{"no":42,"t":"试论审美体验与一般生活体验的联系与区别。","ans":"（1）主体越是具有丰富的生活体验，就越有可能获得丰富的审美体验。（2）生活体验是零碎、分散的，带有功利目的；审美体验具有整体性，摆脱了功利目的的羁绊。","exp":"审美体验不是凭空产生的，它以一般生活体验为基础和素材。但审美体验不是生活体验的简单堆积，而是对生活体验的浓缩、净化和升华——从零碎走向整体，从功利走向非功利，从日常走向诗意。例如，杜甫“安得广厦千万间”源自其颠沛流离的生活体验，但通过审美转化，升华出悲天悯人、超越个人的精神境界。","type":"论述"},{"no":43,"t":"郑板桥说“江馆清秋，晨起看竹，烟光日影霜气皆浮动于疏枝密叶之间。胸中勃勃遂有画意。其实胸中之竹，并非眼中之竹也。因而磨墨展纸，落笔倏作变相，手中之竹又不是胸中之竹也。”请结合这段话，谈谈你对艺术创造过程的理解。","ans":"（1）这段话揭示了艺术意象的孕育和生成过程。（2）艺术意象孕育的起点，是主体与客体的相遇。（3）艺术家必须用特定的形式符号把胸中孕育的意象凝定下来，才能完成艺术创作。","exp":"郑板桥提出“眼中之竹→胸中之竹→手中之竹”三阶段：眼中之竹是客观感知（感官接触），胸中之竹是意象生成（情感加工、想象创造），手中之竹是意象物化（技巧表达）。眼中之竹是自然物象，胸中之竹是审美意象（已有主观改造），手中之竹是艺术品（技巧操作进一步加工）。这表明艺术创造不是简单模仿，而是感知—想象—表达层层递进、不断转化的创造性过程，艺术意象在主客交融中生成，在技巧操作中凝定。","type":"案例"}]},{"id":"2404","year":2024,"month":4,"label":"2024年4月","choice":[{"no":1,"t":"鲍姆嘉通创立美学的哲学基础是","o":["辩证唯物主义哲学","精神分析哲学","理性主义哲学","经验主义哲学"],"a":[2],"exp":"鲍姆嘉通是理性主义哲学家沃尔夫的学生，他在理性主义哲学框架内提出“感性认识的科学”——美学，以弥补理性认识体系的不足。辩证唯物主义（A）是马克思主义哲学，精神分析（B）是弗洛伊德，经验主义（D）是英国哲学传统。","multi":false},{"no":2,"t":"美学的研究方法是","o":["单一的、抽象的","感知的、逻辑的","多样的、综合的","历史的、体验的"],"a":[2],"exp":"美学作为综合性人文学科，研究方法应当是多样的、综合的——既有哲学思辨，也有心理学、社会学等方法。A过于狭隘，B和D虽涉及部分方法但不够全面。","multi":false},{"no":3,"t":"在审美活动中审美主体所看重的是对象的","o":["精神意义","实际用途","感性意义","实践意义"],"a":[0],"exp":"审美活动中，主体超越实用和感性层面，看重对象的精神意义（情感价值、人生意味）。实际用途（B）是功利态度，感性意义（C）是形式层面，实践意义（D）是实用层面。","multi":false},{"no":4,"t":"与一般的生活体验不同，审美体验","o":["常常着眼于局部利益","具有整体性和根本性","总是分散的、零碎的","是种种人生经验的总和"],"a":[1],"exp":"审美体验将各种生活经验浓缩、升华，具有整体性和根本性——把握人生的整体价值和根本意义。A和C是一般生活体验的特征，D（总和）不准确，审美体验不是简单相加。","multi":false},{"no":5,"t":"审美对象的物质因素主要是指构成具体事物的","o":["社会属性","理性属性","实践属性","感性属性"],"a":[3],"exp":"审美对象的物质因素是指可被感知的感性属性（色彩、线条、形状、音响等）。社会属性（A）是关系属性，理性属性（B）是思维属性，实践属性（C）是活动属性。","multi":false},{"no":6,"t":"最初与人类审美活动紧密联系在一起的是","o":["游戏活动","巫术活动","使用工具的活动","制造生产工具的活动"],"a":[3],"exp":"制造生产工具的物质生产劳动是人类最基本的实践活动，是审美活动发生的最初基础。游戏（A）和巫术（B）是审美发生的相关理论但晚于生产劳动，使用工具（C）包含于制造工具。","multi":false},{"no":7,"t":"审美形态是多种因素的统一，其中核心的因素是","o":["审美情趣","人生境界","审美风格","天地境界"],"a":[1],"exp":"审美形态的核心是人生境界——不同的审美形态（优美、崇高、悲剧等）体现了不同的人生境界状态。审美情趣（A）和审美风格（C）是具体表现，天地境界（D）是最高境界之一。","multi":false},{"no":8,"t":"康德认为，崇高给人带来的是","o":["积极的快乐","消极的快乐","游戏的快乐","想象的快乐"],"a":[1],"exp":"康德认为崇高先引起生命力的阻碍（不快），然后产生更强烈的生命力的爆发（快感），因此是“消极的快乐”。优美才带来“积极的快乐”（A），游戏（C）和想象（D）不是康德的分类。","multi":false},{"no":9,"t":"下列关于荒诞的表述中不正确的是","o":["荒诞是一种现代审美形态","荒诞是人的异化与局限性的表现","荒诞是对人生存在的无意义状态的体悟","从内容看，荒诞更接近于喜剧"],"a":[3],"exp":"荒诞虽然在形式上有怪诞、可笑之处，但从内容看更接近于“悲”——它揭示的是非理性、虚无和存在的困境。A、B、C均为荒诞的正确表述。","multi":false},{"no":10,"t":"“明月松间照，清泉石上流”所体现的审美形态是","o":["自然","含蓄","壮美","优美"],"a":[3],"exp":"王维此诗描绘的是宁静、和谐、清丽的自然景象，体现优美的审美形态。自然（A）是美的类型而非审美形态，含蓄（B）是风格，壮美（C）强调宏大。","multi":false},{"no":11,"t":"亚里士多德认为，悲剧的特殊效果在于引起人们的","o":["痛苦与绝望","怜悯与恐惧","尊严与自豪","悲伤与恐怖"],"a":[1],"exp":"亚里士多德在《诗学》中提出，悲剧通过引起怜悯与恐惧使情感得到净化。痛苦与绝望（A）过于消极，尊严与自豪（C）是崇高效果，悲伤与恐怖（D）不准确。","multi":false},{"no":12,"t":"“大漠孤烟直，长河落日圆”，从审美形态来看这句诗属于","o":["优美","意境","崇高","自然"],"a":[2],"exp":"此句描绘大漠、长河、孤烟、落日的宏大意象，体现苍茫壮阔的崇高风格。优美（A）强调和谐小巧，意境（B）是主客交融的境界，自然（D）过于宽泛。","multi":false},{"no":13,"t":"中世纪美学在根本上属于","o":["哲学","神学","社会学","心理学"],"a":[1],"exp":"中世纪美学是神学的婢女，美被理解为上帝的光辉。哲学（A）是古希腊美学的属性，社会学（C）和心理学（D）是现代学科。","multi":false},{"no":14,"t":"下列美学家中，属于经验主义的是","o":["休谟","康德","席勒","黑格尔"],"a":[0],"exp":"休谟是英国经验主义美学的重要代表。康德（B）是德国先验哲学，席勒（C）是美育理论家，黑格尔（D）是德国古典哲学，均不属于经验主义。","multi":false},{"no":15,"t":"中国古代诗论中的“不着一字，尽得风流”，所涉及的审美理解的特点是","o":["非情感性","非概念性","非直观性","非感知性"],"a":[1],"exp":"“不着一字，尽得风流”强调不依赖概念语言而传达深长意蕴，体现审美理解的“非概念性”。A（非情感性）错误——诗中充满情感；C和D与诗句原意相反。","multi":false},{"no":16,"t":"审美经验中最为活跃的因素是","o":["情感","想象","理性","感知"],"a":[0],"exp":"情感是审美经验中最活跃的要素——它驱动感知、激发想象、渗透理解。想象（B）虽活跃，但受情感驱动；理性（C）和感知（D）相对稳定。","multi":false},{"no":17,"t":"明代书法家祝允明提出：“身与事接而境生，境与身接而情生”，这指的是审美经验的","o":["呈现阶段","构成阶段","评价阶段","鉴赏阶段"],"a":[0],"exp":"此句描述主体通过与对象接触产生境界、由境界引发情感，属于审美经验的“呈现阶段”（感知触发）。构成阶段（B）是想象加工，评价阶段（C）是判断，鉴赏阶段（D）是接受。","multi":false},{"no":18,"t":"在审美经验的构成要素中，直接与对象发生关系的是","o":["感知","想象","情感","理解"],"a":[0],"exp":"感知是审美经验中直接与对象发生关系的要素——通过感官把握对象的感性特征。想象（B）是对感知材料的加工，情感（C）是驱动力量，理解（D）是深层把握。","multi":false},{"no":19,"t":"克罗齐的“艺术即直觉”说体现的艺术观是","o":["游戏说","符号说","表现说","巫术说"],"a":[2],"exp":"克罗齐的“艺术即直觉”强调艺术是主观情感的表现，属于表现说。游戏说（A）是席勒，符号说（B）是朗格，巫术说（D）是弗雷泽等。","multi":false},{"no":20,"t":"荣格关于艺术起源的学说是","o":["模仿说","游戏说","劳动说","集体无意识说"],"a":[3],"exp":"荣格认为艺术源于集体无意识和原型意象。模仿说（A）是亚里士多德，游戏说（B）是席勒，劳动说（C）是普列汉诺夫。","multi":false},{"no":21,"t":"“art”一词在古希腊语中的意思主要是指","o":["思想","情感","技艺","智慧"],"a":[2],"exp":"古希腊语“techne”指技艺、技能，包括手工制作和艺术创作。思想（A）和智慧（D）是哲学范畴，情感（B）是表现说的核心。","multi":false},{"no":22,"t":"艺术敏感主要是指艺术家的","o":["表现力","理解力","判断力","感悟力"],"a":[3],"exp":"艺术敏感是艺术家感受生活、体验世界的敏锐感悟力，是孕育意象的起点。表现力（A）是物化能力，理解力（B）和判断力（C）是理性能力。","multi":false},{"no":23,"t":"“期待视界”对于作品来说是一种","o":["先在结构","心理结构","无意识结构","潜意识结构"],"a":[0],"exp":"“期待视界”是接受者接受作品之前已有的审美经验和认知框架，对作品来说是一种“先在结构”。心理结构（B）过泛，无意识（C）和潜意识（D）是精神分析概念。","multi":false},{"no":24,"t":"艺术最核心的功能是","o":["宣传","审美","教育","娱乐"],"a":[1],"exp":"审美是艺术最核心、最本质的功能。宣传（A）、教育（C）、娱乐（D）都是派生功能，需通过审美功能实现。","multi":false},{"no":25,"t":"比较合理的艺术分类标准应该是","o":["艺术作品自身的存在方式","艺术作品与欣赏者之间的关系","艺术与现实之间的关系","艺术作品与创作者之间的关系"],"a":[0],"exp":"按艺术作品自身的存在方式（时间艺术、空间艺术、时空艺术）进行分类是比较合理且全面的标准。B、C、D都是特定角度的分类依据，不如A具有普遍性。","multi":false},{"no":26,"t":"审美教育的实践基础是","o":["教育活动","道德活动","艺术活动","审美活动"],"a":[3],"exp":"审美教育的直接实践基础是审美活动——只有在审美体验中才能实现美育的目标。教育活动（A）是一般形式，道德活动（B）是德育，艺术活动（C）是审美活动的主要形式但不等于全部。","multi":false},{"no":27,"t":"孔子主张“兴于诗，立于礼，成于乐”，说明他把乐的感化作用看成是育人的","o":["最高境界","现实途径","重要手段","根本目的"],"a":[0],"exp":"孔子认为人格修养始于诗（感发），立于礼（规范），最终“成于乐”——以乐的感化达成心灵的和谐自由，是育人的最高境界。重要手段（C）不准确，根本目的（D）过于宽泛。","multi":false},{"no":28,"t":"西方美学史上最早明确提及审美教育的美学家是","o":["亚里士多德","苏格拉底","柏拉图","毕达哥拉斯"],"a":[2],"exp":"柏拉图在《理想国》中最早明确论述审美教育。亚里士多德（A）论净化但晚于柏拉图，苏格拉底（B）无系统美育论述，毕达哥拉斯（D）论数的和谐。","multi":false},{"no":29,"t":"席勒认为，美育的独特目的是","o":["促进健康","促进认识","促进道德","促进鉴赏力"],"a":[3],"exp":"席勒认为美育的独特目的是培养人的“审美鉴赏力”，使人获得自由完整的人性。健康（A）是体育，认识（B）是智育，道德（C）是德育。","multi":false},{"no":30,"t":"与一般的教育方式相比，美育最显著的特点是","o":["诉诸感性","化性起伪","理性直观","陶养性情"],"a":[0],"exp":"美育区别于德育、智育的最显著特点是“诉诸感性”——以感性形象和情感体验打动人。化性起伪（B）是荀子美育观，理性直观（C）是哲学概念，陶养性情（D）是效果而非最显著特点。","multi":false},{"no":31,"t":"审美经验的内在机制中蕴涵的超越性主要包括","o":["从物质世界向精神世界超越","从现实世界向理想世界超越","从经验世界向超验世界超越","从主观世界向客观世界超越","从内在世界向外在世界超越"],"a":[0,1,2],"exp":"审美经验的超越性表现为从物质到精神（A）、从现实到理想（B）、从经验到超验（C）的超越。D和E的方向与超越性（向上、向深）不符。","multi":true},{"no":32,"t":"审美情感对于审美想象的作用主要有","o":["审美情感是审美想象的原动力","审美情感是审美想象的对象和内容","审美情感能够调节和支配审美想象","审美情感能使审美想象具有普遍性","审美情感能使审美想象具有客观性"],"a":[0,1,2],"exp":"审美情感是想象的原动力（A）、对象和内容（B）、能够调节支配想象（C）。D（普遍性）和E（客观性）是理解的功能而非情感对想象的作用。","multi":true},{"no":33,"t":"从美学史来看，美学家们划分艺术类型的主要依据是","o":["艺术与现实的关系","艺术与作者的关系","艺术作品与欣赏者的关系","艺术的起源","艺术作品自身的存在方式"],"a":[0,2,4],"exp":"艺术分类的主要依据是艺术与现实的关系（A，如模仿/表现）、与欣赏者的关系（C）、作品自身存在方式（E）。艺术与作者关系（B）和起源（D）不是主要分类依据。","multi":true},{"no":34,"t":"在中国近代美学史上，对美育作为一门独立学科的形成做出重要贡献的美学家有","o":["蔡元培","王国维","梁启超","宗白华","李泽厚"],"a":[0,1,2],"exp":"蔡元培、王国维、梁启超是近代美育学科的主要奠基人。宗白华（D）和李泽厚（E）是20世纪中后期的美学家，不属于学科形成期的主要贡献者。","multi":true},{"no":35,"t":"美学史上关于美育内涵的主要观点有","o":["美育是人格教育","美育是感恩教育","美育是情感教育","美育是艺术教育","美育是生命教育"],"a":[0,2,3],"exp":"美学史上关于美育内涵的主要观点有：人格教育（A，蔡元培等）、情感教育（C）、艺术教育（D）。感恩教育（B）和生命教育（E）不是美学史上关于美育内涵的主要观点。","multi":true}],"essay":[{"no":36,"t":"简述自然美与人的关系。","ans":"（1）自然美并不是自然物所固有的，它是相对于人而言的，在人类产生之前，自然无所谓美与不美，自然现象只有同人发生了审美关系才成为美的。（2）自然美是在人类社会和人的实践的漫长发展过程中逐渐发生和生成的。","exp":"自然美不是纯客观属性，而是在人的审美实践中生成的价值。没有人，自然就没有“美”的意义；人在实践中不断发现和创造自然美，自然美是人与自然审美关系的产物。","type":"简答"},{"no":37,"t":"简述审美活动并非封闭孤立、与世隔绝的原因。","ans":"（1）审美活动从根本上要受物质实践的决定和制约。（2）物质生产劳动所达到的历史水准以及在生产中所形成的人与人、人与自然之间相互关系，会通过各种中介因素渗透到审美活动中。","exp":"审美活动不是脱离现实的纯精神活动，它受生产力水平、社会关系等物质实践的制约，是社会历史发展的一部分。审美趣味、审美形态都随社会条件变化而变化。","type":"简答"},{"no":38,"t":"简述划分审美形态的基本标准。","ans":"（1）广泛性或普适性，即适用于一切艺术现象和审美活动。（2）统摄性，即集杂多于统一。（3）历史性，即不仅在历史上有持久的影响，而且在当今社会中仍有强大的生命力。","exp":"审美形态的划分需兼顾普适性（适用范围广）、统摄性（能概括多种现象）、历史性（有文化积淀和持久影响），三者共同保证审美形态作为理论范畴的有效性。","type":"简答"},{"no":39,"t":"简述悲剧的基本特征。","ans":"（1）悲剧通过对人生存在的否定性体验，展现出对人生存在价值的肯定。（2）悲剧体现的是人与自然、社会及自身存在的冲突和超越。（3）悲剧带给人的情感体验是一种人生实践存在的深层体验。","exp":"悲剧不是单纯展示痛苦，而是通过毁灭呈现抗争和尊严；悲剧冲突是深刻的生存矛盾；悲剧体验触及人生的根本意义，给人以精神震撼和升华。","type":"简答"},{"no":40,"t":"简述审美感知的基本特征。","ans":"（1）审美感知总是与情感活动紧紧地交织在一起。（2）审美感知具有积极的选择能力。（3）审美感知总是以完形的方式来把握对象，因而具有整体性的特点。","exp":"审美感知不同于日常感知，它受情感驱动，主动选择对象的审美属性，并以整体性的方式把握对象形式，而非被动接受零散信息。","type":"简答"},{"no":41,"t":"简述蔡元培的美育思想。","ans":"（1）率先把“美育”一词引入中国。（2）认为美育的目的在于陶养感情。（3）提出了“以美育代宗教”的主张。","exp":"蔡元培是中国现代美育的先驱，他将美育纳入国民教育体系，强调美育通过情感陶冶提升人格，并主张以美育代替宗教在精神教化中的作用。","type":"简答"},{"no":42,"t":"试论审美活动是人最具本己性的存在方式。","ans":"（1）人在审美活动中的存在不同于在日常生活中的存在，它是一种超越性的存在方式。（2）人在审美活动中的存在不同于在异化活动中的存在，它是一种自由的存在方式。（3）人在审美活动中的存在不同于人的现实存在，它是一种应然的存在方式。","exp":"审美活动使人摆脱功利束缚和异化状态，进入自由、超越的精神境界。在日常工作和生活中，人常受制于生存压力和外部目的；在审美中，人以完整的人性面对世界，实现情感与理性、个体与社会的和谐统一。审美活动最贴近人的本质追求——自由、创造、意义，因此是人最“本己”（最真实、最本真）的存在方式。例如，欣赏音乐或自然美景时，人暂时忘却烦恼，与对象融为一体，体验到生命的充盈和精神的解放，这正是人的理想存在状态。","type":"论述"},{"no":43,"t":"举例说明艺术敏感是艺术家生产意象的重要条件。","ans":"（1）艺术家对生活的敏感是形成意象雏形的最初动力。（2）艺术敏感为艺术家意象创造准备了丰富的素材。（3）艺术敏感与主体先在的文化心理结构有着紧密关系，可以赋予意象以丰富的意义。","exp":"艺术敏感是艺术家区别于常人的特质——能从平凡生活中发现不平凡的美学意义。例如，鲁迅对童年记忆的敏感，使百草园、社戏等普通生活场景转化为深邃的文学意象；梵高对光线和色彩的敏感，使他能从麦田、星空等寻常景物中创造出震撼人心的艺术意象。没有敏感，生活素材就只是素材，无法被激活为意象；有了敏感，艺术家才能捕捉到常人忽略的美学信息，并将其与自身的文化心理结构相结合，孕育出独特的审美意象。敏感既是意象生成的起点（触发创作冲动），也是意象深化的保障（赋予意象多层意义），是艺术家生产意象不可缺失的重要条件。","type":"案例"}]},{"id":"2410","year":2024,"month":10,"label":"2024年10月","choice":[{"no":1,"t":"美学的根基是","o":["文学","史学","哲学","科学"],"a":[2],"exp":"美学从诞生之日起就从属于哲学，审美本质、价值、意义等问题需要哲学思辨来把握，哲学是美学的根基。文学（A）和史学（B）是具体人文学科，科学（D）是实证方法，均不能作为美学的根基。","multi":false},{"no":2,"t":"马克思主义存在论的根基是","o":["实践","历史","文化","劳动"],"a":[0],"exp":"马克思主义存在论以“实践”为根基，强调人的存在是在实践中生成的。历史（B）是实践的过程，文化（C）是实践的产物，劳动（D）是实践的最基本形式，但“实践”是更根本、更全面的概念。","multi":false},{"no":3,"t":"属于审美趣味的内在方面的是","o":["能力或鉴赏力","兴趣或品位","能力或兴趣","品位或鉴赏力"],"a":[0],"exp":"审美趣味的内在方面是能力或鉴赏力（审美判断力），外在表现是兴趣或品位。B、C、D均将内在与外在混淆或不完整。","multi":false},{"no":4,"t":"最能体现人的本质特点的活动方式是","o":["劳动","生殖","审美","宗教"],"a":[2],"exp":"审美活动是人的自由自觉活动的集中体现，最直接地彰显人的本质力量——情感、想象、创造。劳动（A）是基础活动，生殖（B）是生物本能，宗教（D）是异化的精神活动，均不如审美更能体现人的本质特点。","multi":false},{"no":5,"t":"处在审美体验中的人要去","o":["客观认识对象的物理属性","客观评价对象的实用价值","正确把握对象的内在规律","把客体对象完全接纳到自己的生命世界中"],"a":[3],"exp":"审美体验是主体将对象融入自身生命世界、与之交融共鸣的过程。A是科学认知，B是功利评价，C是理性认识，均非审美体验的特征。","multi":false},{"no":6,"t":"审美对象从它所依存的客观事物中被分离出来是因为","o":["主体的社会经验","主体的创造性观照","主体的审美阅历","主体的单纯的静观"],"a":[1],"exp":"审美对象不是客观事物本身，而是在主体创造性观照（审美态度和情感投射）中从客观事物中分离、生成的。社会经验（A）和审美阅历（C）是背景条件，单纯静观（D）过于被动。","multi":false},{"no":7,"t":"提出动物也有美感的是","o":["斯宾塞","弗洛伊德","达尔文","德谟克利特"],"a":[2],"exp":"达尔文从进化论角度认为动物（如鸟类）也具有美感能力。斯宾塞（A）发展游戏说，弗洛伊德（B）论性欲升华，德谟克利特（D）论摹仿。","multi":false},{"no":8,"t":"表征人类已经具有简单审美意识的生产工具出现于","o":["新人阶段","智人阶段","直立人阶段","南方古猿阶段"],"a":[1],"exp":"智人阶段（旧石器时代晚期）出现了制作精美的生产工具，其对称、均衡等形式感表明人类已有简单审美意识。新人（A）是智人的别称，直立人（C）工具较粗糙，南方古猿（D）尚未制造工具。","multi":false},{"no":9,"t":"荒诞作为审美范畴出现在","o":["14世纪中叶以后","17世纪中叶以后","18世纪中叶以后","19世纪中叶以后"],"a":[3],"exp":"荒诞作为审美范畴形成于19世纪中叶以后，与现代非理性哲学和现代主义艺术（如存在主义、荒诞派戏剧）密切相关。14世纪（A）是文艺复兴前，17世纪（B）是古典主义，18世纪（C）是启蒙时期。","multi":false},{"no":10,"t":"西方悲剧崇尚的是","o":["宗教精神","斗争精神","服从精神","牺牲精神"],"a":[3],"exp":"西方悲剧（如古希腊悲剧）崇尚牺牲精神——主人公为理想、命运或道德信念而献身。宗教精神（A）是中世纪特征，斗争精神（B）和服从精神（C）均不准确。","multi":false},{"no":11,"t":"体现出主体与对象之间和谐关系的审美形态是","o":["优美","崇高","悲剧","荒诞"],"a":[0],"exp":"优美体现主体与对象之间的和谐、统一、平衡关系。崇高（B）体现冲突与超越，悲剧（C）体现毁灭与抗争，荒诞（D）体现不和谐与虚无。","multi":false},{"no":12,"t":"在审美意象的形式构成上，崇尚往往具有","o":["劲健的物质力量","劲健的精神力量","粗犷博大的感性形态","惊心动魄的气势"],"a":[2],"exp":"崇高在形式上具有粗犷、博大、雄伟的感性形态。劲健的物质力量（A）和惊心动魄的气势（D）是效果，劲健的精神力量（B）是内涵，均非“形式构成”上的特征。","multi":false},{"no":13,"t":"提出悲剧理论中的“焦虑说”的是","o":["克尔凯郭尔","尼采","康德","黑格尔"],"a":[0],"exp":"克尔凯郭尔从存在主义角度提出“焦虑说”，认为悲剧源于个体生存的焦虑。尼采（B）提出日神酒神说，康德（C）论崇高，黑格尔（D）论冲突，均不属“焦虑说”。","multi":false},{"no":14,"t":"许多审美形态最初总是表现为","o":["艺术形态","自然形态","精神形态","知识形态"],"a":[0],"exp":"许多审美形态（如悲剧、喜剧、崇高）最初是在艺术作品中得以集中体现和理论概括的。自然形态（B）是自然美，精神形态（C）和知识形态（D）不准确。","multi":false},{"no":15,"t":"西方古代美学讨论的核心问题是","o":["美的本质问题","审美经验问题","艺术问题","审美形态问题"],"a":[0],"exp":"西方古代美学（从柏拉图到中世纪）的核心问题是“美的本质”——什么是美。审美经验问题（B）是近代的转向，艺术问题（C）是黑格尔的重点，审美形态问题（D）是现代的关注。","multi":false},{"no":16,"t":"托马斯·门罗的美学思想属于","o":["新自然主义","实用主义","解释学","唯意志论"],"a":[0],"exp":"托马斯·门罗是“新自然主义”美学的代表，主张用科学实证方法研究审美现象。实用主义（B）是杜威，解释学（C）是伽达默尔，唯意志论（D）是叔本华、尼采。","multi":false},{"no":17,"t":"主体能够通过感觉器官把握对象的审美特征，这体现了审美经验的","o":["直观性","超越性","功利性","非功利性"],"a":[0],"exp":"通过感觉器官直接把握对象特征，体现了审美经验的“直观性”。超越性（B）是深层体验，功利性（C）和非功利性（D）是态度特征。","multi":false},{"no":18,"t":"在下列学说中，从艺术的本质出发界定艺术的是","o":["模仿说","游戏说","载道说","娱乐说"],"a":[0],"exp":"模仿说探讨“艺术是什么”（艺术的本质），从本质角度界定艺术。游戏说（B）和娱乐说（D）从起源或功能角度，载道说（C）从功能角度。","multi":false},{"no":19,"t":"艺术品是为接受者而存在的，这说明了艺术品具有","o":["自律性","他律性","符号性","封闭性"],"a":[1],"exp":"艺术品的存在依赖接受者的参与，说明其具有“他律性”（受外部因素制约）。自律性（A）强调自我规定，符号性（C）是媒介特征，封闭性（D）相反。","multi":false},{"no":20,"t":"主体从客观世界中摄取象征物并赋予其象征意义，由此产生的意象属于","o":["仿象","兴象","喻象","抽象"],"a":[2],"exp":"“喻象”是通过借喻、象征方式表达意义的意象，主体赋予客观物以象征意义。仿象（A）模仿物象，兴象（B）触物起情，抽象（D）舍弃具象。","multi":false},{"no":21,"t":"在艺术品的结构中，直接指示并负载着意象世界的是","o":["物质实在层","形式符号层","社会意识层","意境超验层"],"a":[1],"exp":"形式符号层（色彩、线条、音符、词语）直接指示并负载着意象世界。物质实在层（A）是材质，社会意识层（C）不属于艺术品层次结构，意境超验层（D）是意象的升华。","multi":false},{"no":22,"t":"艺术家在创作中突然出现的精神亢奋、想象力活跃、文思泉涌的状态被称作","o":["艺术敏感","艺术灵感","艺术直觉","艺术技巧"],"a":[1],"exp":"艺术灵感是创作中突然迸发的精神亢奋、意象奔涌的状态。艺术敏感（A）是感悟力，艺术直觉（C）是直接把握，艺术技巧（D）是操作能力。","multi":false},{"no":23,"t":"刘勰说：“观文者披文以入情”，这句话涉及到的艺术活动环节是","o":["艺术创造","艺术接受","艺术品","艺术史"],"a":[1],"exp":"“观文者”指读者，“披文以入情”指通过文本进入情感世界，属于艺术接受环节。艺术创造（A）是作者的活动，艺术品（C）是中介，艺术史（D）是历史维度。","multi":false},{"no":24,"t":"主张艺术作品中存在许多空白和不确定性的美学家是","o":["英伽登","伽达默尔","尧斯","伊瑟尔"],"a":[0],"exp":"英伽登提出艺术作品的“图式化结构”中存在“空白”和“未定性”，需要读者填补。伽达默尔（B）论解释学，尧斯（C）提出期待视野，伊瑟尔（D）也论空白但英伽登更早系统论述。","multi":false},{"no":25,"t":"介于审美和实用之间的艺术形态是","o":["建筑","雕塑","绘画","音乐"],"a":[0],"exp":"建筑既有实用功能（居住）又有审美功能（形式美），介于审美与实用之间。雕塑（B）、绘画（C）、音乐（D）均以审美功能为主。","multi":false},{"no":26,"t":"梁启超认为美育是一种","o":["艺术教育","趣味教育","道德教育","信仰教育"],"a":[1],"exp":"梁启超明确提出美育是“趣味教育”，强调通过审美培养人的生命情趣。艺术教育（A）是途径，道德教育（C）是德育，信仰教育（D）不准确。","multi":false},{"no":27,"t":"孔子以山水比德，这可以说明","o":["美育是人格教育","美育是情感教育","美育是艺术教育","美育是人文教育"],"a":[0],"exp":"孔子以山水比德（“智者乐水，仁者乐山”）是将自然美与人格修养相联系，体现了美育是“人格教育”的思想——通过审美陶冶提升道德人格。情感教育（B）和艺术教育（C）均不全面，人文教育（D）过于宽泛。","multi":false},{"no":28,"t":"美育的终极目标是","o":["培养全面发展的人","培养具有高尚情操的人","培养具有艺术素养的人","培养符合社会规范的人"],"a":[0],"exp":"美育的终极目标是培养全面发展的人——感性与理性和谐、个性与社会性协调。高尚情操（B）是德育目标，艺术素养（C）是艺术教育目标，社会规范（D）是社会化目标。","multi":false},{"no":29,"t":"贺拉斯提出的美育理论是","o":["以美育代宗教","寓教于乐","载道说","净化说"],"a":[1],"exp":"贺拉斯在《诗艺》中提出“寓教于乐”原则。以美育代宗教（A）是蔡元培，载道说（C）是韩愈，净化说（D）是亚里士多德。","multi":false},{"no":30,"t":"“习与性成”的思想说明了","o":["美育要注意因势利导","美育就是修身养性","美育是一个潜移默化的过程","美育是主体的率性而为"],"a":[2],"exp":"“习与性成”意为习惯养成性格，说明美育对人的影响是长期的、渐进的、潜移默化的。因势利导（A）是方法，修身养性（B）是目的，率性而为（D）相反。","multi":false},{"no":31,"t":"审美活动是","o":["一种由外力所决定、所强制的活动","一种最符合人性尊严的活动","一种理性的活动","一种摆脱了肉体必然性对人支配的活动","一种只属于人的活动"],"a":[1,3,4],"exp":"审美活动是最符合人性尊严的活动（B）、摆脱肉体必然性的活动（D）、只属于人的活动（E）。A（外力强制）和C（纯理性活动）与审美活动的自由性和感性特征相悖。","multi":true},{"no":32,"t":"广义的审美形态包括","o":["自然美","艺术美","社会美","生活美","装饰美"],"a":[0,1,2],"exp":"广义审美形态包括自然美（A）、艺术美（B）、社会美（C）三大类。生活美（D）包含于社会美，装饰美（E）属于工艺美范畴。","multi":true},{"no":33,"t":"把审美经验视为游戏活动的美学家有","o":["康德","席勒","斯宾塞","伽达默尔","尧斯"],"a":[0,1,2,3],"exp":"康德（审美游戏论）、席勒（游戏冲动）、斯宾塞（游戏说发展）、伽达默尔（游戏作为存在方式）都将审美经验与游戏相联系。尧斯（E）是接受美学代表，不属“游戏说”。","multi":true},{"no":34,"t":"下列说法中体现了美育的主体性特征的有","o":["所谓乐者，人得其得也","夫美不自美，因人而彰","智者乐水，仁者乐山","有一千个读者，就有一千个哈姆雷特","随心所欲不逾矩"],"a":[0,1,2,3,4],"exp":"A（乐是人的自我实现）、B（美因人而显现）、C（主体以山水比德）、D（接受者的个性差异）、E（自由与规范的统一）均体现了美育中主体的能动性和个性特征。五个选项均正确。","multi":true},{"no":35,"t":"美育是一种","o":["形象直观的教育","潜移默化的教育","立竿见影的教育","以情动人的教育","以理服人的教育"],"a":[0,1,3],"exp":"美育是形象直观的（A）、潜移默化的（B）、以情动人的（D）教育。C（立竿见影）不符合美育的长期性，E（以理服人）是智育的特征。","multi":true}],"essay":[{"no":36,"t":"简述美学思想与审美意识的关系。","ans":"（1）美学思想奠基于审美意识，但有进一步的发展。（2）审美意识是一些不自觉的感性认识。（3）美学思想则是对于审美现象的本质、特征和规律比较自觉的理性认识。","exp":"审美意识是美学思想的感性基础，美学思想是对审美意识的理性升华。先有审美意识（原始朦胧感受），后有美学思想（系统理论思考），二者是历史与逻辑的先后关系。","type":"简答"},{"no":37,"t":"简述审美理想的特点。","ans":"（1）审美理想不是一种纯粹的理性观念，而是具有一定的形象性特点。（2）审美理想在主体的审美心理结构中必然处于最高位置。（3）审美理想一旦形成就具有很高的稳定性。","exp":"审美理想是完善美的观念，既有形象性（可感），又在心理结构中居于统摄地位，一旦形成便相对稳定，主导着审美判断和追求。","type":"简答"},{"no":38,"t":"简述审美活动的他律性。","ans":"（1）审美活动从根本上要受到物质实践的决定和制约。（2）物质生产劳动所达到的历史水准以及在生产中形成的人与人、人与自然之间相互关系的特点，会渗透到审美活动的具体内容中，并决定着审美的方向和水平。（3）各种审美形态的历史性生成和演变实质上都是人的现实境遇、生存状况以及理想追求在历史中不断发展的审美凝聚和反映。","exp":"审美活动不是纯粹自由的精神活动，它受生产力水平、社会关系等物质实践的外部条件制约，这是审美活动的“他律性”。","type":"简答"},{"no":39,"t":"简述美感和审美经验的差别。","ans":"（1）美感是指主体对于对象的主观感受，审美经验则是指人在审美活动中与对象所形成的审美关系。（2）美感是指主体瞬间的感受和体验，审美经验则是指审美对象被构成并得到感受和评价的动态过程。（3）美感是指主体对于某种现成对象所做出的反应，因而美感理论实际上假定美或审美对象在审美活动开始之前就已经存在了。","exp":"美感侧重于主体的瞬时感受，审美经验侧重于主客动态建构关系；美感理论预设美的先在性，审美经验理论强调美的生成性。","type":"简答"},{"no":40,"t":"简述审美理解的基本特征。","ans":"（1）审美理解具有非概念性的特点。（2）审美理解具有多义性的特点，从而使审美对象的含义显得丰富多彩和不可穷尽。","exp":"审美理解不依赖抽象概念，而是在感性体验中直接领悟；同时允许不同解读，使审美对象意蕴丰富、不可穷尽。","type":"简答"},{"no":41,"t":"简述美育和情感教育的关系。","ans":"（1）美育具有强烈的情感特征，它以感性形象唤起人们的情感共鸣。（2）美育不等于情感教育，情感只是美育的中介和手段。","exp":"美育以情感为中介（以情动人），但美育的目标不止于情感培养，还包括人格完善、精神自由等更全面的发展，因此不能将美育等同于情感教育。","type":"简答"},{"no":42,"t":"试论荒诞的基本特征。","ans":"（1）荒诞是一种对人生存在的无意义状态的体悟。（2）荒诞的审美意象具有象征性。（3）荒诞的表现形式具有怪诞性。","exp":"荒诞是现代审美形态，核心是对人生无意义、世界非理性的深刻体悟（1）。它不直接说理，而是通过象征性意象（如卡夫卡的“城堡”、贝克特的“戈多”）暗示存在的荒诞（2）。其表现形式往往怪诞、变形、不和谐，打破常规逻辑和审美习惯（3）。三者共同构成荒诞的基本特征——内容上的虚无感、意象上的象征性、形式上的怪诞性，使荒诞成为现代人处境和感受的独特审美表达。","type":"论述"},{"no":43,"t":"举例说明艺术操作在艺术创作中的重要作用。","ans":"（1）艺术操作是意象生产中的一个重要环节。（2）只有艺术操作才能赋予意象以最终的形式符号，从而完成意象的物态化和物化。（3）各门类艺术由于其形式符号和传达媒介的不同，因此就需要不同的艺术操作和艺术技巧。","exp":"艺术操作是将内在心理意象转化为可感艺术品的物质实践过程。以罗丹的雕塑《思想者》为例：罗丹首先在内心形成沉思者的意象（意象孕育），然后通过雕塑操作——在泥塑中塑造形态、刻画面部表情和肌肉张力（艺术操作），最终铸造成青铜雕像（物态化与物化）。如果没有精湛的雕塑技巧和操作，内在意象就无法成为可感知的艺术品。再如书法创作中，郑板桥“手中之竹”需要通过笔墨技巧的操作来实现，同样的胸中意象，笔墨操作的不同（浓淡、干湿、疾徐）会产生截然不同的艺术效果。艺术操作是连接意象世界与物质世界的桥梁，决定了意象能否被完美地传达和显现。","type":"案例"}]},{"id":"2504","year":2025,"month":4,"label":"2025年4月","choice":[{"no":1,"t":"美学是一门研究审美现象的","o":["客观性社会科学","抽象性自然科学","审美性艺术学科","综合性人文学科"],"a":[3],"exp":"美学研究审美现象，涉及价值、情感、意义等主观精神层面，需要哲学、心理学、艺术学等多学科方法，是一门综合性人文学科。社会科学（A）强调客观性，自然科学（B）强调实证，艺术学科（C）过于狭隘。","multi":false},{"no":2,"t":"哲学方法是美学研究的","o":["次要方法","唯一方法","核心方法","理想方法"],"a":[2],"exp":"哲学方法是美学研究的核心方法，因为审美本质、价值等根本问题需要哲学思辨来把握。但不是唯一方法（B），也需要其他方法辅助；也不是次要（A）或理想（D）方法。","multi":false},{"no":3,"t":"提出“审美带有令人解放的性质”的是","o":["柏拉图","黑格尔","布瓦洛","贺拉斯"],"a":[1],"exp":"黑格尔在《美学》中提出“审美带有令人解放的性质”，强调审美使人摆脱有限性、获得精神自由。柏拉图（A）论迷狂，布瓦洛（C）论古典主义，贺拉斯（D）论寓教于乐。","multi":false},{"no":4,"t":"决定审美发生的首要、根本的因素是","o":["装饰","巫术","摹仿","劳动"],"a":[3],"exp":"物质生产劳动是人类最基本的实践活动，是审美发生首要和根本的因素。装饰（A）、巫术（B）、摹仿（C）都是审美发生的相关因素，但以劳动为基础。","multi":false},{"no":5,"t":"马克思指出：“作家绝不把自己的作品看作手段，作品就是目的本身。”这说明审美活动具有","o":["他律性","有限无功利性","自律性","最高功利性"],"a":[2],"exp":"以作品本身为目的而非手段，体现了审美活动的自律性——不依赖外在目的而自我规定。他律性（A）相反，有限无功利性（B）和最高功利性（D）是康德的概念，与本题直接指向不同。","multi":false},{"no":6,"t":"原始社会最流行、最大众化的一种审美方式是","o":["史前彩陶纹饰","史前青铜器","精美石器","粗糙石器"],"a":[0],"exp":"史前彩陶纹饰是原始社会最流行、最大众化的审美方式，在彩陶上绘制图案既实用又美观。青铜器（B）是夏商周时期，精美石器（C）和粗糙石器（D）虽与审美相关但不如彩陶纹饰具有普遍性和代表性。","multi":false},{"no":7,"t":"下列属于表演艺术的是","o":["建筑","舞蹈","雕刻","绘画"],"a":[1],"exp":"舞蹈属于表演艺术，以身体动作在时空中的表演为特征。建筑（A）、雕刻（C）、绘画（D）均属于空间艺术或造型艺术。","multi":false},{"no":8,"t":"审美对象的非实体性取决于审美活动的","o":["积极建构性","单纯静观性","感性愉悦性","社会实践性"],"a":[0],"exp":"审美对象不是在审美活动之前就存在的实体，而是在审美活动中被主体积极建构起来的，因此具有非实体性。单纯静观（B）过于被动，感性愉悦（C）是效果，社会实践（D）是根本基础。","multi":false},{"no":9,"t":"审美形态的二重性指的是","o":["贯通性与兼容性","生成性与历史性","民族性与世界性","实践性与现实性"],"a":[2],"exp":"审美形态的二重性是指民族性与世界性的统一。贯通性与兼容性（A）是审美形态的特征，生成性与历史性（B）是生成特征，实践性与现实性（D）不准确。","multi":false},{"no":10,"t":"古希腊的悲剧常被称为","o":["人生悲剧","命运悲剧","性格悲剧","社会悲剧"],"a":[1],"exp":"古希腊悲剧（如索福克勒斯《俄狄浦斯王》）以主人公无法逃脱命运的安排为核心，被称为“命运悲剧”。性格悲剧（C）如莎士比亚，社会悲剧（D）如易卜生，人生悲剧（A）过于宽泛。","multi":false},{"no":11,"t":"喜剧有多种次级形态，包括","o":["暴露与歌颂","滑稽与嘲笑","讽刺与幽默","揭露与批判"],"a":[2],"exp":"喜剧的基本形式是讽刺和幽默两种次级形态。暴露与歌颂（A）、滑稽与嘲笑（B）、揭露与批判（D）都是具体手法或效果，不是喜剧的次级形态分类。","multi":false},{"no":12,"t":"最早被人类认识和把握的审美形态是","o":["优美","崇高","悲剧","喜剧"],"a":[0],"exp":"优美是最早被人类认识和把握的审美形态，因为和谐、秩序、对称等形式美在原始时期就受到关注。崇高（B）、悲剧（C）、喜剧（D）都是在文明发展到较高阶段才被认识的。","multi":false},{"no":13,"t":"荒诞引起的笑","o":["是对旧事物的讽刺","是对自己的信心和自豪","是充满希望的肯定","是一种无望的否定"],"a":[3],"exp":"荒诞引起的笑不是讽刺旧事物（A）或充满希望的肯定（C），也不是自信自豪（B），而是一种对世界非理性和人生虚无的无望的否定性笑。","multi":false},{"no":14,"t":"“将那无价值的撕破给人看”这句话所指的审美形态是","o":["悲剧","荒诞","丑","喜剧"],"a":[3],"exp":"鲁迅此语是对喜剧本质的经典概括——将无价值事物撕破给人看，引发批判性的笑。悲剧（A）展现有价值事物的毁灭，荒诞（B）体现无意义，丑（C）表现畸形。","multi":false},{"no":15,"t":"夏夫兹博里把人类天生就具有的分辨善恶和美丑的能力归结于","o":["视觉器官","听觉器官","内在感官","外在感官"],"a":[2],"exp":"夏夫兹博里提出“内在感官说”，认为人类天生具有分辨善恶美丑的“内在感官”或“第六感官”。外在感官（D）包括视觉（A）和听觉（B），但不能单独完成审美判断。","multi":false},{"no":16,"t":"《荀子·乐论》云：“以道制欲，则乐而不乱。”就审美经验而言，这句话说的是","o":["感知和想象的关系","想象和情感的关系","情感和理智的关系","想象和理智的关系"],"a":[2],"exp":"“以道制欲”意为用理性原则（道）节制感性欲望（欲），涉及审美经验中情感与理智的关系。A、B、D中的“想象”在此句中未涉及。","multi":false},{"no":17,"t":"审美经验中，心理距离的产生需要借助于","o":["感知","情感","想象","理解"],"a":[2],"exp":"心理距离（布洛）主要通过想象来实现——想象使主体脱离日常功利意识，进入审美世界。感知（A）是基础，情感（B）和（D）虽参与，但距离的产生依赖想象的转化作用。","multi":false},{"no":18,"t":"与中国的“言志说”相近的西方理论是","o":["有意味的形式说","集体无意识说","表现说","符号说"],"a":[2],"exp":"“言志说”强调诗歌表达思想情感，与西方的“表现说”相近。有意味的形式说（A）强调形式，集体无意识说（B）强调原型，符号说（D）强调符号形式。","multi":false},{"no":19,"t":"意大利美学家克罗齐认为艺术即","o":["形式","符号","模仿","直觉"],"a":[3],"exp":"克罗齐在《美学原理》中提出“艺术即直觉”，认为艺术是主观情感的直接表现。形式（A）是贝尔的关注点，符号（B）是朗格，模仿（C）是亚里士多德。","multi":false},{"no":20,"t":"追问艺术怎样存在，属于","o":["艺术认识论","艺术价值论","艺术本体论","艺术接受论"],"a":[2],"exp":"艺术本体论探讨艺术的根本存在方式，即“艺术怎样存在”。认识论（A）关注如何认识，价值论（B）关注功能意义，接受论（D）关注欣赏者。","multi":false},{"no":21,"t":"创作主体与接受主体之间的中介与桥梁是","o":["艺术欣赏","艺术品","艺术家","艺术技巧"],"a":[1],"exp":"艺术品是连接艺术创作主体和接受主体的中介与桥梁。艺术欣赏（A）是接受活动，艺术家（C）是创作主体，艺术技巧（D）是手段。","multi":false},{"no":22,"t":"孕育意象需要艺术家具备","o":["“潇洒”的精神状态","“豁达”的精神状态","“宽容”的精神状态","“虚静”的精神状态"],"a":[3],"exp":"“虚静”是孕育意象的重要精神状态，要求主体排除杂念、超越知性，以虚空的心胸接纳万物。潇洒（A）、豁达（B）、宽容（C）均不准确。","multi":false},{"no":23,"t":"和“艺术操作与技巧”相关的是郑板桥所说的","o":["“手中之竹”","“眼中之竹”","“胸中之竹”","“山中之竹”"],"a":[0],"exp":"郑板桥“眼中之竹”（感知）、“胸中之竹”（意象）、“手中之竹”（物化），“手中之竹”涉及艺术操作与技巧。B是感知，C是意象孕育，D是客观自然物。","multi":false},{"no":24,"t":"鲁迅的作品批判了落后的国民性，这反映了艺术的","o":["思想启迪功能","政治宣传功能","社会娱乐功能","道德教育功能"],"a":[0],"exp":"鲁迅通过文学批判国民性，启发民众思想觉醒，体现了艺术的思想启迪功能。政治宣传（B）过于狭隘，娱乐（C）是消遣，道德教育（D）侧重品德培养。","multi":false},{"no":25,"t":"提出“以美育代宗教”的中国现代美学家是","o":["王国维","蔡元培","梁启超","朱光潜"],"a":[1],"exp":"蔡元培在1917年明确提出“以美育代宗教”的主张。王国维（A）引入西方美学，梁启超（C）倡导趣味教育，朱光潜（D）是现当代美学家。","multi":false},{"no":26,"t":"荀子所谓“化性起伪”中的“伪”是指","o":["虚伪矫饰","私人欲望","自然本质","精神境界"],"a":[3],"exp":"荀子“化性起伪”中的“伪”指人为教化所达到的精神境界和能力，非虚伪矫饰（A）或私人欲望（B）。自然本质（C）是“性”而非“伪”。","multi":false},{"no":27,"t":"王国维在《论教育之宗旨》一文中","o":["认为美育是一种“人格教育”","认为美育是一种“趣味教育”","将美育与德育、智育、体育并称四育","提出“寓教于乐”"],"a":[2],"exp":"王国维在《论教育之宗旨》中首次将美育与德、智、体并称四育。A是蔡元培，B是梁启超，D是贺拉斯。","multi":false},{"no":28,"t":"把美育等同于艺术教育，其错误在于","o":["把美和善混为一谈","把美等同于美感","夸大了艺术在审美教育中的地位和作用","颠倒了因果关系"],"a":[2],"exp":"美育不仅包括艺术教育，还涵盖自然美、社会美等领域，将美育等同于艺术教育是夸大了艺术的地位和作用。A是把美育等同于人格教育的错误，B是美学基本问题，D不准确。","multi":false},{"no":29,"t":"孔子说：“草上之风必偃”，这说明美育的特点是","o":["诉诸感性","潜移默化","能动性","艺术性"],"a":[1],"exp":"此句意为风吹草倒，比喻教化像风一样无声地影响人，体现美育“潜移默化”的特点。诉诸感性（A）是美育的另一个特点，但此句强调的是潜移默化。能动性（C）和艺术性（D）不符。","multi":false},{"no":30,"t":"柏拉图强调“音乐教育比其他教育都重要得多”的理由是","o":["节奏与乐调有最强烈的力量浸入心灵的最深处","音乐是古希腊最流行的艺术形式","只有音乐才能提高人们的审美感受力","音乐比其他艺术更易于普及"],"a":[0],"exp":"柏拉图认为节奏和乐调最能直接深入心灵，影响性格和情感，因此音乐教育最重要。流行程度（B）、提高感受力（C）、易于普及（D）均不是柏拉图的核心理由。","multi":false},{"no":31,"t":"审美理想是","o":["主体的审美趣味","主体的主观爱好和倾向","主体的美学思想","主体全部人生实践的结晶","主体心目中关于完善的美的观念"],"a":[3,4],"exp":"审美理想是主体心目中关于完善的美的观念（E），是主体全部人生实践的结晶（D）。审美趣味（A）和主观爱好（B）是个人偏好，美学思想（C）是系统理论，均不等于审美理想。","multi":true},{"no":32,"t":"朗吉弩斯认为，文学作品的崇高风格应该具有","o":["庄严伟大的思想","强烈深厚的热情","符合修辞格的藻饰","高尚的措辞","庄严宏伟的结构"],"a":[0,1,2,3,4],"exp":"朗吉弩斯在《论崇高》中提出崇高风格的五种来源：庄严伟大的思想（A）、强烈深厚的热情（B）、修辞格的运用（C）、高尚的措辞（D）、庄严宏伟的结构（E），五个选项均正确。","multi":true},{"no":33,"t":"审美经验中涉及的高级想象形式包括","o":["接近联想","对比联想","类似联想","再造性想象","创造性想象"],"a":[3,4],"exp":"想象活动的高级形式是再造性想象（D）和创造性想象（E）。接近联想（A）、对比联想（B）、类似联想（C）属于联想，是想象的低级形式。","multi":true},{"no":34,"t":"接受者在美育过程中的能动性主要表现在","o":["通过道德约束自己","对道德观念的无条件接受","有自觉的追求","能开拓出新的境界","能获得广博的知识"],"a":[2,3],"exp":"接受者在美育中的能动性表现为有自觉的追求（C）和能开拓新的境界（D）。A（道德约束）属于德育，B（无条件接受）是被动性，E（获得知识）是智育功能。","multi":true},{"no":35,"t":"席勒在《审美教育书简》中第一次明确提出了“审美教育”的概念，其贡献主要在于","o":["解释了美育的目的","揭示了美育的价值","提出了美育和艺术教育的差别","说明了美育的复杂性","分析了美育与德育的差异"],"a":[0,1],"exp":"席勒的主要贡献是解释美育的目的（A，培养完整人性）和揭示美育的价值（B，实现自由）。C（美育与艺术教育的差别）和D（美育的复杂性）不是席勒的重点，E（美育与德育的差异）是后来学者的讨论。","multi":true}],"essay":[{"no":36,"t":"简述艺术美的特征。","ans":"（1）艺术美是人创造、提炼的结果，它高于自然，是人的精神和本质力量的感性显现和确证。（2）艺术美是一种在审美活动中现实地生成的审美现象，而非游离于人的审美活动、固定不变的美的现象。","exp":"艺术美是人工创造的，经过艺术家的提炼加工，凝聚了人的精神和本质力量；艺术美在审美活动中动态生成，而非脱离主体的客观属性。","type":"简答"},{"no":37,"t":"简述判断审美趣味是否健康的标准。","ans":"（1）必须将审美趣味和具体的审美对象联系起来，看看依据该趣味所做出的判断是否充分反映了审美对象的客观特点。（2）审美趣味必然要受到主体审美理想的制约，健康的审美趣味需要积极地把对象与主体的审美理想联系起来。","exp":"健康的审美趣味需要同时尊重对象的客观特征和主体的审美理想，二者的统一是评判审美趣味健康与否的标准。","type":"简答"},{"no":38,"t":"简述作为审美发生理论的“劳动说”的主要内容。","ans":"（1）劳动说是由毕歇尔提出的，主旨是认为艺术和审美起源于人类的物质生产劳动。（2）劳动说认为在艺术发生的最初阶段，劳动、音乐和诗歌紧密相联，其劳动构成了艺术的基础。","exp":"劳动说强调物质生产劳动是艺术和审美发生的根本基础，在原始社会，艺术活动与劳动实践密不可分。","type":"简答"},{"no":39,"t":"简述再造性想象与创造性想象的区别。","ans":"（1）再造性想象是指主体根据自己或他人原有的知觉表象进行加工和综合，从而在自己的头脑中重新形成关于事物形象的心理功能。（2）创造性想象则不是为了再现事物，而是要通过主体的创造性思维产生新的表象。","exp":"再造性想象是对已有形象的复现和重组，创造性想象是无中生有地创造全新形象，是艺术创造的核心能力。","type":"简答"},{"no":40,"t":"简述西方审美经验理论的发展过程。","ans":"（1）古希腊美学已经涉及到了审美经验问题，产生了柏拉图“迷狂说”和亚里士多德的“净化说”。（2）中世纪美学揭示出了审美经验的超验性维度。（3）西方近代美学把审美经验当作美学研究的核心问题，经验主义美学堪称其代表。（4）西方现代美学也十分重视审美经验问题，产生了科学主义和人本主义两大潮流。","exp":"西方审美经验理论从古希腊萌芽，经中世纪超验化，到近代成为核心课题，再到现代分化发展，经历了一个不断深化和多元化的过程。","type":"简答"},{"no":41,"t":"简述美育的怡情养性功能。","ans":"（1）美育能够对人的精神领域进行调节，从而达到心理的平衡、人格的完善。（2）美育的方式是动于内，从内心、从人的情感的角度去打动人的。（3）美育对人的感化能够使人亲和，充满爱心。","exp":"美育通过情感陶冶调节人的心理，使内心和谐；以内在感动的方式触动人心；最终使人更具亲和力和爱心，实现人格完善。","type":"简答"},{"no":42,"t":"论述悲剧作为审美形态的主要特征。","ans":"（1）悲剧审美形态是否定性与肯定性的结合，通过对人生存在的否定性体验，从而展现对人生存在价值的肯定。（2）悲剧的审美冲突具有社会性，体现的是人与自然、社会及自身存在的冲突和超越。（3）悲剧的情感体验具有超越性，是一种人生实践存在的深层体验。","exp":"悲剧不是单纯展示痛苦和毁灭（否定性），而是在毁灭中肯定人的尊严和价值（肯定性）。其冲突不仅是个人命运，更是社会历史矛盾的深刻反映。悲剧引发的情感不仅是怜悯与恐惧，更使人超越个体经验，触及人生存在的根本意义，获得精神净化和升华。例如，《哈姆雷特》中主人公在复仇冲突中毁灭，但其对正义和真理的追寻却使观众感受到人类精神的崇高与不朽。","type":"论述"},{"no":43,"t":"以李商隐的诗《无题》为例，说明艺术家通过艺术想象创造艺术意象的过程。无题相见时难别亦难，东风无力百花残。春蚕到死丝方尽，蜡炬成灰泪始干。晓镜但愁云鬓改，夜吟应觉月光寒。蓬山此去无多路，青鸟殷勤为探看。","ans":"（1）艺术家的想象必须建立在对生活的感受和感悟的基础上。（2）艺术家需要运用想象力对自己的感受和形象进行融会与整合，由此产生出艺术意象。（3）艺术家对意象的创造必须服从自己的感悟主旨。","exp":"李商隐此诗生动展示了艺术意象的创造过程。首先，诗人对离别相思之苦有深切的感受和感悟（“相见时难别亦难”），这是想象的起点。其次，诗人将“春蚕吐丝”“蜡炬成灰”“青鸟传信”等传统意象进行融合与改造——春蚕到死丝方尽，蜡炬成灰泪始干，创造出了“相思至死不渝”的独特意象，这种意象不是对现实的简单模仿，而是情感与物象在想象中融会整合的产物。最后，诗人创造这一意象的目的是表达对爱情的执着信念和无奈感慨，“春蚕”“蜡炬”等意象服务于“别亦难”这一主旨。整个创造过程体现了艺术想象如何在生活感受的基础上，通过整合传统符号，创造出新的、情感充盈的艺术意象。","type":"案例"}]},{"id":"2510","year":2025,"month":10,"label":"2025年10月","choice":[{"no":1,"t":"美学思想属于","o":["感性认识","理性认识","非理性认识","不自觉的认识"],"a":[1],"exp":"美学思想是对审美现象的本质、特征和规律进行的系统理性思考，属于理性认识。审美意识（A、D）才是感性认识和不自觉的，非理性认识（C）不符合美学思想的理性特征。","multi":false},{"no":2,"t":"黑格尔认为美学的研究对象是","o":["美的规律","艺术","审美经验","审美关系"],"a":[1],"exp":"黑格尔明确将美学定义为“美的艺术的哲学”，认为美学的研究对象是艺术。美的规律（A）是鲍姆嘉通关注的艺术对象之一，审美经验（C）是近代美学的转向，审美关系（D）是蒋孔阳的观点。","multi":false},{"no":3,"t":"影响主体审美趣味的主要因素是","o":["社会条件","生理特征","先天禀赋","个性才能"],"a":[0],"exp":"审美趣味虽然有个体差异，但主要受后天社会条件（文化传统、教育背景、时代风尚等）的影响。生理特征（B）、先天禀赋（C）和个性才能（D）都是先天或个体因素，并非主要因素。","multi":false},{"no":4,"t":"审美活动本身所展开的是一个","o":["情感的世界","属人的世界","生命的世界","物质的世界"],"a":[1],"exp":"审美活动所展开的是一个属人的世界——以人的情感、理想、价值为核心的精神世界，是人的本质力量的感性显现。情感的世界（A）是部分，生命的世界（C）过于宽泛，物质的世界（D）是客观物理世界。","multi":false},{"no":5,"t":"在审美活动中，审美主体看重的是","o":["对象的精神意义","对象的形式创新","对象的物质功利性","对象的实际用途"],"a":[0],"exp":"审美活动中，主体超越实用层面，看重对象的精神意义（情感价值、人生意味等）。形式创新（B）是美学标准之一，但主体更关注精神意义；物质功利性（C）和实际用途（D）属于功利态度。","multi":false},{"no":6,"t":"最基本、最普遍的形式规律是","o":["均衡对称","多样统一","节奏韵律","对比调和"],"a":[1],"exp":"多样统一是形式美的最高法则，也是最基本、最普遍的形式规律。均衡对称（A）、节奏韵律（C）、对比调和（D）都是多样统一的具体表现形式。","multi":false},{"no":7,"t":"审美形态是对人类审美实践活动中的审美经验的","o":["诗意表达","感性表达","抽象演绎","逻辑总结"],"a":[3],"exp":"审美形态是对审美经验进行逻辑归类和理性描述的结果，是对审美现象的逻辑总结。诗意表达（A）和感性表达（B）属于审美体验本身，抽象演绎（C）不准确。","multi":false},{"no":8,"t":"优美感的心理特征表现在对象与主体之间的","o":["服从","和谐","斗争","对立"],"a":[1],"exp":"优美体现主体与对象之间的和谐、统一、平衡关系。服从（A）是压抑，斗争（C）和对立（D）是崇高和悲剧的特征。","multi":false},{"no":9,"t":"认为崇高和优美都是“活的形象”的美学家是","o":["席勒","康德","黑格尔","克罗齐"],"a":[0],"exp":"席勒在《审美教育书简》中认为崇高和优美都是“活的形象”，即感性形式与理性内容的统一。康德（B）将二者作为审美判断的两种类型，黑格尔（C）论艺术类型，克罗齐（D）论直觉。","multi":false},{"no":10,"t":"人们面对崇高最终体验的是一种","o":["渺小感和压迫感","力量感和实现感","无奈感和恐惧感","臣服感和满足感"],"a":[1],"exp":"面对崇高，主体初始体验可能是渺小和压迫，但最终通过理性超越获得力量感和精神实现感。A是初始体验，C和D不符合崇高的积极超越特征。","multi":false},{"no":11,"t":"在西方美学史上真正奠基了悲剧理论基础的是","o":["德谟克利特","亚里士多德","苏格拉底","柏拉图"],"a":[1],"exp":"亚里士多德在《诗学》中第一次对悲剧做出完整定义和系统分析，真正奠定了西方悲剧理论基础。德谟克利特（A）论摹仿，苏格拉底（C）论道德，柏拉图（D）否定悲剧，均未系统奠基悲剧理论。","multi":false},{"no":12,"t":"广义的荒诞实质是","o":["人的丰富性和创造力的表现","人的异化和局限性的表现","人的想象力和征服力的表现","人的理性力和自由力的表现"],"a":[1],"exp":"荒诞实质上是人的异化和局限性的表现，体现世界的非理性和人存在的无意义。丰富性（A）、想象力（C）、理性力（D）均与荒诞的否定性实质相反。","multi":false},{"no":13,"t":"夏夫兹博里提出的美学主张是","o":["表现说","迷狂说","内在感官说","心理距离说"],"a":[2],"exp":"夏夫兹博里提出“内在感官说”，认为人类天生具有分辨美丑善恶的内在感官。表现说（A）是浪漫主义，迷狂说（B）是柏拉图，心理距离说（D）是布洛。","multi":false},{"no":14,"t":"杜威的美学思想属于","o":["实用主义","存在主义","解释学","唯意志论"],"a":[0],"exp":"杜威是实用主义哲学的代表，其美学著作《艺术即经验》是实用主义美学的经典。存在主义（B）如萨特，解释学（C）如伽达默尔，唯意志论（D）如叔本华。","multi":false},{"no":15,"t":"提出“智者乐水，仁者乐山”这一主张的是","o":["老子","庄子","孔子","孟子"],"a":[2],"exp":"“智者乐水，仁者乐山”出自《论语·雍也》，是孔子的名言。老子（A）和庄子（B）是道家代表，孟子（D）是儒家后学但非此语出处。","multi":false},{"no":16,"t":"北岛的诗句“卑鄙是卑鄙者的通行证，高尚是高尚者的墓志铭”运用的是","o":["接近联想","类似联想","对比联想","回忆联想"],"a":[2],"exp":"诗句将“卑鄙”与“高尚”、“通行证”与“墓志铭”相对照，运用了对比联想。接近联想（A）基于时空接近，类似联想（B）基于相似性，回忆联想（D）基于记忆。","multi":false},{"no":17,"t":"移情论美学认为审美经验产生于主体对客体的","o":["情感投射","情感共鸣","理性思考","理性沉思"],"a":[0],"exp":"移情论（立普斯为代表）认为审美经验产生于主体将自身情感投射（移注）到客体中。情感共鸣（B）是结果，理性思考（C）和理性沉思（D）与移情论的感性投射相悖。","multi":false},{"no":18,"t":"中国古代诗学认为诗无达诂，这说明审美理解具有","o":["直观性","抽象性","多义性","模糊性"],"a":[2],"exp":"“诗无达诂”指诗歌没有唯一确定的解释，说明审美理解具有多义性。直观性（A）是感知特征，抽象性（B）是理性认识，模糊性（D）不等于多义性。","multi":false},{"no":19,"t":"北宋画家郭熙认为，画家在创作中应该“盖身即山川而取之”，这说明审美经验","o":["与身体相关","与身体无关","与精神有关","与精神无关"],"a":[0],"exp":"郭熙强调“身即山川”，指画家要用身体去感受山川，说明审美经验与身体感知密切相关。B、D直接否定，C只说精神而忽略身体，不全面。","multi":false},{"no":20,"t":"中国古代文论中的缘情说大体上接近于西方的","o":["模仿说","表现说","移情说","再现说"],"a":[1],"exp":"缘情说强调诗歌源于情感表达，与西方的“表现说”大体相近。模仿说（A）和再现说（D）强调对现实的反映，移情说（C）强调情感投射而非表达。","multi":false},{"no":21,"t":"提出“有意味的形式”说的美学家是","o":["克莱夫·贝尔","卡西尔","哈贝马斯","伽达默尔"],"a":[0],"exp":"克莱夫·贝尔在《艺术》中提出“有意味的形式”理论。卡西尔（B）论符号，哈贝马斯（C）论交往理性，伽达默尔（D）论解释学。","multi":false},{"no":22,"t":"与对象在感性形态上具有相似性的意象类型是","o":["抽象","喻象","兴象","仿象"],"a":[3],"exp":"仿象是对客观物象的模仿性再现，与对象在感性形态上具有相似性。抽象（A）舍弃相似性，喻象（B）靠象征意义，兴象（C）触物起情。","multi":false},{"no":23,"t":"“玄之又玄，众妙之门”，这句话可以用来描述艺术作品中的","o":["意象","意境","形式","技巧"],"a":[1],"exp":"“玄之又玄，众妙之门”形容深远玄妙的境界，可以用来描述意境——超越具体意象的形而上境界。意象（A）是具体形象，形式（C）是外在结构，技巧（D）是操作手段。","multi":false},{"no":24,"t":"艺术家把意象物态化和物化主要借助于","o":["艺术敏感","艺术技巧","艺术想象力","艺术灵感"],"a":[1],"exp":"艺术技巧是将内在心理意象转化为可感物质形式的操作能力，是物态化和物化的主要手段。艺术敏感（A）是起点，想象力（C）是孕育，灵感（D）是突发状态。","multi":false},{"no":25,"t":"与雕塑和建筑相比，绘画对物质材料的依赖","o":["大大减弱了","大大增强了","完全消失了","完全摆脱了"],"a":[0],"exp":"绘画以二维平面表现三维空间，对物质材料的依赖（如画布、颜料）相比雕塑（三维实体材料）和建筑（结构材料）大大减弱了。B、C、D均不准确。","multi":false},{"no":26,"t":"狭义的美育是指","o":["一切利用审美进行的教育活动","一种与德育、智育等并列的教育方式","一切艺术教育活动","一切艺术欣赏活动"],"a":[1],"exp":"狭义的美育是一种与德育、智育、体育等并列的教育方式。A是广义美育，C和D将美育等同于艺术教育，均不准确。","multi":false},{"no":27,"t":"主张美育的作用在于“消融渣滓”的美学家是","o":["孔子","孟子","朱熹","王阳明"],"a":[2],"exp":"朱熹提出“消融渣滓”之说，认为乐教（美育）可以消除人心中的杂念和私欲。孔子（A）重乐教，孟子（B）主性善，王阳明（D）主致良知，均无此表述。","multi":false},{"no":28,"t":"认为美育是一种人格教育，事实上是","o":["把美和善混为一谈","把美和真混为一谈","把真和善混为一谈","把美和智混为一谈"],"a":[0],"exp":"人格教育侧重道德人格培养，将美育等同于人格教育，是把美（审美）与善（道德）混为一谈。B和C涉及真，D涉及智，均不准确。","multi":false},{"no":29,"t":"孔子说“知之者不如好之者，好之者不如乐之者”，这说明美育的特点是","o":["诉诸感性","潜移默化","能动性","被动性"],"a":[0],"exp":"孔子强调从“知”（认知）到“好”（情感）再到“乐”（愉悦），说明美育以感性愉悦打动人，体现了“诉诸感性”的特点。潜移默化（B）和能动性（C）也是美育特点，但此句侧重感性愉悦。被动性（D）相反。","multi":false},{"no":30,"t":"荀子把人性和文化的生成归结为","o":["化性起伪","以道制欲","存天理，灭人欲","怡情养性"],"a":[0],"exp":"荀子提出“化性起伪”，认为通过教化可以转化自然本性、生成文化和人性。以道制欲（B）是《荀子·乐论》的原则，存天理灭人欲（C）是宋明理学，怡情养性（D）是美育功能。","multi":false},{"no":31,"t":"下列美学流派中，属于现代美学的有","o":["现实主义","浪漫主义","自然主义","科学主义","实用主义"],"a":[2,3,4],"exp":"科学主义（如托马斯·门罗）和实用主义（如杜威）属于西方现代美学流派。现实主义（A）和浪漫主义（B）属于近代美学流派，不属于现代。","multi":true},{"no":32,"t":"审美经验的构成要素主要有","o":["感知","想象","情感","理解","回忆"],"a":[0,1,2,3],"exp":"审美经验的构成要素是感知（A）、想象（B）、情感（C）、理解（D）四者。回忆（E）是想象的辅助材料，不作为独立构成要素。","multi":true},{"no":33,"t":"艺术品在艺术活动过程中作为中介呈现出的基本特征有","o":["他律性","自律性","开放性","兼容性","形式符号性"],"a":[0,2,4],"exp":"艺术品作为中介的特征包括他律性（依赖外部因素）、开放性（意蕴不断生成）、形式符号性（依赖符号系统）。自律性（B）是艺术品的本质特征之一但非“作为中介”呈现的特征，兼容性（D）是审美形态的特征。","multi":true},{"no":34,"t":"美育的目的主要有","o":["培养审美感受力","造就艺术人才","成就审美人生","弘扬传统文化","发展科学技术"],"a":[0,2],"exp":"美育的目的是培养审美感受力（A）和成就审美人生（C）。造就艺术人才（B）是艺术教育目标，弘扬传统文化（D）和文化传承相关，发展科学技术（E）是科技目标。","multi":true},{"no":35,"t":"对于美育和情感教育的关系，正确的理解有","o":["情感教育是美育的目的","美育本质上是一种情感教育","美育是情感教育的中介和手段","美育不等于情感教育","情感因素贯穿于美育过程的始终"],"a":[3,4],"exp":"美育不等于情感教育（D），虽然情感因素贯穿美育始终（E）。情感不是美育的目的（A），而是中介和手段；美育也不仅仅等于情感教育（B），C的表述颠倒了美育与情感教育的关系。","multi":true}],"essay":[{"no":36,"t":"简述美学与哲学的关系。","ans":"（1）美学最初依附于哲学，后来才逐渐脱离哲学成为一门独立的学科，但仍与哲学紧密相关。（2）所有的美学理论都有其哲学背景，哲学是美学的根基，美学必然包含哲学的品格。","exp":"美学从哲学母体中分化而来，始终与哲学保持着深层联系。审美本质、价值、意义等根本问题都需要哲学思辨来把握，美学理论的历史演变也总是伴随着哲学思潮的更替。","type":"简答"},{"no":37,"t":"简述审美理想在审美活动中的作用。","ans":"（1）从一定程度上看，审美理想决定着主体对审美对象的选择及其所做出的审美判断。（2）作为一种人生修养，审美理想直接使审美活动成为主体人生实践的重要组成部分。","exp":"审美理想是主体审美的最高尺度，它引导主体选择什么对象、如何评价对象；同时审美理想也是人格修养的体现，使审美活动与人生实践融为一体。","type":"简答"},{"no":38,"t":"简述丑成为审美形态的原因。","ans":"（1）由丑陋引起的情绪感受仍然属于审美情感的范畴。（2）丑表现为反常、混乱、给人以恶性刺激等形式，但人能够从这些不和谐的形式中体悟到美的存在，感受到人生的意义和价值，因此，这些丑的形式经过人的内在心理的转换而成为美的形象。","exp":"丑成为审美形态，是因为在审美活动中，丑被形式化和意义化后，能引发主体对生存的深刻反思，从否定性体验中获得精神启示，丑本身转化为审美对象。","type":"简答"},{"no":39,"t":"简述喜剧的特征。","ans":"（1）喜剧具有不和谐、悖谬的形式特征。（2）喜剧中包含着深刻的社会现实内容，具有社会批判性。（3）喜剧的情感形式表现为以笑为主的特征。（4）喜剧是否定性与肯定性的统一。","exp":"喜剧通过不和谐、错乱的形式揭示现实中的矛盾，笑是其主要情感载体，笑中既有批判（讽刺）也有肯定（幽默），在否定丑的同时肯定美。","type":"简答"},{"no":40,"t":"简述审美经验的直观性特征。","ans":"（1）审美经验是一种感性直观活动，能够通过感觉器官来把握对象的审美特征。（2）审美经验同时是一种本质直观活动，能够不经推理直接把握到事物的本质特征。","exp":"审美经验的直观性既表现为对感性形象的直接把握（感知），也表现为对深层意蕴的直接领悟（本质直观），二者统一于审美体验之中。","type":"简答"},{"no":41,"t":"简述美育与艺术教育的关系。","ans":"（1）艺术是美育最重要的媒介和手段。（2）艺术教育以培养艺术人才为目的，美育的目的则是培养全面发展的人。","exp":"艺术教育是美育的重要组成部分和主要途径，但二者不能等同。艺术教育的重点是培养艺术专业技能，美育的目标是陶冶人的情感、完善人格，两者在目的和范围上有所不同。","type":"简答"},{"no":42,"t":"论述审美活动的基本性质。","ans":"（1）审美活动是人与世界的本己性精神交流。（2）审美活动是最具个性化的精神活动。（3）审美活动是有限无功利性与最高功利性的统一。（4）审美活动是自律性与他律性的统一。","exp":"审美活动是人最真实、最本真的精神交流方式，它以情感体验为核心，超越功利又指向人的全面发展；它既是自我规定（自律）又受社会历史条件制约（他律）。审美活动使人在有限中触及无限，在感性中把握理性，是个体性与普遍性、自由与必然的辩证统一，因此它不仅是精神娱乐，更是人的存在方式之一。","type":"论述"},{"no":43,"t":"鲁迅在谈到对《红楼梦》的解读时说，“经学家看见《易》，道学家看见淫，才子看见缠绵，革命家看见排满，流言家看见宫闱秘事”，请结合这段话说明读者的“期待视界”在艺术接受中的作用。","ans":"（1）期待视界是艺术接受的主体性的重要体现。（2）期待视界对于作品是一种先在结构，它能够对读者的接受活动进行引导和制约。（3）由于期待视界的影响，任何接受者对一件艺术品的欣赏都不可能完整地得到创造者的意象，不同接受者对同一件艺术品的接受也不可能完全相同。","exp":"鲁迅这段话生动说明“期待视界”对艺术接受的深刻影响。同一部《红楼梦》，经学家带着儒家经典的期待视野看到周易思想，道学家带着道德训诫的期待看到淫欲，才子带着爱情的期待看到缠绵，革命家带着政治批判的期待看到排满，流言家带着猎奇的期待看到宫闱秘事。这说明接受者不是被动地接收作品，而是带着自己已有的知识背景、价值观念和审美偏好（即“期待视界”）去解读和建构作品的意义。期待视界既使接受成为可能（没有先在结构就无法理解任何文本），又对接受产生制约（使接受者只能看到“视界”允许看到的东西）。正因如此，同一部作品在不同时代、不同读者眼中呈现出不同的意义，艺术的接受永远是主体的、历史的、个性化的。","type":"案例"}]},{"id":"2604","year":2026,"month":4,"label":"2026年4月","choice":[{"no":1,"t":"美学研究的中心问题和主要对象是","o":["美和美的本质","审美经验","人和世界之间的审美关系","审美心理"],"a":[2],"exp":"现代美学认为，美学研究的核心不是抽象的 \"美\" 本身，而是人与世界之间的审美关系。这一观点超越了传统美学只关注美的本质或审美心理的局限，将审美活动置于人与世界互动的关系中进行考察，更全面地把握了审美现象的本质。选项 A 是传统美学的研究对象，选项 B 和 D 只是美学研究的部分内容，而非中心问题。","multi":false},{"no":2,"t":"审美活动实质上是主体与客体之间的一种","o":["反映的关系","静态的关系","动态的关系","抽象的关系"],"a":[2],"exp":"审美活动不是主体对客体的静态反映，而是主体与客体之间相互作用、相互交融的动态过程。在审美活动中，主体通过感知、想象、情感等心理活动与客体进行互动，客体也在这一过程中展现其审美价值。这种动态关系是审美活动区别于认识活动和实践活动的重要特征。","multi":false},{"no":3,"t":"将人的需要区分为生存需要、享受需要和发展需要三个层次的是","o":["恩格斯","马克思","马斯洛","黑格尔"],"a":[0],"exp":"恩格斯在《自然辩证法》等著作中将人的需要划分为三个层次：生存需要（维持生命的基本需要）、享受需要（提高生活质量的需要）和发展需要（实现自我潜能的需要）。这一划分对理解审美需要的产生和发展具有重要意义。需要注意与马斯洛的需要层次理论区分，马斯洛提出的是生理、安全、归属与爱、尊重、自我实现五个层次。","multi":false},{"no":4,"t":"在主体审美心理结构中必然处于最高位置的是","o":["审美需要","审美理想","审美经验","审美趣味"],"a":[1],"exp":"审美理想是主体在长期审美实践中形成的关于美的最高范型和标准，它指导和制约着主体的审美活动，在审美心理结构中处于统摄地位。审美需要是审美活动的动力，审美经验是审美活动的结果，审美趣味是主体的审美偏好，它们都受到审美理想的指导和制约。","multi":false},{"no":5,"t":"审美活动之所以吸引人、感染人，是因为它所展开的是一个","o":["情感的世界","意象的世界","美妙的世界","属人的世界"],"a":[3],"exp":"审美活动的根本魅力在于它展现了一个属人的世界，即体现了人的本质力量和价值的世界。在审美活动中，人不仅观照对象，更在对象中直观自身，确证自己的本质力量。情感、意象、美妙都是审美世界的特征，但最根本的是它的属人性，即审美世界是人的本质力量的对象化。","multi":false},{"no":6,"t":"就目前的研究来看，在原始社会中促进审美发生最重要的中介因素是","o":["种族繁衍活动","生产劳动","游戏活动","巫术礼仪活动"],"a":[3],"exp":"人类学研究表明，原始巫术礼仪活动是促进审美发生最重要的中介因素。巫术活动中包含了原始人对世界的想象性掌握，孕育了最早的艺术形式和审美意识。生产劳动是审美发生的根本动因，但巫术礼仪是直接的中介，它将原始人的实用活动与审美活动联系起来，推动了审美意识的独立发展。","multi":false},{"no":7,"t":"能够使人的本质力量得到最充分的显露的是","o":["认识活动","创造活动","审美活动","宗教活动"],"a":[2],"exp":"审美活动是人的本质力量最充分的显现方式。在审美活动中，人摆脱了实用功利和认识目的的束缚，全面地展现自己的感知、想象、情感、理解等本质力量。认识活动主要展现人的理性能力，创造活动受到实用目的制约，宗教活动则是人的本质力量的异化，只有审美活动使人的本质力量得到自由而全面的展现。","multi":false},{"no":8,"t":"审美主体在审美活动中所指涉的客体是","o":["审美对象","审美情绪","审美理想","审美意象"],"a":[0],"exp":"审美对象是审美活动中主体所观照的客体，它不同于一般的客观事物，而是在审美关系中向主体显现的具有审美价值的对象。审美情绪是主体的心理状态，审美理想是主体的审美标准，审美意象是主体在审美活动中构建的意识内容，它们都不是客体。","multi":false},{"no":9,"t":"古希腊人乃至整个西方最主要的思维方式是","o":["形象思维","象数思维","抽象思维","直觉思维"],"a":[2],"exp":"古希腊哲学奠定了西方抽象思维的传统，强调概念、判断、推理的逻辑思维方式。这种思维方式追求普遍性、必然性和确定性，对西方科学和哲学的发展产生了深远影响。形象思维、象数思维、直觉思维是中国传统思维的重要特征，与西方思维方式形成鲜明对比。","multi":false},{"no":10,"t":"表现出对象与主体之间的和谐的是","o":["优美感的心理特征","荒诞感的心理特征","悲剧感的心理特征","喜剧感的心理特征"],"a":[0],"exp":"优美是最基本的审美形态之一，其核心特征是和谐。优美感表现为主体与对象之间的和谐统一，主体在欣赏优美对象时感到轻松、愉悦、宁静，没有冲突和痛感。荒诞感、悲剧感、喜剧感都包含着不同程度的矛盾、冲突和不和谐，与优美感的和谐特征形成对比。","multi":false},{"no":11,"t":"认为美具有完整、和谐、鲜明三个要素的美学家是","o":["博克","西塞罗","康德","托马斯・阿奎那"],"a":[3],"exp":"中世纪经院哲学家托马斯・阿奎那在《神学大全》中提出美的三个要素：完整（事物的完善性）、和谐（各部分的比例适当）、鲜明（色彩的光彩）。这一观点继承了古希腊以来的形式美学传统，对后世美学产生了重要影响。博克主要研究崇高与优美，西塞罗强调美在得体，康德提出美的四个契机。","multi":false},{"no":12,"t":"以下属于马克思关于喜剧的论断的是","o":["喜剧情感是一种强烈的生命感","喜剧使 \"人类能够愉快地和自己的过去诀别\"","喜剧是对于比较坏的人的模仿","喜剧将那无价值的撕破给人看"],"a":[1],"exp":"马克思在《黑格尔法哲学批判导言》中提出：\"喜剧使人类能够愉快地和自己的过去诀别。\" 这一论断揭示了喜剧的社会批判功能和历史进步意义。选项 A 是柏格森的观点，选项 C 是亚里士多德的观点，选项 D 是鲁迅的观点。","multi":false},{"no":13,"t":"在西方的审美形态中，体现着西方人在丑面前的无奈的是","o":["荒诞","崇高","喜剧","悲剧"],"a":[0],"exp":"荒诞是现代西方重要的审美形态，它表现了现代人对世界的无意义、非理性和异化的体验，体现了人在荒诞世界面前的无奈、困惑和焦虑。崇高包含着痛感转化为快感的过程，喜剧通过笑来否定丑，悲剧通过抗争来超越命运，它们都包含着主体的能动性，而荒诞则更多地表现了主体在丑面前的无奈。","multi":false},{"no":14,"t":"西方古代的思维方式最基本的思维单位是","o":["概念","象数","物数","物象"],"a":[0],"exp":"西方古代哲学以概念为最基本的思维单位，通过概念的抽象、分析和推演来把握世界。这种思维方式始于古希腊哲学，特别是柏拉图的理念论和亚里士多德的逻辑学。象数、物数、物象是中国古代思维的基本单位，与西方的概念思维形成鲜明对比。","multi":false},{"no":15,"t":"在西方近代美学中用来指审美经验的术语是","o":["趣味","兴趣","品味","兴味"],"a":[0],"exp":"\"趣味\"（taste）是西方近代美学中用来指审美经验和审美判断力的核心术语。18 世纪英国经验主义美学家如休谟、博克等广泛使用这一术语，讨论审美趣味的标准、特征和来源。\"兴趣\" 是康德美学中的重要概念，\"品味\" 和 \"兴味\" 更多是中国美学的术语。","multi":false},{"no":16,"t":"总是与审美感知紧紧地交织在一起的是","o":["感觉","理解","想象","情感"],"a":[3],"exp":"情感是审美活动中最活跃的因素，它始终与审美感知交织在一起。审美感知不是纯粹的感官反映，而是渗透着情感的体验；情感也不是抽象的情绪，而是在感知对象的过程中产生和发展的。感觉是感知的基础，理解和想象是审美活动的重要因素，但它们与感知的交织不如情感那样紧密和直接。","multi":false},{"no":17,"t":"提出 \"取象曰比，取义曰兴\" 的是","o":["庄子","皎然","严羽","陆机"],"a":[1],"exp":"唐代诗僧皎然在《诗式》中提出：\"取象曰比，取义曰兴。\" 这是对中国传统诗学中 \"比兴\" 概念的重要阐释，区分了比喻（取象）和起兴（取义）的不同特征。庄子是道家思想家，严羽著有《沧浪诗话》，陆机著有《文赋》，他们都没有提出这一论断。","multi":false},{"no":18,"t":"将美学称为 \"艺术哲学\" 的是","o":["黑格尔","康德","费希特","席勒"],"a":[0],"exp":"黑格尔在《美学》讲演录中将美学定义为 \"艺术哲学\"，认为美学的研究对象是美的艺术，美是理念的感性显现。黑格尔的美学体系以艺术为中心，系统研究了艺术的本质、发展和类型。康德的美学主要研究审美判断力，席勒关注审美教育，费希特的哲学对美学影响较小。","multi":false},{"no":19,"t":"艺术品之所以成为艺术品的关键层次是","o":["符号","情感","理解","意象"],"a":[3],"exp":"意象是艺术品的核心层次，是艺术品之所以成为艺术品的关键。艺术品通过物质符号传达情感和意义，但真正使艺术品具有审美价值的是它所构建的意象世界。符号是载体，情感是内容，理解是功能，只有意象才是艺术品的本体存在。","multi":false},{"no":20,"t":"将艺术品区分为语音层、语义层、图式层、客体层的美学家是","o":["罗曼・英伽登","艾布拉姆斯","斯宾塞","苏珊・朗格"],"a":[0],"exp":"波兰现象学美学家罗曼・英伽登在《文学的艺术作品》中将文学作品分为四个层次：语音层、语义层、图式化外观层、客体层。这一层次理论对现代文艺理论产生了深远影响。艾布拉姆斯提出艺术四要素理论，斯宾塞是游戏说的代表，苏珊・朗格是符号论美学的代表。","multi":false},{"no":21,"t":"用一些纯粹的形式符号来唤起读者审美情感的意象属于","o":["兴象","喻象","仿象","抽象"],"a":[3],"exp":"抽象是意象的一种类型，它不直接模仿客观事物，也不使用比喻或起兴，而是通过纯粹的形式符号（如线条、色彩、声音等）来唤起审美情感。抽象艺术是现代艺术的重要特征，它摆脱了再现的束缚，直接以形式表达情感和意义。兴象是情景交融的意象，喻象是比喻性意象，仿象是模仿性意象。","multi":false},{"no":22,"t":"以下属于空间艺术的是","o":["文学","绘画","戏剧","音乐"],"a":[1],"exp":"根据艺术形象的存在方式，艺术可分为空间艺术、时间艺术和时空艺术。绘画、雕塑、建筑等属于空间艺术，它们的形象在空间中并列展开。音乐、文学属于时间艺术，形象在时间中先后承续。戏剧、影视属于时空综合艺术。","multi":false},{"no":23,"t":"从意象的类型上看，左拉、福楼拜、莫泊桑的小说中的意象属于","o":["兴象","喻象","仿象","抽象"],"a":[2],"exp":"左拉、福楼拜、莫泊桑是法国批判现实主义作家，他们的小说注重客观再现现实生活，其意象属于仿象类型。仿象是主体通过模仿对象世界的形态创造的意象，具有客观性和再现性。兴象是中国古典美学的概念，喻象具有比喻性，抽象是形式化的，都不符合现实主义文学的特征。","multi":false},{"no":24,"t":"艺术符号对其意义的表达只能通过的方法是","o":["暗喻与拟人","比喻与象征","夸张与变形","象征与暗示"],"a":[3],"exp":"艺术符号不同于科学符号，它不直接指称意义，而是通过象征与暗示的方式来表达意义。艺术符号具有多义性和含蓄性，它不直接说出意义，而是让接受者在体验中领悟。暗喻、拟人、比喻、夸张、变形都是具体的艺术手法，而象征与暗示是艺术符号表达意义的根本方法。","multi":false},{"no":25,"t":"黑格尔认为凝聚意象的核心的是","o":["感知","想象","情感","理解"],"a":[2],"exp":"黑格尔在《美学》中认为，情感是凝聚意象的核心，艺术家的情感赋予意象以生命和灵魂。他强调艺术是 \"情致\" 的表现，情致是渗透着理性内容的情感，它使意象成为有机统一的整体。感知、想象、理解都是创造意象的重要因素，但情感是核心和灵魂。","multi":false},{"no":26,"t":"在中国，首次出现 \"美育\" 一词是在","o":["春秋时期","战国时期","唐宋时期","建安时期"],"a":[3],"exp":"\"美育\" 一词最早出现在建安时期徐干的《中论・艺纪》中，其中提到：\"美育群材，其犹人之于艺乎？\" 这是中国文献中 \"美育\" 一词的首次出现。虽然中国古代有丰富的美育思想，但 \"美育\" 这个术语的出现是在建安时期。","multi":false},{"no":27,"t":"具有审美价值的对象在感化人时首先向人展现的是","o":["理智形式","能动形式","感性对象","认知对象"],"a":[2],"exp":"审美教育的特点是感性的，具有审美价值的对象首先以感性形象作用于人，通过人的感官和情感体验来发挥感化作用。这是美育区别于智育和德育的重要特征。理智形式、认知对象是智育的特征，能动形式是实践的特征。","multi":false},{"no":28,"t":"王国维的将美育与德育、智育、体育并称为 \"四育\" 的文章是","o":["《论教育之宗旨》","《谈美感教育》","《以美育代宗教》","《趣味教育与教育趣味》"],"a":[0],"exp":"王国维在 1906 年发表的《论教育之宗旨》中，首次在中国教育史上将美育与德育、智育、体育并列为 \"四育\"，提出完全之教育在于培养 \"完全之人物\"。《谈美感教育》是朱光潜的文章，《以美育代宗教》是蔡元培的著名演讲，《趣味教育与教育趣味》是梁启超的文章。","multi":false},{"no":29,"t":"中国古代以乐感化的传统，最早可以追溯到","o":["尧的时代","舜的时代","夏朝","商朝"],"a":[1],"exp":"中国古代的乐教传统最早可以追溯到舜的时代。《尚书・舜典》记载：\"帝曰：夔！命汝典乐，教胄子。\" 舜任命夔掌管乐教，这是中国文献中关于乐教的最早记载。乐教是中国古代美育的主要形式，对中国文化和教育产生了深远影响。","multi":false},{"no":30,"t":"在中国的上古时期，\"乐\" 是","o":["诗、画、舞的统称","剧、歌、舞的统称","诗、歌、舞的统称","诗、歌、剧的统称"],"a":[2],"exp":"在中国上古时期，\"乐\" 是诗、歌、舞三位一体的综合艺术形式。《毛诗序》说：\"诗者，志之所之也，在心为志，发言为诗。情动于中而形于言，言之不足故嗟叹之，嗟叹之不足故永歌之，永歌之不足，不知手之舞之，足之蹈之也。\" 这说明上古之乐是诗、歌、舞的统一体。\n二、多项选择题（本大题共 5 小题，每小题 2 分，共 10 分）","multi":false},{"no":31,"t":"审美活动所追求的价值","o":["内在地包含着 \"真\"","内在地包含着 \"善\"","主要着眼于既定的现实关系","内在地包含着人的 \"终极关怀\"","内在地包含着对现存世界的根本否定"],"a":[0,1,3],"exp":"审美活动追求的是真善美的统一，它内在地包含着 \"真\"（对世界的真实把握）和 \"善\"（对人的价值的肯定），同时也包含着人的 \"终极关怀\"（对人生意义的追寻）。选项 C 错误，审美活动超越了既定的现实关系；选项 E 错误，审美活动不是对现存世界的根本否定，而是对现存世界的超越和升华。","multi":true},{"no":32,"t":"鲁迅曾把汉字的审美效果总结为","o":["状美以通神","意美以感心","音美以感耳","形美以感目","体美以醒脑"],"a":[1,2,3],"exp":"鲁迅在《汉文学史纲要》中指出汉字具有三美：\"意美以感心，一也；音美以感耳，二也；形美以感目，三也。\" 这一论述精辟地概括了汉字的审美特征：意义之美作用于心灵，声音之美作用于听觉，形体之美作用于视觉。","multi":true},{"no":33,"t":"康德认为审美经验是以下哪些认识能力的自由游戏","o":["感性","知性","情感","通感","想象力"],"a":[1,4],"exp":"康德在《判断力批判》中提出，审美经验是想象力与知性的自由游戏。想象力提供感性直观，知性提供概念规则，在审美活动中，想象力不受概念的束缚，与知性自由协调，产生审美愉悦。感性是认识的低级阶段，情感是审美经验的结果，通感是审美经验的特征，它们都不是参与自由游戏的认识能力。","multi":true},{"no":34,"t":"在先秦儒家那里，审美活动的目的主要是为了实现","o":["天与天之间的和谐","天与人之间的和谐","人与人之间的和谐","阴与阳之间的和谐","天与地之间的和谐"],"a":[1,2],"exp":"先秦儒家美学强调审美活动的社会功能，认为审美和艺术的目的是实现 \"天人合一\"（天与人的和谐）和 \"人际和谐\"（人与人的和谐）。孔子提出 \"兴观群怨\"，荀子提出 \"乐和同\"，都是为了通过审美活动实现社会和谐和天人和谐。其他选项不是儒家美学关注的核心。","multi":true},{"no":35,"t":"席勒的美育理论的重要性主要体现在","o":["把美育纳入宗教的范畴","从哲学高度解释美育的独特目的","把美育的目的与审美活动的性质内在地统一起来","明确揭示美育的价值是完满人性","回答了完满人性的方式，即人性统一的根据就在于自身"],"a":[1,2,3,4],"exp":"席勒在《美育书简》中系统阐述了美育理论，其重要性体现在：从哲学高度解释了美育的独特目的（B），将美育目的与审美活动的自由性质统一起来（C），明确提出美育的价值在于造就完满的人性（D），指出人性统一的根据在于人自身（E）。选项 A 错误，席勒没有把美育纳入宗教范畴，相反，他强调美育的独立性。","multi":true}],"essay":[{"no":36,"t":"简述美学思想与审美意识的关系","ans":"(1) 审美意识是美学思想得以产生的前提。审美意识是人类在长期审美实践中形成的对美的自发的、零散的、感性的认识，它为美学思想的产生提供了素材和基础。\n(2) 美学思想奠基于审美意识，但有进一步的发展。美学思想是思想家对审美现象进行自觉的、系统的、理性的思考的结果，它超越了审美意识的自发性和零散性，形成了理论化的观点和学说。","exp":"审美意识是初级的、自发的审美认识，存在于每一个具有审美能力的人的意识中；美学思想是高级的、自觉的审美理论，是美学家对审美现象进行反思和概括的产物。二者的关系是：审美意识是美学思想的源泉和基础，美学思想是审美意识的升华和系统化。没有审美意识，美学思想就成为无源之水；没有美学思想，审美意识就只能停留在自发阶段。","type":"简答"},{"no":37,"t":"简述审美活动作为价值活动的特殊性","ans":"(1) 审美活动所追求的不是一般的价值，而是能满足人的心灵需要的精神价值。审美活动超越了物质功利，满足的是人的精神需要，使人获得心灵的愉悦和满足。\n(2) 审美活动所追求的不是一般的精神价值，而是能够启迪人领悟人生真谛的独特精神价值。审美价值不仅是娱乐和消遣，更重要的是它能使人超越日常生存，领悟人生的意义和价值，获得精神的升华。","exp":"审美活动是一种特殊的价值活动，其特殊性表现在：第一，它是精神价值而非物质价值，不具有直接的实用性；第二，它是独特的精神价值，不同于道德价值和认识价值，它通过感性形象的体验使人领悟人生真谛。审美价值的独特性在于它的无功利性、超越性和体验性。","type":"简答"},{"no":38,"t":"简述审美惊异的主要特征","ans":"(1) 审美惊异不是一种理性的求知欲，而是一种鲜活的生命感。审美惊异不是对未知事物的好奇和探究，而是主体被对象所吸引，产生的一种活生生的体验，它唤醒了主体的生命意识。\n(2) 审美惊异的产生既依赖于主体一定的自身条件，也依赖于对象本身一定的客观条件。从主体方面说，需要具备一定的审美能力和审美态度；从客体方面说，对象需要具有独特性和吸引力，能够引起主体的注意和兴趣。","exp":"审美惊异是审美活动的起点，它不同于科学研究中的惊异。科学惊异是求知欲的表现，指向对事物本质的认识；审美惊异是生命感的表现，指向对事物审美价值的体验。审美惊异的产生是主客体相互作用的结果，既需要主体的审美能力，也需要客体的审美属性。","type":"简答"},{"no":39,"t":"简述夏夫兹博里的 \"内在感官说\"","ans":"(1) 夏夫兹博里认为，人天生就具有审辨美丑和善恶的能力，他把这种能力称为 \"内在的感官\"。这种内在感官是人类特有的，它使人能够直接感知美和善，不需要经过推理和思考。\n(2) 他认为这种内在感官不同于五官感觉，是一种第六感官。外在感官只能接受简单的感觉印象，内在感官则能够感知美、和谐、秩序等复杂的审美价值，它是理性与感性的统一。","exp":"夏夫兹博里是 18 世纪英国经验主义美学家，他提出的 \"内在感官说\" 是近代美学的重要理论。这一理论试图解决审美判断的普遍性问题，认为人具有共同的审美能力，保证了审美判断的普遍有效性。\"内在感官说\" 对后来的哈奇生、休谟等美学家产生了重要影响，是审美直觉理论的早期形态。","type":"简答"},{"no":40,"t":"简述审美情感与一般情感的差异","ans":"(1) 一般情感具有较强的个人色彩，审美情感则具有一定的社会性和理性特征。一般情感往往是个人特定境遇的产物，具有私人性；审美情感则是对具有普遍审美价值的对象的反应，包含着社会的、理性的内容，能够为他人所分享和理解。\n(2) 一般情感常常产生于本能需要的满足，审美情感则经过了超越性的反思和判断。一般情感与生理需要和实用目的紧密相关，具有直接的功利性；审美情感则超越了生理欲望和实用目的，是对对象审美价值的体验，具有无功利性和超越性。","exp":"审美情感是一种特殊的情感，它不同于日常生活中的一般情感。审美情感的特殊性在于：它具有社会性和普遍性，不是纯粹个人的情绪；它具有超越性和精神性，不是生理欲望的满足。审美情感是经过 \"审美距离\" 过滤的情感，是在审美观照中产生的高级情感。","type":"简答"},{"no":41,"t":"简述美育的目的","ans":"(1) 美育的最高目的是造就审美的人。审美的人是具有敏锐的审美能力、健康的审美趣味、崇高的审美理想的人，他们能够以审美的态度对待生活和世界。\n(2) 美育不仅要培养人对于美的热爱，还能使人得到全面的发展。美育通过陶冶人的情感、完善人的心理结构、提升人的精神境界，促进人的感性与理性的协调发展，造就全面发展的人。","exp":"美育的根本目的是人的全面发展。通过审美教育，人不仅获得了欣赏美和创造美的能力，更重要的是，人的感性与理性得到了协调发展，摆脱了片面性和异化状态，成为完整的人。造就审美的人，就是造就具有自由个性和完善人格的人，这是美育的终极目标。","type":"简答"},{"no":42,"t":"试论喜剧的基本特征","ans":"(1) 喜剧具有不和谐、悖谬的形式特征。喜剧的对象往往是违背正常秩序、不符合常规的事物，表现为形式与内容、现象与本质、动机与效果的矛盾和悖谬。这种不和谐和悖谬是喜剧性的根源，它使人感到意外和惊奇，从而产生笑。\n(2) 喜剧中包含着深刻的社会现实内容，具有一定的社会批判性。喜剧不是纯粹的娱乐，它通过笑来揭露和批判社会生活中的虚假、丑恶和荒谬。优秀的喜剧作品总是具有深刻的思想内容和鲜明的社会批判精神，它使人们在笑声中认识社会现实。\n(3) 喜剧的情感形式表现主要是笑。笑是喜剧最直接、最显著的特征，是喜剧美感的基本形式。喜剧的笑具有多种形态，如讽刺的笑、幽默的笑、滑稽的笑等。笑既是喜剧的情感表达，也是喜剧的批判武器。\n(4) 喜剧是否定性和肯定性的统一。喜剧通过否定旧的、过时的、丑恶的事物，肯定新的、进步的、美好的事物。它在嘲笑旧事物的同时，也表达了对美好未来的向往和追求。马克思说喜剧使 \"人类能够愉快地和自己的过去诀别\"，正是体现了这种否定与肯定的统一。","exp":"喜剧是重要的审美形态之一，其基本特征体现在形式、内容、情感和价值取向四个方面。从形式上看，喜剧以不和谐、悖谬为特征，通过夸张、变形、巧合等手法制造喜剧效果；从内容上看，喜剧具有深刻的社会批判性，是反映现实、批判现实的重要方式；从情感上看，喜剧以笑为基本表达形式，笑是喜剧美感的核心；从价值取向上看，喜剧是否定性与肯定性的统一，它在否定中包含着肯定，在批判中包含着理想。理解喜剧的基本特征，有助于我们更好地欣赏和创造喜剧艺术。","type":"论述"},{"no":43,"t":"以《西游记》中的孙悟空形象为例，说明艺术意象的基本特征","ans":"艺术意象具有四个基本特征：虚拟性、直观性、想象性、情感性。下面以《西游记》中的孙悟空形象为例进行说明：\n(1) 虚拟性：艺术意象不是客观实在本身，而是艺术家虚构的产物。孙悟空形象具有鲜明的虚拟性：他是石猴出世，拥有七十二变、筋斗云等超凡能力，能大闹天宫、降妖伏魔，这些都是现实中不可能存在的，是作家吴承恩虚构的艺术世界。孙悟空的形象虽然来源于现实生活中的猴子和人的特征，但经过艺术加工和虚构，成为一个超越现实的艺术意象。\n(2) 直观性：艺术意象是感性的、具体的，可以直接为主体的感官所把握。孙悟空的形象具有鲜明的直观性：他 \"尖嘴缩腮，金睛火眼\"，头戴紧箍咒，手持金箍棒，这些具体的感性特征使读者一提到孙悟空就能在脑海中浮现出他的形象。艺术意象不是抽象的概念，而是具体可感的形象，孙悟空的直观性使他成为中国文学中最鲜活的艺术形象之一。\n(3) 想象性：艺术意象是艺术家想象活动的产物，想象是意象创造的核心。孙悟空形象充分体现了艺术意象的想象性：从石猴出世到大闹天宫，从保护唐僧西天取经历经九九八十一难到最终修成正果，整个形象的塑造都充满了丰富的想象。七十二变、筋斗云、火眼金睛等都是想象力的结晶，正是通过丰富的想象，孙悟空才成为一个超越现实、充满魅力的艺术形象。\n(4) 情感性：艺术意象总是包含着艺术家的情感，情感是意象的灵魂。孙悟空形象凝聚着作者和读者的丰富情感：他的机智勇敢、疾恶如仇、敢于反抗的性格，寄托了人民对英雄的向往和赞美；他的大闹天宫体现了反抗封建权威的精神，表达了人民对自由和平等的追求；他对师父的忠诚、对师弟的情义，体现了美好的人性。正是这些丰富的情感内涵，使孙悟空的形象具有强大的艺术感染力。","exp":"孙悟空是中国古典文学中最成功的艺术形象之一，完美地体现了艺术意象的四个基本特征。虚拟性使他超越了现实的局限，成为自由的艺术存在；直观性使他具有鲜明的感性特征，易于被读者接受和记忆；想象性使他充满了神奇色彩和艺术魅力；情感性使他具有丰富的精神内涵和强大的感染力。这四个特征相互联系、有机统一，共同构成了孙悟空这一不朽的艺术意象。","type":"案例"}]}]};
